def longest_balanced_substring(s):
    """
    Finds the length of the longest balanced substring in the given string s.
    A balanced substring has an equal number of opening and closing parentheses.
    """
    max_len = 0
    stack = [-1]  # Initial index to handle base case

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_len = max(max_len, i - stack[-1])

    return max_len

import math


def find_perfect_squares(numbers):
    """
    Returns a list of unique perfect squares from the input list.
    """
    perfect_squares = set()
    for num in numbers:
        if num >= 0:  # only non-negative numbers can be perfect squares
            root = int(math.isqrt(num))
            if root * root == num:
                perfect_squares.add(num)
    return sorted(perfect_squares)

from typing import List


def generate_balanced_bracket_sequences(n: int) -> List[str]:
    """
    Generate all combinations of n pairs of balanced parentheses.
    """
    def backtrack(s='', left=0, right=0):
        if len(s) == 2 * n:
            result.append(s)
            return
        if left < n:
            backtrack(s + '(', left + 1, right)
        if right < left:
            backtrack(s + ')', left, right + 1)

    result = []
    backtrack()
    return result

