def move_zeros_to_beginning(arr):
    """
    Moves all zeros in the array to the beginning while maintaining
    the relative order of non-zero elements.
    """
    zero_count = 0
    non_zero_list = []

    for i in arr:
        if i == 0:
            zero_count += 1
        else:
            non_zero_list.append(i)

    return [0] * zero_count + non_zero_list

