def longest_increasing_subsequence(arr):
    """
    Returns the length of the longest strictly increasing subsequence in the given array.
    """
    if not arr:
        return 0

    length = len(arr)
    lis = [1] * length

    for i in range(1, length):
        for j in range(i):
            if arr[i] > arr[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    return max(lis)

def generate_base_pairs():
    """
    Returns a list of all possible valid DNA base pairs based on given rules.
    """
    bases = ['A', 'T', 'C', 'G']
    valid_pairs = []
    for i in bases:
        for j in bases:
            if (i == 'A' and j == 'T') or (i == 'T' and j == 'A') or (i == 'C' and j == 'G') or (i == 'G' and j == 'C'):
                valid_pairs.append(f"{i}{j}")
    return valid_pairs

def camel_to_snake(camel_str):
    """
    Converts a given camel case string to snake case.
    """
    snake_str = ''
    for char in camel_str:
        if char.isupper():
            if snake_str:
                snake_str += '_'
            snake_str += char.lower()
        else:
            snake_str += char
    return snake_str

