def remove_duplicates_sorted(nums):
    """
    Removes duplicates from a sorted list of integers while maintaining the order.
    """
    if not nums:
        return nums
    unique_nums = [nums[0]]
    for num in nums[1:]:
        if num != unique_nums[-1]:
            unique_nums.append(num)
    return unique_nums

def longest_subarray_with_sum_zero(arr):
    """
    Returns the length of the longest continuous subarray with sum equal to zero.

    :param arr: List of integers
    :return: Length of the longest subarray with sum zero
    """
    # Dictionary to store the cumulative sum and its index
    cum_sum_map = {}
    cum_sum = 0
    max_len = 0

    for index, value in enumerate(arr):
        cum_sum += value

        if cum_sum == 0:
            max_len = index + 1
        elif cum_sum in cum_sum_map:
            max_len = max(max_len, index - cum_sum_map[cum_sum])
        else:
            cum_sum_map[cum_sum] = index

    return max_len

