def is_valid_ipv4(ip: str) -> bool:
    """
    Determines if the given string is a valid IPv4 address.
    """
    parts = ip.split('.')

    # Check if there are exactly 4 parts
    if len(parts) != 4:
        return False

    for part in parts:
        # Check if part is numeric and within the range 0-255
        if not part.isdigit():
            return False

        num = int(part)
        if num < 0 or num > 255:
            return False

        # Check for leading zeros
        if part != "0" and part.startswith("0"):
            return False

    return True

def reverse_letters_in_words(input_string):
    """
    Reverses the letters in each word of a string while retaining the original word order.
    """
    if not input_string:
        return ""

    words = input_string.split(' ')
    reversed_words = [word[::-1] for word in words]
    return ' '.join(reversed_words)

def count_status_codes(logs: list) -> dict:
    """
    Processes a list of HTTP request logs and returns a dictionary with the count 
    of occurrences for each HTTP status code.
    """
    status_code_count = {}

    for log in logs:
        status_code = log.split()[-1]
        if status_code in status_code_count:
            status_code_count[status_code] += 1
        else:
            status_code_count[status_code] = 1

    return status_code_count

