def substring_count(main_str, sub_str):
    """
    Returns the number of times the substring appears in the given string.
    """
    count = 0
    for i in range(len(main_str) - len(sub_str) + 1):
        if main_str[i:i+len(sub_str)] == sub_str:
            count += 1
    return count

