import bisect


def longest_increasing_subsequence(prices: list) -> int:
    """
    Returns the length of the longest increasing subsequence in the list of prices.
    """
    if not prices:
        return 0

    dp = []

    for price in prices:
        pos = bisect.bisect_left(dp, price)
        if pos < len(dp):
            dp[pos] = price
        else:
            dp.append(price)

    return len(dp)

def check_permutation(str1: str, str2: str) -> bool:
    """
    Check if str2 is a permutation of str1.
    """
    if len(str1) != len(str2):
        return False

    char_count = {}

    for char in str1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in str2:
        if char in char_count:
            char_count[char] -= 1
            if char_count[char] == 0:
                del char_count[char]
        else:
            return False

    return len(char_count) == 0

