def follows_pattern(pattern: str, s: str) -> bool:
    """
    Determines if the given string s follows the specified pattern.

    Args:
    pattern (str): The pattern string where each character represents a particular word.
    s (str): The string composed of words separated by spaces.

    Returns:
    bool: True if the pattern matches the given string s, otherwise False.
    """
    words = s.split()
    if len(pattern) != len(words):
        return False

    char_to_word = {}
    word_to_char = {}

    for char, word in zip(pattern, words):
        if char in char_to_word:
            if char_to_word[char] != word:
                return False
        else:
            char_to_word[char] = word

        if word in word_to_char:
            if word_to_char[word] != char:
                return False
        else:
            word_to_char[word] = char

    return True

def longest_consecutive_segment(s: str) -> int:
    """
    This function takes a string s and returns the length of the longest consecutive character segment.
    """
    max_length = 1
    current_length = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

from typing import List


def max_non_adjacent_sum(nums: List[int]) -> int:
    """
    Calculate the maximum sum of non-adjacent numbers in the list.
    """
    if not nums:
        return 0

    if len(nums) == 1:
        return max(0, nums[0])

    prev1 = 0
    prev2 = 0

    for num in nums:
        current = max(prev1, prev2 + num)
        prev2 = prev1
        prev1 = current

    return prev1

