import math


def find_roots(a, b, c):
    """
    Returns a tuple containing the real roots of the quadratic equation ax^2 + bx + c = 0.
    If there are no real roots, return an empty tuple.
    """
    discriminant = b**2 - 4*a*c

    if discriminant < 0:
        return ()
    elif discriminant == 0:
        root = -b / (2*a)
        return (root,)
    else:
        root1 = (-b + math.sqrt(discriminant)) / (2*a)
        root2 = (-b - math.sqrt(discriminant)) / (2*a)
        return (root1, root2)

