def balancedBrackets(s: str):
    """
    This function checks if the given string s with various types of brackets 
    ('{', '}', '(', ')', '[', ']') is properly balanced.
    """
    stack = []
    opening_brackets = {'{', '(', '['}
    closing_brackets = {'}': '{', ')': '(', ']': '['}

    for char in s:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack or stack.pop() != closing_brackets[char]:
                return False
    return not stack

def rock_paper_scissors(user1, user2):
    """
    Determines the winner of a rock, paper, scissors game.

    Args:
    user1 (str): Choice of the first player (rock/paper/scissors).
    user2 (str): Choice of the second player (rock/paper/scissors).

    Returns:
    str: Result of the game.
    """
    if user1 == user2:
        return f"Both players selected {user1}. It's a tie!"
    elif user1 == "rock":
        if user2 == "scissors":
            return "Rock smashes scissors! Player 1 wins!"
        else:
            return "Paper covers rock! Player 2 wins."
    elif user1 == "paper":
        if user2 == "rock":
            return "Paper covers rock! Player 1 wins!"
        else:
            return "Scissors cuts paper! Player 2 wins."
    elif user1 == "scissors":
        if user2 == "paper":
            return "Scissors cuts paper! Player 1 wins!"
        else:
            return "Rock smashes scissors! Player 2 wins."

def get_first_last(arr):
    """
    Returns a tuple with the first and last elements of the array.
    If the array is empty, returns None.
    If there is only one element in the array, returns a tuple with that element twice.
    """
    if len(arr) == 0:
        return None
    elif len(arr) == 1:
        return (arr[0], arr[0])
    else:
        return (arr[0], arr[-1])

