def factorial(n):
    """
    Returns the factorial of a non-negative integer n 
    using a recursive algorithm.
    """
    # Base case: factorial of 0 or 1 is 1
    if n == 0 or n == 1:
        return 1

    # Recursive case: factorial of n is n * factorial of (n-1)
    return n * factorial(n - 1)

def rock_paper_scissors(player1, player2):
    """
    Determines the winner of a Rock, Paper, Scissors game.

    Args:
    player1: str, one of "rock", "paper", "scissors".
    player2: str, one of "rock", "paper", "scissors".

    Returns:
    str, result of the game - "Player 1 wins", "Player 2 wins", or "It's a tie".
    """
    winning_combinations = {
        'rock': 'scissors',
        'scissors': 'paper',
        'paper': 'rock'
    }

    if player1 == player2:
        return "It's a tie"
    elif winning_combinations[player1] == player2:
        return "Player 1 wins"
    else:
        return "Player 2 wins"

