def compare_strings_as_numbers(str1, str2):
    """
    Compares two string representations of numbers and returns the larger one.
    Raises ValueError if any of the strings is not a valid number.
    """
    try:
        num1 = float(str1)
        num2 = float(str2)
    except ValueError:
        return "Error: Both inputs must be numeric strings."

    if num1 > num2:
        return str1
    elif num1 < num2:
        return str2
    else:
        return "Both numbers are equal."

