def fibonacci(n):
    """
    Returns a list of the first n Fibonacci numbers. If n is zero or negative, returns an error message.
    """
    if n <= 0:
        return "Input must be a positive integer."

    def fib_recursive(m):
        if m == 1:
            return [0]
        elif m == 2:
            return [0, 1]
        else:
            seq = fib_recursive(m - 1)
            return seq + [seq[-1] + seq[-2]]

    return fib_recursive(n)

