def f(x):
    """
    Returns the result of the iterative function defined by:
    f(0) = 0
    f(x) = 3*f(x-1) + 2 for any x > 0
    """
    if x == 0:
        return 0
    else:
        result = 0
        for i in range(1, x + 1):
            result = 3 * result + 2
        return result

