def replace_with_next_two_letters(text):
    """
    Replaces every occurrence of a letter with the letter that is two places to the right in the alphabet.
    'z' is replaced with 'b' and 'Z' is replaced with 'B'.
    """
    return ''.join(chr(((ord(c) - 65 + 2) % 26) + 65) if c.isupper() else chr(((ord(c) - 97 + 2) % 26) + 97) if c.islower() else c for c in text)

