import math


def compute_factorial(a, b):
    """
    Returns the factorial of a, and if b is 0, returns the square root of the factorial.
    """
    try:
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError("Both a and b must be integers.")
        if a < 0:
            raise ValueError("a must be a non-negative integer.")

        c = math.factorial(a)
        if b == 0:
            return math.sqrt(c)
        return c
    except (ValueError, TypeError) as e:
        return str(e)

