def generate_checkerboard():
    """
    Generates an 8x8 checkerboard pattern using "#" and " " characters.
    """
    checkerboard = []
    for i in range(8):
        row = []
        for j in range(8):
            if (i + j) % 2 == 0:
                row.append("#")
            else:
                row.append(" ")
        checkerboard.append("".join(row))
    return "\n".join(checkerboard)

