def is_valid_ipv4_address(ip_str):
    """
    Check if the given string is a valid IPv4 address.
    """
    parts = ip_str.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        n = int(part)
        if not 0 <= n <= 255:
            return False
        if part != "0" and part.startswith("0"):
            return False
    return True

