import json


def import__lambda(event, context):
    """
    Lambda function to handle import map events.
    """
    try:
        import_map = json.loads(event['body'])

        # Get the location property from the import map
        location = import_map.get('location')

        if not location:
            raise ValueError("Location property is missing in the import map")

        # Now you can utilize the location value
        # Perform necessary operations with location

        return {
            'statusCode': 200,
            'body': json.dumps({
                'message': 'Location successfully processed',
                'location': location
            })
        }
    except json.JSONDecodeError:
        return {
            'statusCode': 400,
            'body': json.dumps({
                'message': 'Invalid JSON format'
            })
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({
                'message': str(e)
            })
        }

