def is_leap_year(year):
    """
    Returns True if the specified year is a leap year, else returns False.
    """
    if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
        return True
    else:
        return False

def is_valid_parentheses_sequence(s):
    """
    Determines if a given string is a valid parentheses sequence.

    Args:
    s (str): The input string containing '(' and ')'.

    Returns:
    bool: True if the string is a valid parentheses sequence, False otherwise.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack.pop() != '(':
                return False
    return len(stack) == 0

def T(input_object):
    """
    Handles strings by reversing them and matrices by transposing them.

    :param input_object: A string or a list of lists (matrix)
    :return: Reversed string if input is a string, transposed matrix if input is a matrix
    """
    if isinstance(input_object, str):
        return input_object[::-1]
    elif isinstance(input_object, list) and all(isinstance(i, list) for i in input_object):
        return [list(row) for row in zip(*input_object)]
    else:
        raise ValueError("Input must be either a string or a list of lists (matrix).")

