def decimal_to_binary(n: int) -> str:
    """
    Return the binary representation of n as a string.

    :param n: the non-negative integer
    :return: the binary representation as a string.
    """
    if n == 0:
        return '0'

    binary_rep = []
    while n > 0:
        binary_rep.append(str(n % 2))
        n = n // 2

    return ''.join(reversed(binary_rep))

def is_fibonacci(num: int) -> bool:
    """
    Determines if a given number is part of the Fibonacci sequence.

    :param num: The number to be checked.
    :return: True if num is a Fibonacci number, else False.
    """
    if num < 0:
        return False

    # Two checks based on Fibonacci property
    def is_perfect_square(x):
        s = int(x**0.5)
        return s * s == x

    return is_perfect_square(5*num*num + 4) or is_perfect_square(5*num*num - 4)

def number_to_excel_column(n: int) -> str:
    """
    Converts an integer column number to its corresponding Excel column title.
    """
    result = []
    while n > 0:
        n -= 1  # decrement n to handle 1-based indexing
        result.append(chr(n % 26 + ord('A')))
        n //= 26
    return ''.join(result[::-1])

def update_position(current_position, commands):
    """
    Update the player's position based on a list of movement commands.

    Parameters:
    current_position (tuple of int): A tuple (x, y) representing the player's current coordinates on the grid.
    commands (list of str): A list of movement commands, where each command is one of "UP", "DOWN", "LEFT", "RIGHT".

    Returns:
    tuple of int: A tuple (x, y) representing the player's new position after executing all the commands.
    """
    x, y = current_position

    for command in commands:
        if command == "UP" and y > 0:
            y -= 1
        elif command == "DOWN" and y < 9:
            y += 1
        elif command == "LEFT" and x > 0:
            x -= 1
        elif command == "RIGHT" and x < 9:
            x += 1

    return (x, y)

