def single_digit_sum(num: int) -> int:
    """
    Repeatedly sums the digits of a given non-negative integer until the result is a single digit.
    Returns the final single digit.
    """
    if num == 0:
        return 0

    while num >= 10:
        num = sum(int(digit) for digit in str(num))

    return num

