def reverse_string(s: str) -> str:
    """
    Returns a string where the characters are reversed while preserving the positions of the spaces.
    """
    characters = [char for char in s if char != ' ']
    result = []
    for char in s:
        if char == ' ':
            result.append(char)
        else:
            result.append(characters.pop())
    return ''.join(result)

def does_return_to_origin(moves: str) -> bool:
    """
    Determine if a robot returns to the origin after a sequence of moves.

    Parameters:
    moves (str): A sequence of characters representing the moves of the robot ('U', 'D', 'L', 'R').

    Returns:
    bool: True if the robot returns to the origin, False otherwise.
    """
    x, y = 0, 0
    for move in moves:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
    return x == 0 and y == 0

