def parse_and_build_values(input_string: str) -> list:
    """
    Parses a string containing type:value pairs and returns a list of values
    converted to their respective Python types.
    """
    result = []
    pairs = input_string.split(',')

    for pair in pairs:
        type_, value = pair.split(':')

        if type_ == 'int':
            result.append(int(value))
        elif type_ == 'float':
            result.append(float(value))
        elif type_ == 'str':
            result.append(value)
        else:
            raise ValueError(f"Unsupported type: {type_}")

    return result

