import unicodedata


def validate_unicode_chars(char_list, criteria):
    """
    Validate a list of Unicode characters based on specified criteria.

    Parameters:
    - char_list: A list of single character strings to be validated.
    - criteria: A dictionary specifying the properties and their required values.

    Returns:
    - A list of tuples. Each tuple contains a character and a boolean indicating if it meets the criteria.
    """
    result = []

    for char in char_list:
        is_valid = True

        if 'category' in criteria:
            if unicodedata.category(char) not in criteria['category']:
                is_valid = False

        if 'is_digit' in criteria:
            if criteria['is_digit'] != char.isdigit():
                is_valid = False

        if 'east_asian_width' in criteria:
            if unicodedata.east_asian_width(char) not in criteria['east_asian_width']:
                is_valid = False

        if 'mirrored' in criteria:
            if criteria['mirrored'] != bool(unicodedata.mirrored(char)):
                is_valid = False

        result.append((char, is_valid))

    return result

