def future_features_summary(features):
    """
    Processes the list of feature dictionaries and returns a summary dictionary.

    :param features: List of dictionaries representing feature metadata.
    :return: Dictionary containing the summary of features.
    """
    summary = {
        "features_by_mandatory_version": {},
        "total_features": len(features),
        "features_never_mandatory": []
    }

    for feature in features:
        name = feature["feature"]
        mandatory_version = feature["mandatory_in"]

        if mandatory_version:
            if mandatory_version not in summary["features_by_mandatory_version"]:
                summary["features_by_mandatory_version"][mandatory_version] = []
            summary["features_by_mandatory_version"][mandatory_version].append(name)
        else:
            summary["features_never_mandatory"].append(name)

    return summary

