def sort_letters_and_numbers(s):
    """
    Separates letters and numbers from the input string, sorts them individually,
    and merges them back into a single string with letters followed by numbers.
    """
    letters = ""
    digits = ""
    for char in s:
        if char.isdigit():
            digits += char
        else:
            letters += char

    sorted_letters = sorted(letters)
    sorted_digits = sorted(digits)

    return "".join(sorted_letters) + "".join(sorted_digits)

def factorial(n):
    """
    Returns the factorial of a given non-negative integer n using recursion.
    If n is a negative integer, returns None.

    :param n: Non-negative integer
    :return: Factorial of n or None for negative input
    """
    if n < 0:
        return None
    elif n == 0:
        return 1
    else:
        return n * factorial(n - 1)

