from typing import List, Dict, Any


def calculate_average_grades(data: List[Dict[str, Any]]) -> Dict[str, float]:
    """
    Calculate the average grade for each student.

    :param data: List of dictionaries containing students' names and their grades.
    :return: Dictionary with each student's name as a key and their average grade as the value.
    """
    average_grades = {}
    for student in data:
        name, grades = student['name'], student['grades']
        if grades:
            average = sum(grades.values()) / len(grades)
            average_grades[name] = average
        else:
            average_grades[name] = 0.0
    return average_grades

