def find_indices(lst, n):
    """
    Returns a list of indices where the integer 'n' occurs in the input list 'lst'.
    If 'n' is not present in 'lst', returns an empty list.
    """
    if not isinstance(lst, list):
        raise ValueError("The first argument must be a list.")
    if not isinstance(n, int):
        raise ValueError("The second argument must be an integer.")

    return [i for i, x in enumerate(lst) if x == n]

