def find_pair_with_sum(list1, list2, target):
    """
    Finds the first pair of elements (one from each list) that sums up to the given target.

    Parameters:
    list1 (list of int): The first list of integers.
    list2 (list of int): The second list of integers.
    target (int): The target sum.

    Returns:
    tuple: A tuple containing the first pair of elements from list1 and list2 that sum to the target, 
           or a message indicating no such pair if none exists.
    """
    for num1 in list1:
        for num2 in list2:
            if num1 + num2 == target:
                return (num1, num2)
    return "No pair found"

