def string_length_message(s):
    """
    Returns a message based on the length of the string s.
    """
    length = len(s)

    if length < 2:
        return "The string is too short"
    elif length == 2:
        return "The string has exactly 2 characters"
    elif 2 < length < 5:
        return "The string has a moderate length"
    else:
        return "The string is too long"

