def extract_key_value_pairs(json_object, keys):
    """
    Extracts the given keys along with their values from the provided JSON object.

    :param json_object: JSON object to parse
    :param keys: List of keys to extract
    :return: Dictionary containing key-value pairs
    """
    result = {}
    for key in keys:
        if key in json_object:
            result[key] = json_object[key]
        elif "address" in json_object and key in json_object["address"]:
            result[key] = json_object["address"][key]
    return result

