def update_server_permissions(servers):
    """
    Updates the permissions of a list of servers based on predefined rules.
    """
    updated_servers = []
    for server in servers:
        updated_permissions = set(server['permissions'])

        if 'delete' in updated_permissions:
            updated_permissions.update(['write', 'read'])
        elif 'write' in updated_permissions:
            updated_permissions.add('read')
        elif 'read' not in updated_permissions:
            updated_permissions = set()

        updated_servers.append({'name': server['name'], 'permissions': sorted(updated_permissions)})

    return updated_servers

def dec_to_bin(n):
    """
    Converts a decimal number to binary using recursion.

    Parameters:
    n (int): A decimal number to be converted to binary.

    Returns:
    str: The binary representation of the number as a string.
    """
    if n == 0:
        return "0"
    elif n == 1:
        return "1"
    else:
        return dec_to_bin(n//2) + str(n % 2)

def check_rotation(string1, string2):
    """
    Checks if string2 is a rotation of string1.
    """
    if len(string1) != len(string2):
        return False
    for i in range(len(string1)):
        if string1 == string2[i:] + string2[:i]:
            return True
    return False

