def is_valid_parentheses(s: str) -> bool:
    """
    Returns True if the given string of parentheses is valid, False otherwise.
    A string of parentheses is valid if every opening '(' has a corresponding closing ')'.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')' and stack:
            stack.pop()
        else:
            return False
    return len(stack) == 0

def recursive_sum(arr):
    """
    Sum all integers in an array recursively with an accumulator to avoid the inefficiency of slicing.

    Arguments:
    arr: List[int] -- array of integers to be summed

    Returns:
    int -- the sum of all integers in the array
    """

    def helper(arr, index):
        if index == len(arr):
            return 0
        return arr[index] + helper(arr, index + 1)

    return helper(arr, 0)

