def solve(n):
    """
    Returns the binary representation of the integer n as a string.
    """
    if n == 0:
        return '0'

    ans = ''
    while n > 0:
        if n % 2 == 0:
            ans = '0' + ans
        else:
            ans = '1' + ans
        n //= 2
    return ans

