def fruit_list_transformation(my_list):
    """
    Transforms the input list of lists into another list where each sublist contains a unique string
    and the sum of the corresponding numbers.
    """
    fruit_dict = {}
    for fruit, count in my_list:
        if fruit in fruit_dict:
            fruit_dict[fruit] += count
        else:
            fruit_dict[fruit] = count

    output_list = []
    for fruit, count in fruit_dict.items():
        output_list.append([fruit, count])

    return output_list

