def parse_color_codes(hex_string):
    """
    Parses a string of 2-digit hexadecimal color codes and returns a dictionary
    with the color codes as keys and their occurrences as values.
    """
    color_counts = {}
    for i in range(0, len(hex_string), 2):
        color_code = hex_string[i:i + 2]
        if color_code in color_counts:
            color_counts[color_code] += 1
        else:
            color_counts[color_code] = 1
    return color_counts

