def pad_string(input_string, target_length):
    """
    Pads the input_string with zeros at the beginning until it reaches target_length.
    Returns an error message for erroneous input.
    """
    if not isinstance(input_string, str):
        return "Error: input_string should be a string"

    if not isinstance(target_length, int):
        return "Error: target_length should be an integer"

    if target_length < len(input_string):
        return "Error: target_length is less than the length of input_string"

    return input_string.zfill(target_length)

