def is_balanced(expression):
    """
    Determines if the parentheses in the given expression are balanced.
    """
    stack = []
    matching_parentheses = {')': '(', ']': '[', '}': '{'}

    for char in expression:
        if char in matching_parentheses.values():
            stack.append(char)
        elif char in matching_parentheses.keys():
            if stack == [] or stack.pop() != matching_parentheses[char]:
                return False
    return len(stack) == 0

def is_ugly_number(num):
    """
    Returns True if the given number is an ugly number, else returns False.
    An ugly number is a number whose only prime factors are 2, 3, or 5.
    """
    if num <= 0:
        return False

    for p in [2, 3, 5]:
        while num % p == 0:
            num //= p

    return num == 1

def shift_encrypt(text):
    """
    Encrypts the given text by shifting each letter by one position in the alphabet.
    Non-letter characters are not modified.
    """
    result = []
    for char in text:
        if char.isalpha():
            if char.islower():
                # handle lowercase letters
                new_char = chr(((ord(char) - ord('a') + 1) % 26) + ord('a'))
            elif char.isupper():
                # handle uppercase letters
                new_char = chr(((ord(char) - ord('A') + 1) % 26) + ord('A'))
            result.append(new_char)
        else:
            # non-letter characters remain unchanged
            result.append(char)
    return ''.join(result)

