def vecsum(v):
    """
    Computes the sum of the elements in the vector v recursively.
    If the vector has only one element, it returns that element.
    Otherwise, it adds the first element to the sum of the rest of the elements.
    """
    if len(v) == 1:
        return v[0]
    else:
        return v[0] + vecsum(v[1:])

