    else:
        return n + solve(n - 1)

def safe_divide(a, b):
    """
    Returns the quotient of a and b. If b is zero, it returns 'undefined'.
    Rounds the result to the nearest integer if the answer is not a whole number.
    """
    if b == 0:
        return 'undefined'

    result = a / b

    return round(result)

def factorial(n):
    """
    Returns the factorial of a positive integer n using recursion.
    If n is not a positive integer, returns an appropriate error message.
    """
    if not isinstance(n, int):
        return "Error: Input is not an integer. Please enter a positive integer."
    if n < 0:
        return "Error: Input is a negative integer. Please enter a positive integer."
    if n == 0:
        return 1
    return n * factorial(n - 1)

