def is_integer(number):
    """
    Returns True if the number is an integer, otherwise False.
    It can handle both numeric types (int, float) and strings that represent numbers.
    """
    if isinstance(number, int):
        return True

    if isinstance(number, float):
        return number.is_integer()  # check if float number has no decimal part

