def count_e_and_frequency(input_string):
    """
    Returns the total count of the letter 'e' (both upper and lower case) and a frequency table for each letter.

    Parameters:
    input_string (str): The string to be analyzed.

    Returns:
    dict: A dictionary containing the count of 'e' and the frequency table.
    """
    e_count = input_string.lower().count('e')
    frequency_table = {}

    for char in input_string:
        if char.isalpha():
            if char in frequency_table:
                frequency_table[char] += 1
            else:
                frequency_table[char] = 1

    return {'e_count': e_count, 'frequency_table': frequency_table}

