def collatz_tree(n):
    """
    Construct the Collatz tree rooted at a given number `n`.

    :param n: Root number of the Collatz tree.
    :return: A dictionary representing the Collatz tree.
    """
    if n == 1:
        return {"value": 1, "children": []}

    node = {"value": n, "children": []}
    if n % 2 == 0:
        node["children"].append(collatz_tree(n // 2))
    else:
        node["children"].append(collatz_tree(3 * n + 1))

    return node

