def contract_list(lst):
    """
    Returns the single unique element in the list if all elements are the same.
    Otherwise, returns a message indicating the list contains more than one distinct element.
    """
    it = iter(lst)
    try:
        first = next(it)
    except StopIteration:
        return "List is empty"

    if all(element == first for element in it):
        return first
    else:
        return "List contains more than one distinct element"

