def multiply_matrices(A, B):
    """
    Multiplies two n x n matrices A and B.
    """
    n = len(A)  # Assuming A and B are n x n matrices
    C = [[0] * n for _ in range(n)]  # Initialize result matrix with zeros

    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]

    return C

def find_value_index(matrix, value):
    """
    Returns the index of the first occurrence of the value in the 2D array.
    If the value is not found, returns [-1, -1].
    """
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            if matrix[i][j] == value:
                return [i, j]
    return [-1, -1]

def generate_diamond(n):
    """
    Generates a diamond pattern of the size 'n', representing
    the middle line width and longest part of the diamond.
    """
    diamond = []
    for i in range(n):
        line = ' ' * (n - i - 1) + '*' * (2 * i + 1) + ' ' * (n - i - 1)
        diamond.append(line)

    for i in range(n - 2, -1, -1):
        line = ' ' * (n - i - 1) + '*' * (2 * i + 1) + ' ' * (n - i - 1)
        diamond.append(line)

    return "\n".join(diamond)

