def sum_odd_numbers(n):
    """
    Returns the sum of all odd numbers up to a given number n using recursion.
    If n is negative or zero, the function returns 0.
    """
    if n <= 0:
        return 0

    if n % 2 == 0:
        n -= 1

    return n + sum_odd_numbers(n - 2)

