def fibonacci(n):
    """
    Returns the nth Fibonacci number using an iterative approach with constant space complexity and optimized O(log n) time complexity using matrix exponentiation.
    """
    if n == 0:
        return 0
    if n == 1:
        return 1

    def multiply_matrices(m1, m2):
        return [
            [m1[0][0] * m2[0][0] + m1[0][1] * m2[1][0], m1[0][0] * m2[0][1] + m1[0][1] * m2[1][1]],
            [m1[1][0] * m2[0][0] + m1[1][1] * m2[1][0], m1[1][0] * m2[0][1] + m1[1][1] * m2[1][1]]
        ]

    def matrix_power(matrix, power):
        if power == 1:
            return matrix

        if power % 2 == 0:
            half_power = matrix_power(matrix, power // 2)
            return multiply_matrices(half_power, half_power)

        else:
            return multiply_matrices(matrix, matrix_power(matrix, power - 1))

    F = [[1, 1],
         [1, 0]]

    result = matrix_power(F, n - 1)

    return result[0][0]

def is_robot_back_to_origin(instructions):
    """
    Determines if following the given instructions brings the robot back to the origin (0, 0).

    Parameters:
    instructions (str): A string consisting of 'N', 'S', 'E', 'W' representing directions.

    Returns:
    bool: True if the robot returns to the origin after following all instructions, False otherwise.
    """
    x, y = 0, 0

    for move in instructions:
        if move == 'N':
            y += 1
        elif move == 'S':
            y -= 1
        elif move == 'E':
            x += 1
        elif move == 'W':
            x -= 1

    return x == 0 and y == 0

def fibonacci(n, m, memo=None):
    """
    Returns the nth Fibonacci number modulo m.
    This function uses memoization to avoid recalculating values.
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return n

    # Recursively calculate the nth Fibonacci number
    memo[n] = (fibonacci(n-1, m, memo) + fibonacci(n-2, m, memo)) % m
    return memo[n]

