def switch_core(instruction):
    """
    Executes a function based on the provided instruction keyword.

    Parameters:
    instruction (str): The instruction keyword to map to a specific function.

    Returns:
    str: The result of the executed function or an error message for unknown instructions.
    """

    def handle_case_one():
        return "Executed Case One"

    def handle_case_two():
        return "Executed Case Two"

    def handle_case_three():
        return "Executed Case Three"

    # Dictionary mapping of instruction keywords to handling functions
    cases = {
        "case_one": handle_case_one,
        "case_two": handle_case_two,
        "case_three": handle_case_three
    }

    # Default case for unknown instructions
    def default_case():
        return "Unknown instruction"

    # Get the function from dictionary or use default_case if not found
    func = cases.get(instruction, default_case)

    # Execute the function and return its result
    return func()

