def find_permutations(s):
    """
    Returns all permutations of the input string s.
    """
    if len(s) < 2:
        return [s]

    chars = list(s)
    result = []

    for i, char in enumerate(chars):
        rest = s[:i] + s[i + 1:]

        # Get permutations of the rest of the characters
        for perm in find_permutations(rest):
            result.append(char + perm)

    return list(set(result))

