def fibonacci(n):
    """
    Returns the nth Fibonacci number using recursion. Handles negative input by returning an error message.

    :param n: The position in the Fibonacci sequence.
    :return: The nth Fibonacci number or an error message for negative input.
    """
    if n < 0:
        return "Input should be a non-negative integer"
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

def fib(n):
    """
    Returns the nth Fibonacci number using recursion.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fib(n-1) + fib(n-2)

def fibonacci(n):
    """
    Returns the nth Fibonacci number using fast doubling method.
    This method is efficient for large values of n.
    """
    def fib(n):
        if n == 0:
            return (0, 1)
        else:
            a, b = fib(n // 2)
            c = a * ((b << 1) - a)
            d = a * a + b * b
            if n & 1:
                return (d, c + d)
            else:
                return (c, d)

    return fib(n)[0]

