import json


def validate_json(json_string, required_keys):
    """
    Validates if the given json_string is a correct JSON and contains specific keys with certain types.

    Args:
    json_string (str): The JSON string to be validated.
    required_keys (dict): A dictionary where keys are the required keys in the JSON and values are the expected types.

    Returns:
    tuple: (is_valid (bool), error_message (str))
    """
    try:
        data = json.loads(json_string)
    except json.JSONDecodeError:
        return False, "Invalid JSON format"

    for key, expected_type in required_keys.items():
        if key not in data:
            return False, f"Missing key: {key}"
        if not isinstance(data[key], expected_type):
            return False, f"Incorrect type for key: {key}. Expected {expected_type.__name__}, got {type(data[key]).__name__}"

    return True, "Valid JSON"

