import math


def find_roots(a, b, c):
    """
    Calculates the roots of a quadratic equation a*x^2 + b*x + c = 0.

    If a is zero, raises a ValueError because the equation is not quadratic.
    If there are no real roots, returns a message indicating that.
    Otherwise, returns the two roots.
    """
    if a == 0:
        raise ValueError("Coefficient 'a' cannot be zero for a quadratic equation.")

    discriminant = b**2 - 4*a*c
    if discriminant < 0:
        return "The equation has no real roots."
    elif discriminant == 0:
        root = -b / (2*a)
        return (root,)
    else:
        root1 = (-b + math.sqrt(discriminant)) / (2*a)
        root2 = (-b - math.sqrt(discriminant)) / (2*a)
        return (root1, root2)

