def reverse_string(s):
    """
    Returns the reversed string. If the string is a palindrome, also returns True, otherwise returns False.

    :param s: Input string
    :return: Tuple (reversed string, boolean indicating if input string is a palindrome)
    """
    reversed_s = s[::-1]
    is_palindrome = s == reversed_s
    if is_palindrome:
        return (s, True)
    else:
        return (reversed_s, False)

