def calculate_operations(a, b):
    """
    Returns the sum, difference, product, and quotient (if b is not zero) of two integers a and b.
    """
    results = {}
    results['sum'] = a + b
    results['difference'] = a - b
    results['product'] = a * b
    try:
        results['quotient'] = a / b
    except ZeroDivisionError:
        results['quotient'] = 'Error: Division by zero'

    return results

