import json


def lambda_handler(event, context):
    """
    AWS Lambda function that takes a string from the input and returns the string in uppercase.
    """
    input_string = event.get('input_string', '')

    # Check if the input is indeed a string
    if not isinstance(input_string, str):
        return {
            'statusCode': 400,
            'body': json.dumps('Invalid input, please provide a string.')
        }

    uppercase_string = input_string.upper()

    return {
        'statusCode': 200,
        'body': json.dumps(uppercase_string)
    }

