def binary_to_decimal(binary_str):
    """
    Converts a given binary number (as a string) to its decimal equivalent.
    The binary number can be prefixed with '0b' or '-0b' for positive and negative numbers respectively.

    Parameters:
    binary_str (str): The binary number as a string.

    Returns:
    int: The decimal equivalent as an integer.
    """
    if binary_str[:2] == '0b':
        return int(binary_str, 2)
    elif binary_str[:3] == '-0b':
        return int(binary_str, 2)
    else:
        raise ValueError("Invalid binary number format")

