def caesar_cipher(text, shift, decrypt=False):
    """
    Encrypts or decrypts a text using the Caesar Cipher method.

    :param text: The input text to encrypt or decrypt.
    :param shift: The number of positions to shift the letters by.
    :param decrypt: If True, will decrypt the text. Otherwise, will encrypt.
    :return: The encrypted or decrypted text.
    """
    if decrypt:
        shift = -shift

    result = []

    for char in text:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            result.append(chr((ord(char) - base + shift) % 26 + base))
        else:
            result.append(char)

    return ''.join(result)

def check_balanced_parentheses(s):
    """
    Checks if the parentheses in the string s are balanced.

    Parameters:
    s (str): The input string containing parentheses.

    Returns:
    tuple: (bool, int or None) - A tuple where the first element is True if the parentheses are balanced, 
                                    False otherwise. The second element is the position of the first unbalanced 
                                    parenthesis (0-based index), or None if parentheses are balanced.
    """
    stack = []
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                return (False, i)

    if stack:
        return (False, stack[0])

    return (True, None)

