def binary_exponentiation(base, exponent):
    """
    Calculates the power of a number using binary exponentiation.
    """
    if exponent == 0:
        return 1
    elif exponent % 2 == 0:
        half_power = binary_exponentiation(base, exponent // 2)
        return half_power * half_power
    else:
        half_power = binary_exponentiation(base, (exponent - 1) // 2)
        return half_power * half_power * base

