def fizz_buzz():
    """
    Prints the numbers from 1 to 100 that are divisible by 3 or 5, and replaces
    - multiples of 3 with "Fuzz",
    - multiples of 5 with "Buzz",
    - multiples of both 3 and 5 with "FuzzBuzz".
    """
    result = []
    for i in range(1, 101):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FuzzBuzz")
        elif i % 3 == 0:
            result.append("Fuzz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(i)
    return result

