def is_valid_ipv4(ip):
    """
    Checks if a given IPv4 address is valid.

    :param ip: IPv4 address as a string
    :return: True if the IPv4 address is valid, otherwise False
    """
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
    return True

