def next_palindrome(n):
    """
    Returns the next palindrome number greater than n.
    """
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    n += 1  # Start checking from the next number
    while not is_palindrome(n):
        n += 1
    return n

def generate_pac(domains, proxy):
    """
    Generates a PAC file content for given domains with specified proxy settings.

    Parameters:
        domains (list of str): List of domains to be proxied.
        proxy (str): The proxy settings in the form "PROXY host:port".

    Returns:
        str: The PAC file content.
    """

    pac_script = """function FindProxyForURL(url, host) {
    var domains = [""" + ", ".join(f'"{domain}"' for domain in domains) + """];

    for (var i = 0; i < domains.length; i++) {
        if (shExpMatch(host, domains[i])) {
            return '""" + proxy + """';
        }
    }
    return 'DIRECT';
}
"""
    return pac_script

