def manage_student_scores():
    """
    Manages student scores using a dictionary. Returns a dictionary of student scores.
    """
    student_scores = {}

    def add_student_score(student, score):
        if student in student_scores:
            student_scores[student].append(score)
        else:
            student_scores[student] = [score]

    def get_student_score(student):
        return student_scores.get(student, [])

    def remove_student(student):
        if student in student_scores:
            del student_scores[student]

    def get_all_students():
        return list(student_scores.keys())

    return {
        "add_student_score": add_student_score,
        "get_student_score": get_student_score,
        "remove_student": remove_student,
        "get_all_students": get_all_students,
    }

def is_perfect_square(n):
    """
    Determine if a given number n is a perfect square without using the square root function.
    """
    if n < 0:
        return False

    i = 0
    while i * i <= n:
        if i * i == n:
            return True
        i += 1

    return False

