def climb_stairs(n):
    """
    Calculate the number of ways to climb a staircase with n steps,
    given that you can take 1 or 2 steps at a time.
    """
    if n <= 1:
        return 1
    return climb_stairs(n - 1) + climb_stairs(n - 2)

