def has_consecutive_numbers(nums):
    """
    Returns True if the list contains consecutive numbers, False otherwise.
    """
    if not nums:
        return False

    nums = sorted(nums)
    for i in range(len(nums) - 1):
        if nums[i] + 1 != nums[i + 1]:
            return False
    return True

