def factorial(num):
    """
    Returns the factorial of a given non-negative integer num.
    If num is negative, it returns None as the factorial is not defined for negative numbers.
    """
    if num < 0:
        return None
    elif num == 0 or num == 1:
        return 1
    else:
        return num * factorial(num - 1)

