def valid_isbn10(isbn):
    """
    Determines if the given string is a valid ISBN-10.
    An ISBN-10 is valid if it consists of 9 digits followed by a digit or 'X' (for 10),
    and passes the ISBN-10 checksum calculation.
    """
    if len(isbn) != 10:
        return False

    total = 0
    for i in range(10):
        if isbn[i] == 'X':
            if i == 9:
                total += 10 * (10 - i)
            else:
                return False
        elif isbn[i].isdigit():
            total += int(isbn[i]) * (10 - i)
        else:
            return False

    return total % 11 == 0

