def find_longest_substring(s):
    """
    Returns the length of the longest substring without repeating characters.
    """
    char_index_map = {}
    longest = 0
    start = 0

    for current in range(len(s)):
        if s[current] in char_index_map and char_index_map[s[current]] >= start:
            start = char_index_map[s[current]] + 1
        char_index_map[s[current]] = current
        longest = max(longest, current - start + 1)

    return longest

