def evaluate_operations(operations_dict: dict) -> dict:
    """
    Evaluates a series of mathematical operations on pairs of operands provided in a dictionary.

    Parameters:
    operations_dict (dict): A dictionary where each key is a string representing the operation (add, subtract, multiply, divide)
                            and the value is a list of tuples, each containing two integers representing the operands.

    Returns:
    dict: A dictionary where each key is the operation name and each value is a list of results corresponding to
          the operation applied to the operand pairs.
    """
    result_dict = {}

    for operation, pairs in operations_dict.items():
        results = []
        for x, y in pairs:
            if operation == "add":
                results.append(x + y)
            elif operation == "subtract":
                results.append(x - y)
            elif operation == "multiply":
                results.append(x * y)
            elif operation == "divide":
                if y == 0:
                    results.append("undefined")
                else:
                    results.append(x / y)
        result_dict[operation] = results

    return result_dict

