def calculate_weekly_summary(data):
    """
    Processes the given dictionary of daily timings for various activities and returns a dictionary with the 
    total time spent on each activity for the week.

    Parameters:
    data (dict): A dictionary where the keys are the days of the week and the values are dictionaries of 
                 activity names and time spent (in minutes).

    Returns:
    dict: A dictionary where the keys are the activity names and the values are the total time spent on each 
          activity over the week, in minutes.
    """
    weekly_summary = {}

    for day, activities in data.items():
        for activity, time in activities.items():
            if activity in weekly_summary:
                weekly_summary[activity] += time
            else:
                weekly_summary[activity] = time

    return weekly_summary

