def is_permutation(str1: str, str2: str) -> bool:
    """
    Determine if two strings are permutations of each other.
    """
    if len(str1) != len(str2):
        return False

    count1 = {}
    count2 = {}

    for ch in str1:
        if ch in count1:
            count1[ch] += 1
        else:
            count1[ch] = 1

    for ch in str2:
        if ch in count2:
            count2[ch] += 1
        else:
            count2[ch] = 1

    return count1 == count2

def digit_frequency(number_list: list) -> dict:
    """
    Calculate the frequency of each digit in the given list of integers.

    :param number_list: List of integers to be analyzed.
    :return: Dictionary with digit frequencies.
    """
    frequencies = {str(digit): 0 for digit in range(10)}

    for number in number_list:
        for digit in str(abs(number)):
            frequencies[digit] += 1

    return frequencies

