def calculate_course_average(grades):
    """
    Calculate the average grades for students and the overall course average.

    :param grades: dict, where keys are student names and values are dictionaries,
                   with subject names as keys and grades as values (all values are floats).

    :return: dict, a dictionary with student names as keys and their average grades as values.
                   Additionally, it should contain an 'overall_avg' key representing the course average.
    """
    student_averages = {}

    for student, subjects in grades.items():
        if subjects:
            average = sum(subjects.values()) / len(subjects)
            student_averages[student] = average

    if student_averages:
        overall_avg = sum(student_averages.values()) / len(student_averages)
        student_averages['overall_avg'] = round(overall_avg, 2)
    else:
        student_averages['overall_avg'] = 0.0

    return student_averages

