def normalize_directory_path(path: str) -> str:
    """
    Normalizes the given UNIX-style file path.

    Parameters:
    path (str): The input file path which may include '.', '..', or multiple '/'.

    Returns:
    str: The normalized file path.

    Raises:
    ValueError: When the input is not a string.
    """
    if not isinstance(path, str):
        raise ValueError(f"Expected string as input, found {type(path)}")

    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '..':
            if stack:
                stack.pop()
        elif part and part != '.':
            stack.append(part)

    return '/' + '/'.join(stack)

