def rotate_matrix(image: list) -> None:
    """
    Rotates the given n x n matrix by 90 degrees clockwise in place.

    Args:
    image (list[list[int]]): The n x n 2D list of integers representing the grayscale image.
    """
    if not image or not image[0]:
        return

    n = len(image)

    # Step 1: Transpose the matrix
    for i in range(n):
        for j in range(i, n):
            image[i][j], image[j][i] = image[j][i], image[i][j]

    # Step 2: Reverse each row
    for i in range(n):
        image[i].reverse()

