from typing import List, Dict


def batch_transactions(transactions: List[Dict[str, any]]) -> Dict[str, float]:
    """
    Groups transactions by customer_id and calculates the total amount for each customer.

    :param transactions: List of transactions, each represented by a dictionary with keys 'customer_id' and 'amount'.
    :return: A dictionary with customer IDs as keys and total transaction amounts as values.
    """
    result = {}
    for transaction in transactions:
        customer_id = transaction['customer_id']
        amount = transaction['amount']

        if customer_id in result:
            result[customer_id] += amount
        else:
            result[customer_id] = amount

    return result

