def evaluate_rpn(expression):
    """
    Evaluates the given RPN expression and returns the result as a float.

    Args:
    expression (List[str]): A list of strings where each string is either an integer or an operator.

    Returns:
    float: The result of the RPN expression.
    """
    stack = []
    operators = {"+", "-", "*", "/"}

    for token in expression:
        if token in operators:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)
        else:
            stack.append(int(token))

    return float(stack.pop())

