def calculate_directory_size(file_system: dict, directory: str) -> int:
    """
    Calculates the total size of the specified directory in the given file system tree.

    Args:
    file_system (dict): A dictionary representing the file system tree where keys are directory or file names and values are either another dictionary (for subdirectories) or an integer (for file sizes).
    directory (str): The name of the directory for which to calculate the total size.

    Returns:
    int: The total size of all files and subdirectories within the specified directory.

    Raises:
    ValueError: If the specified directory does not exist in the file system.
    """

    def size_helper(current_directory):
        total_size = 0
        for item, value in current_directory.items():
            if isinstance(value, dict):
                total_size += size_helper(value)
            else:
                total_size += value
        return total_size

    if directory not in file_system:
        raise ValueError("Directory not found")

    return size_helper(file_system[directory])

