def camel_to_snake(camel_case_sentence: str) -> str:
    """
    Converts a camelCase sentence into snake_case format.

    :param camel_case_sentence: A sentence in camelCase format.
    :return: The sentence converted to snake_case format.
    """
    snake_case_sentence = ""

    for index, char in enumerate(camel_case_sentence):
        if char.isupper():
            if index != 0:
                snake_case_sentence += "_"
            snake_case_sentence += char.lower()
        else:
            snake_case_sentence += char

    return snake_case_sentence

