def regex_match(pattern: str, text: str) -> bool:
    """
    Matches a given pattern against a given text using basic regex rules.

    Parameters:
        - pattern (str): The regex pattern, which can include `.` and `*`.
        - text (str): The text to match against the pattern.

    Returns:
        (bool): True if the text matches the pattern, else False.
    """
    def match_helper(p, t, p_idx, t_idx):
        if p_idx == len(p):  # End of pattern
            return t_idx == len(t)  # True if end of text, else False

        first_match = t_idx < len(t) and (p[p_idx] == t[t_idx] or p[p_idx] == '.')

        if p_idx + 1 < len(p) and p[p_idx + 1] == '*':
            return (match_helper(p, t, p_idx + 2, t_idx) or
                   (first_match and match_helper(p, t, p_idx, t_idx + 1)))
        else:
            return first_match and match_helper(p, t, p_idx + 1, t_idx + 1)

    return match_helper(pattern, text, 0, 0)

from collections import deque


def shortest_path(graph, start_node, target_node):
    """
    Finds the shortest path in an unweighted graph from start_node to target_node using BFS.

    :param graph: A dictionary where keys are node identifiers and values are lists of adjacent nodes.
    :param start_node: The identifier of the starting node.
    :param target_node: The identifier of the target node.
    :return: A list of nodes representing the shortest path from start_node to target_node.
    """
    if start_node == target_node:
        return [start_node]

    visited = set()
    queue = deque([(start_node, [start_node])])

    while queue:
        current_node, path = queue.popleft()

        if current_node not in visited:
            visited.add(current_node)

            for neighbor in graph[current_node]:
                if neighbor == target_node:
                    return path + [target_node]

                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))

    return []

