import collections
import heapq


def network_delay_time(times, N, K):
    """
    Calculate the minimum time required for a signal to reach all nodes in the network from starting node K.

    :param times: List of tuples (u, v, w), each representing an edge with transmission time w from node u to v.
    :param N: The total number of nodes in the network.
    :param K: The starting node.
    :return: Minimum time required for the signal to reach all nodes, or -1 if it's impossible.
    """
    graph = collections.defaultdict(list)
    for u, v, w in times:
        graph[u].append((v, w))

    min_heap = [(0, K)]
    dist = {}

    while min_heap:
        time, node = heapq.heappop(min_heap)
        if node in dist:
            continue
        dist[node] = time
        for v, w in graph[node]:
            if v not in dist:
                heapq.heappush(min_heap, (time + w, v))

    if len(dist) == N:
        return max(dist.values())
    return -1

def collatz_sequence_length(n: int, memo={1: 1}) -> int:
    """
    Returns the length of the Collatz sequence starting from n.
    Uses memoization to store previously computed results for efficiency.
    """
    if n in memo:
        return memo[n]

    if n % 2 == 0:
        next_n = n // 2
    else:
        next_n = 3 * n + 1

    memo[n] = 1 + collatz_sequence_length(next_n)
    return memo[n]

