def is_symmetric(matrix: list[list[int]]) -> bool:
    """
    Checks if the given square matrix is symmetric.

    :param matrix: List of lists representing the square matrix
    :return: True if the matrix is symmetric, False otherwise
    """
    n = len(matrix)

    # Check symmetry
    for i in range(n):
        for j in range(i, n):
            if matrix[i][j] != matrix[j][i]:
                return False

    return True

