def sum_of_digits(number: int) -> int:
    """
    Returns the sum of the digits of a non-negative integer number.
    """
    if not isinstance(number, int) or number < 0:
        raise ValueError("Input must be a non-negative integer (0 ≤ number ≤ 10^9)")

    if number == 0:
        return 0

    if number < 10:
        return number

    return number % 10 + sum_of_digits(number // 10)

