def find_two_sum_indices(nums, target):
    """
    Determine if two distinct indices exist such that the elements at those indices sum to the target.
    :param nums: List of integers.
    :param target: Integer representing the target sum.
    :return: Tuple of two integers representing the indices.
    """
    num_to_index = {}

    for i, num in enumerate(nums):
        complement = target - num

        if complement in num_to_index:
            return (num_to_index[complement], i)

        num_to_index[num] = i

    raise ValueError(f"No two sum solution for target {target}")

