def calculate_total_size(directory: dict) -> int:
    """
    Traverses the nested directory structure and returns the total size of all unique files.
    """
    def traverse(dir, seen_files):
        total_size = 0
        for key, value in dir.items():
            if isinstance(value, dict):
                # Recurse into sub-directory
                total_size += traverse(value, seen_files)
            elif isinstance(value, int):
                # It's a file, check if it's already seen
                if key not in seen_files:
                    seen_files.add(key)
                    total_size += value
        return total_size

    seen_files = set()
    return traverse(directory, seen_files)

