def process_emails(email_list: list, keywords: dict) -> dict:
    """
    Process email contents and categorize them based on keywords.
    Parameters:
        - email_list <type: list>: list of email contents in plain text.
        - keywords <type: dict>: dictionary with categories as keys and lists of keywords as values.
    Return:
        - email_category_dict <type: dict>: dictionary with email index as keys and list of matching categories as values.
    """
    email_category_dict = {}
    for email_index, email_content in enumerate(email_list):
        email_categories = []
        email_lower = email_content.lower()
        for category, keyword_list in keywords.items():
            for keyword in keyword_list:
                if keyword.lower() in email_lower:
                    email_categories.append(category)
                    break
        email_category_dict[email_index] = email_categories
    return email_category_dict

