from typing import List


def matrix_multiplication(matrix_a: List[List[float]], matrix_b: List[List[float]]) -> List[List[float]]:
    """
    Multiplies two matrices and returns the result as a new matrix.
    """
    # Check if the matrices are valid for multiplication
    if len(matrix_a[0]) != len(matrix_b):
        raise ValueError("Number of columns in matrix_a must be equal to number of rows in matrix_b")

    # Initialize result matrix with zeros
    result = [[0.0 for _ in range(len(matrix_b[0]))] for _ in range(len(matrix_a))]

    # Perform matrix multiplication
    for i in range(len(matrix_a)):
        for j in range(len(matrix_b[0])):
            for k in range(len(matrix_b)):
                result[i][j] += matrix_a[i][k] * matrix_b[k][j]

    return result

