def manage_warehouse(commands: str, start_position: tuple) -> tuple:
    """
    Simulates the movement of a robot within a grid-shaped warehouse.

    Parameters:
    commands (str): A string containing the movement commands ('U', 'D', 'L', 'R').
    start_position (tuple): A tuple (x, y) representing the robot's starting coordinates.

    Returns:
    tuple: A tuple (x, y) representing the robot's final position after executing all commands.
    """
    x, y = start_position

    for command in commands:
        if command == 'U':
            y -= 1
        elif command == 'D':
            y += 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1

    return (x, y)

def factorial_recursive(n: int) -> int:
    """
    Return the factorial of a non-negative integer n using recursion.

    :param n: Non-negative integer
    :return: Factorial of the input integer
    """
    if n == 0:
        return 1
    return n * factorial_recursive(n - 1)

