def complex_evaluation(num_list, conversion_factor, threshold):
    """
    Takes a list of integers, a conversion factor, and a threshold. Converts the integers, filters them,
    and applies alternating square and cube operations through a generator. Returns the results as a list.
    """
    # List comprehension to convert and filter numbers
    filtered_numbers = [float(x) * conversion_factor for x in num_list if float(x) * conversion_factor >= threshold]

    def alternating_generator(nums):
        for num in nums:
            yield num ** 2
            yield num ** 3

    result_generator = alternating_generator(filtered_numbers)

    collect_results = []
    try:
        while True:
            collect_results.append(next(result_generator))
    except StopIteration:
        pass

    return collect_results

