def summarize_constants(values):
    """
    Returns a summary of occurrences of specific built-in constants in the given list of values.
    """
    constants_summary = {
        'True': 0,
        'False': 0,
        'None': 0,
        'NotImplemented': 0,
        'Ellipsis': 0,
        'Others': 0
    }

    for value in values:
        if value is True:
            constants_summary['True'] += 1
        elif value is False:
            constants_summary['False'] += 1
        elif value is None:
            constants_summary['None'] += 1
        elif value is NotImplemented:
            constants_summary['NotImplemented'] += 1
        elif value is Ellipsis:
            constants_summary['Ellipsis'] += 1
        else:
            constants_summary['Others'] += 1

    return constants_summary

