def append_frequency(s):
    """
    Takes in a string s and returns the string with each character's frequency appended to it consecutively.
    """
    freq = {}
    result = []

    for char in s:
        freq[char] = freq.get(char, 0) + 1
        result.append(f"{char}{freq[char]}")

