def group_people_by_age(people):
    """
    Group people by age.

    Parameters:
    people (list of dict): A list of dictionaries where each dictionary contains 'name' and 'age' keys.

    Returns:
    dict: A dictionary where the keys are ages and the values are lists of names of people with that age.
    """
    age_groups = {}
    for person in people:
        # Handle missing keys
        if 'age' not in person or 'name' not in person:
            continue

        age = person['age']
        name = person['name']

        if age in age_groups:
            age_groups[age].append(name)
        else:
            age_groups[age] = [name]

    return age_groups

