def count_employees_by_department(employees):
    """
    Given a list of dictionaries representing employees in a company, returns a dictionary 
    where keys are department names and values are the count of employees in each department.

    :param employees: List[Dict[str, str]] - list of dictionaries with 'name' and 'department' keys
    :return: Dict[str, int] - dictionary with department names as keys and their employee count as values.
    """
    department_counts = {}

    for employee in employees:
        department = employee["department"]
        if department in department_counts:
            department_counts[department] += 1
        else:
            department_counts[department] = 1

    return department_counts

