def count_even_sum_subarrays(arr: list) -> int:
    """
    Returns the count of contiguous subarrays whose elements sum up to an even number.
    """
    count = 0
    n = len(arr)

    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += arr[j]
            if current_sum % 2 == 0:
                count += 1

    return count

def longest_balanced_substring(s: str) -> int:
    """
    Returns the length of the longest balanced parentheses substring.
    """
    stack = [-1]
    max_length = 0

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_length = max(max_length, i - stack[-1])

    return max_length

