def compress_list(lst):
    """
    Compresses a list of integers into a string where consecutive, identical elements
    are represented by the element followed by the count.
    """
    if not lst:
        return ""

    compressed = []
    current = lst[0]
    count = 1

    for num in lst[1:]:
        if num == current:
            count += 1
        else:
            compressed.append(f"{current}*{count}")
            current = num
            count = 1
    compressed.append(f"{current}*{count}")

    return "".join(compressed)

