def find_two_sum_indices(nums, target):
    """
    Finds two indices in the list 'nums' such that the elements at these indices add up to 'target'.

    :param nums: List of integers
    :param target: Target integer
    :return: Tuple containing two indices or an empty tuple if no pair is found
    """
    num_to_index = {}

    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], i)
        num_to_index[num] = i

    return ()

