def pair_sum_to_zero(lst):
    """
    Returns a list of unique pairs of integers from the input list that sum to zero.
    Each pair is in the form (min, max) and ordered lexicographically.
    """
    from collections import Counter

    counter = Counter(lst)
    result = set()

    for num in counter:
        if num > 0 and -num in counter:
            result.add((-num, num))

    return sorted(result)

def word_occurrences(sentences):
    """
    Takes a list of sentences and returns a dictionary where each unique word is a key
    and the value is a list of indices of sentences in which the word appears.
    """
    word_dict = {}

    for idx, sentence in enumerate(sentences):
        words = sentence.split()
        for word in words:
            if word not in word_dict:
                word_dict[word] = []
            if idx not in word_dict[word]:
                word_dict[word].append(idx)

    return word_dict

