def create_directory_structure(paths):
    """
    Takes a list of strings representing file paths as input 
    and organizes them into a hierarchical dictionary structure.
    """
    root = {}

    for path in paths:
        parts = path.split('/')
        current_level = root

        for part in parts[:-1]:
            current_level = current_level.setdefault(part, {})

        current_level[parts[-1]] = None

    return root

