from collections import deque


def shortest_path(graph, start, end):
    """
    Returns the shortest path between start and end nodes in an unweighted graph.
    """
    if start == end:
        return [start]

    queue = deque([(start, [start])])
    visited = set()

    while queue:
        node, path = queue.popleft()

        if node in visited:
            continue

        visited.add(node)

        for neighbor in graph.get(node, []):
            if neighbor == end:
                return path + [neighbor]
            else:
                queue.append((neighbor, path + [neighbor]))

    return None

