def flatten_dictionary(d: dict, parent_key: str = '', sep: str = '.') -> dict:
    """Flatten a nested dictionary using dot-notation for nested keys.

    Handles keys as integers and strings, allows for lists within the dictionary.

    Examples:
    >>> flatten_dictionary({'a': 1, 'b': {'c': 2, 'd': {'e': 3}}, 'f': {'g': 4}})
    {'a': 1, 'b.c': 2, 'b.d.e': 3, 'f.g': 4}

    >>> flatten_dictionary({1: {2: {3: 4}}})
    {'1.2.3': 4}

    >>> flatten_dictionary({'a': []})
    {'a': []}

    >>> flatten_dictionary({})
    {}
    """
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else str(k)
        if isinstance(v, dict):
            items.extend(flatten_dictionary(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

