def is_prime(n):
    """
    Determine if a given positive integer n is a prime number.

    :param n: Positive integer to check for primality.
    :return: True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False

    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False

    return True

def find_peak(nums):
    """
    Returns the index of the first peak element in the list.
    A peak element is an element that is greater than its neighbors.
    If the list is empty or no peak exists, returns -1.
    """
    if not nums:
        return -1

    n = len(nums)

    for i in range(n):
        if (i == 0 or nums[i] > nums[i - 1]) and (i == n - 1 or nums[i] > nums[i + 1]):
            return i

    return -1

