def analyze_scores(students):
    """
    Returns a dictionary with the average, highest, and lowest score from a list of students' scores.

    :param students: List of dictionaries containing 'name' and 'score' keys.
    :return: A dictionary with 'average', 'highest', and 'lowest' keys.
    """
    if not students:
        return {'average': None, 'highest': None, 'lowest': None}

    scores = [student['score'] for student in students]

    average_score = sum(scores) / len(scores)
    highest_score = max(scores)
    lowest_score = min(scores)

    return {'average': average_score, 'highest': highest_score, 'lowest': lowest_score}

