def is_balanced(input_string: str) -> bool:
    """
    Checks whether the input string has balanced and correctly nested pairs of parentheses, brackets, and curly braces.

    Parameters:
    input_string (str): The input string containing (), [], {} characters.

    Returns:
    bool: True if the string is balanced, False otherwise.
    """
    stack = []
    matching_pairs = {')': '(', ']': '[', '}': '{'}

    for char in input_string:
        if char in matching_pairs.values():
            stack.append(char)
        elif char in matching_pairs.keys():
            if stack == [] or stack.pop() != matching_pairs[char]:
                return False
        else:
            # Invalid character, return False
            return False

    return stack == []

def find_duplicates(nums):
    """
    Returns a list of elements that appear more than once in the input list.
    The order of elements in the returned list is the same as their first occurrence in the input list.
    """
    seen = set()
    duplicates = set()
    result = []

    for num in nums:
        if num in seen:
            duplicates.add(num)
        else:
            seen.add(num)

    for num in nums:
        if num in duplicates and num not in result:
            result.append(num)

    return result

