def analyze_frequency(input_list):
    """
    Analyzes the frequency of integers in the input list.

    Parameters:
    input_list (list): A list of integers.

    Returns:
    dict: A dictionary with frequency of each integer, highest frequency integer, and lowest frequency integer.
    """
    frequency_dict = {}
    for number in input_list:
        if number in frequency_dict:
            frequency_dict[number] += 1
        else:
            frequency_dict[number] = 1

    highest_freq = max(frequency_dict.values())
    lowest_freq = min(frequency_dict.values())

    highest_frequency = min([k for k, v in frequency_dict.items() if v == highest_freq])
    lowest_frequency = min([k for k, v in frequency_dict.items() if v == lowest_freq])

    return {
        'frequency_dict': frequency_dict,
        'highest_frequency': highest_frequency,
        'lowest_frequency': lowest_frequency
    }

