def count_friends(people):
    """
    Takes a list of people objects and returns a dictionary mapping each person's name to the number of friends they have.
    """
    # Create a set of valid person names
    valid_names = {person['name'] for person in people}

    # Create the result dictionary
    friends_count = {}
    for person in people:
        # Only count friends that are also in the valid names set
        valid_friends = [friend for friend in person['friends'] if friend in valid_names]
        friends_count[person['name']] = len(valid_friends)

    return friends_count

