def deep_copy_dictionary(d):
    """
    Returns a deep copy of the input dictionary. The dictionary may contain nested dictionaries,
    lists, and other primitive data types (integers, strings, floats, etc.).
    """
    if not isinstance(d, dict):
        raise ValueError("Input is not a dictionary.")

    def deep_copy(d):
        result = {}
        for key, value in d.items():
            if isinstance(value, dict):
                result[key] = deep_copy(value)
            elif isinstance(value, list):
                result[key] = [deep_copy(v) if isinstance(v, dict) else v for v in value] 
            else:
                result[key] = value
        return result

    return deep_copy(d)

