def categorize_students(students, passing_grade):
    """
    Categorizes students into "pass" or "fail" based on the given passing grade threshold.

    Parameters:
    - students (dict): A dictionary where keys are student names and values are their respective grades.
    - passing_grade (int): The grade threshold for passing.

    Returns:
    - dict: A dictionary with keys "pass" and "fail", mapping to lists of student names.
    """
    categorized = {"pass": [], "fail": []}

    for name, grade in students.items():
        if grade >= passing_grade:
            categorized["pass"].append(name)
        else:
            categorized["fail"].append(name)

    return categorized

