def group_students_by_grade(student_info):
    """
    Groups students by their grades, with names sorted alphabetically within each grade group.

    :param student_info: List of strings where each string is in the form "name:grade".
    :return: Dictionary with grades as keys and lists of student names as values.
    """
    grade_dict = {}
    for info in student_info:
        name, grade = info.split(':')
        if grade not in grade_dict:
            grade_dict[grade] = []
        grade_dict[grade].append(name)

    for grade in grade_dict:
        grade_dict[grade].sort()

    return grade_dict

