def find_palindromic_substrings(s):
    """
    Returns a list of all unique palindromic substrings contained within the input string.
    """
    palindromic_substrings = set()

    def expand_around_center(left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            palindromic_substrings.add(s[left:right+1])
            left -= 1
            right += 1

    for i in range(len(s)):
        # Odd length palindromes
        expand_around_center(i, i)
        # Even length palindromes
        expand_around_center(i, i + 1)

    return list(palindromic_substrings)

