def categorize_temperatures(temperatures):
    """
    This function accepts a list of integers representing temperatures in Celsius,
    and returns a new list with corresponding temperature categories.
    """
    categories = []
    for temp in temperatures:
        if temp < 10:
            categories.append("Cold")
        elif 10 <= temp <= 25:
            categories.append("Warm")
        else:
            categories.append("Hot")
    return categories

