def smooth_list(nums):
    """
    Given a list of integers, returns a new list where each element is
    the average of itself and its previous and next elements in the original list.
    For elements at the beginning or the end of the list, only use the neighboring elements that exist.
    """
    if not nums:
        return []
    if len(nums) == 1:
        return nums

    smoothed = []
    for i in range(len(nums)):
        if i == 0:
            average = (nums[i] + nums[i + 1]) / 2
        elif i == len(nums) - 1:
            average = (nums[i - 1] + nums[i]) / 2
        else:
            average = (nums[i - 1] + nums[i] + nums[i + 1]) / 3

        smoothed.append(average)

    return smoothed

