def get_permutations(s):
    """
    Returns all the permutations of the given string s.
    """
    if len(s) == 1:
        return [s]
    permutations = []
    for i, char in enumerate(s):
        remaining = s[:i] + s[i+1:]
        for perm in get_permutations(remaining):
            permutations.append(char + perm)
    return permutations

