def mark_words_as_seen_and_removed(first_list, second_list):
    """
    Mark words in first_list as 'seen' if they are present in second_list and mark the corresponding word in second_list as 'removed'.
    """
    for i, word in enumerate(first_list):
        if word in second_list:
            first_list[i] = 'seen'
            second_list[second_list.index(word)] = 'removed'
    return first_list, second_list

