def generate_permutations(lst):
    """
    Generate all permutations of a given list of integers.
    """
    if len(lst) == 1:
        return [lst]  # Base case: list with one element
    elif len(lst) == 0:
        return [[]]  # Base case: empty list
    else:
        permutations = []
        for i in range(len(lst)):
            first_element = lst[i]
            rest_of_list = lst[:i] + lst[i+1:]
            for permutation in generate_permutations(rest_of_list):
                permutations.append([first_element] + permutation)
        return permutations

