def merge_item_quantities(items):
    """
    Merges the quantities of the same items together.

    Parameters:
    items (list): A list of dictionaries, where each dictionary represents an item and its quantity.

    Returns:
    list: A new list of dictionaries where the quantities of the same items are merged together.
    """
    merged_items_dict = {}
    for item in items:
        if item["item"] in merged_items_dict:
            merged_items_dict[item["item"]] += item["quantity"]
        else:
            merged_items_dict[item["item"]] = item["quantity"]

    merged_items = [{"item": key, "quantity": value} for key, value in merged_items_dict.items()]

    return merged_items

