def find_first_last_indices(lst):
    """
    Returns a dictionary where the keys are the elements in the list and the values are tuples containing
    the indices of the first and last occurrence of each element.
    """
    return {element: (lst.index(element), len(lst) - 1 - lst[::-1].index(element)) for element in set(lst)}

