def categorize_age(age):
    """
    Categorizes a person based on their age.

    Args:
        age (int): The age to categorize.

    Returns:
        str: The category of the age.
    """
    if age < 0:
        return 'Invalid age'
    elif age < 13:
        return 'Child'
    elif age < 18:
        return 'Teenager'
    elif age < 65:
        return 'Adult'
    else:
        return 'Senior'

