def find_max(matrix):
    """
    Returns the maximum element in the last column of the matrix.
    """
    if not matrix or not matrix[0]:
        return None  # edge case where matrix is empty or has empty sublists

    last_column_elements = [row[-1] for row in matrix]
    return max(last_column_elements)

