def get_subsets(nums):
    """
    Returns all possible subsets of a list of numbers.
    """
    subsets = []
    num_subsets = 2 ** len(nums)
    for i in range(num_subsets):
        subset = []
        for j in range(len(nums)):
            if (i & (1 << j)) != 0:
                subset.append(nums[j])
        subsets.append(subset)
    return subsets

