def separate_players(players):
    """
    Separates players into two teams: TeamA and TeamB in an alternating manner.

    Args:
    players (list): List of player names (str).

    Returns:
    dict: A dictionary with two keys "TeamA" and "TeamB" with lists of player names.
    """
    teams = {"TeamA": [], "TeamB": []}

    for i, player in enumerate(players):
        if i % 2 == 0:
            teams["TeamA"].append(player)
        else:
            teams["TeamB"].append(player)

    return teams

