def detect_duplicates(lst):
    """
    Returns a list of tuples where there are duplicate integers and the string is not the same.

    :param lst: List of tuples, where each tuple contains a string and an integer.
    :return: List of tuples meeting the criteria.
    """
    duplicates = []
    seen = {}

    for string, number in lst:
        if number in seen and seen[number] != string:
            duplicates.append((string, number))
        seen[number] = string

    return duplicates

