def symmetric_pairs(pairs):
    """
    Returns a list of symmetric pairs from the given list of pairs.
    (a, b) is symmetric to (c, d) if a == d and b == c.
    """
    seen = set()
    symmetric = []

    for pair in pairs:
        if (pair[1], pair[0]) in seen:
            symmetric.append((pair[1], pair[0]))
        else:
            seen.add(pair)

    return symmetric

