def max_consecutive_ones(bits):
    """
    Determine the maximum number of 1s in any consecutive sequence of 20 bits.
    """
    max_ones = 0
    current_ones = 0
    for bit in bits:
        if bit == 1:
            current_ones += 1
        else:
            current_ones = 0
        max_ones = max(max_ones, current_ones)
    return min(max_ones, 20)

