def binary_to_decimal(binary_str):
    """
    Converts a binary number (given as string) to a decimal number using recursion.
    :param binary_str: str
    :return: int
    """
    def convert(binary_str, index):
        if index == -1:
            return 0
        return int(binary_str[index]) * (2 ** (len(binary_str) - 1 - index)) + convert(binary_str, index - 1)

    return convert(binary_str, len(binary_str) - 1)

