import math


def check_number(num):
    """
    Check if the given number is a Perfect Square, a Perfect Cube, Both or Neither.
    """
    is_perfect_square = math.isqrt(num) ** 2 == num
    cube_root = round(num ** (1/3))
    is_perfect_cube = cube_root ** 3 == num

    if is_perfect_square and is_perfect_cube:
        return f"The number {num} is a Perfect Square and a Perfect Cube."
    elif is_perfect_square:
        return f"The number {num} is a Perfect Square."
    elif is_perfect_cube:
        return f"The number {num} is a Perfect Cube."
    else:
        return f"The number {num} is Neither a Perfect Square nor a Perfect Cube."

