def permute(s):
    """
    Returns all permutations of a given string.
    """
    if len(s) == 0:
        return ['']

    result = []
    for i, char in enumerate(s):
        remaining = s[:i] + s[i+1:]
        for permutation in permute(remaining):
            result.append(char + permutation)
    return result

