def get_last_msg(log, username):
    """
    Returns the most recent message from the IRC log for the given username.

    :param log: List of tuples containing (msg_time, msg_username, msg_type, msg_text)
    :param username: The username to filter messages for
    :return: A dictionary containing the most recent message or an error message if log is empty
    """
    if not log:
        return {"error": "log is empty"}

    user_msgs = [msg for msg in log if msg[1] == username]

    if not user_msgs:
        return {"error": "no messages for given username"}

    last_msg = max(user_msgs, key=lambda x: x[0])
    return {
        "msg_time": last_msg[0],
        "msg_username": last_msg[1],
        "msg_type": last_msg[2],
        "msg_text": last_msg[3]
    }

