def hamming_distance(str1, str2):
    """
    Calculate the Hamming distance between two binary strings of equal length.
    """
    if len(str1) != len(str2):
        raise ValueError("Strings must be the same length.")

    distance = 0
    for i in range(len(str1)):
        if str1[i] != str2[i]:
            distance += 1
    return distance

