def string_length(s):
    """
    Returns the length of the string s.
    If s is None or an empty string, return an appropriate error message.
    If s contains any numbers, raise a ValueError.
    """
    if s is None:
        return "Input string is None"
    if s == "":
        return "Input string is empty"
    if any(char.isdigit() for char in s):
        raise ValueError("Input string contains numbers")

    return len(s)

