def create_multiplication_table(size):
    """
    Create a multiplication table of the specified size and 
    store it in a dictionary format.

    Parameters:
    size (int): The size of the multiplication table.

    Returns:
    dict: A dictionary containing the multiplication table.
    """
    table = {}

    for i in range(1, size + 1):
        table[i] = {}
        for j in range(1, size + 1):
            table[i][j] = i * j

    return table

