def calculate_resistance(resistors, formula):
    """
    Calculate the total resistance of resistors based on the given formula.

    :param resistors: List of resistor values.
    :param formula: 'parallel' or 'series'.
    :return: Calculated resistance value.
    :raises ValueError: If formula is invalid or non-numeric values are entered as resistor values.
    """
    if not all(isinstance(r, (int, float)) for r in resistors):
        raise ValueError("All resistors must be numeric values.")

    if formula == 'series':
        return sum(resistors)
    elif formula == 'parallel':
        try:
            return 1 / sum(1 / r for r in resistors)
        except ZeroDivisionError:
            raise ValueError("Resistor values must be non-zero for parallel calculation.")
    else:
        raise ValueError("Invalid formula choice. Must be 'parallel' or 'series'.")

def get_long_strings(string_list):
    """
    Filters the given list of strings and returns a new list containing only strings longer than 4 characters.
    """
    def custom_len(s):
        count = 0
        for _ in s:
            count += 1
        return count

    return [string for string in string_list if custom_len(string) > 4]

def calibrate_spinner(spins):
    """
    Calibrates the spinner by checking the proportion of each color.

    Args:
    spins (list of str): List of colors obtained from spinning the spinner.

    Returns:
    dict: A dictionary with colors as keys and their proportions as values.
    """
    if not spins:
        return {"R": 0.0, "B": 0.0, "G": 0.0, "Y": 0.0, "O": 0.0}

    total_spins = len(spins)
    colors_count = {"R": 0, "B": 0, "G": 0, "Y": 0, "O": 0}

    for color in spins:
        if color in colors_count:
            colors_count[color] += 1

    colors_proportion = {color: count / total_spins for color, count in colors_count.items()}
    return colors_proportion

