def create_nested_dictionary(keys, values):
    """
    Creates a nested dictionary from two lists, one of keys and the other of values.
    """
    result = {}

    for key, value in zip(keys, values):
        if isinstance(value, list) and len(value) > 1:
            nested_dict = {value[0]: value[1:]}
            result[key] = nested_dict
        else:
            result[key] = value

    return result

