def modify_map(game_map):
    """
    Modifies the game map such that every zero to the left of the first 1 is filled with 2.

    :param game_map: List[List[int]] - A two-dimensional array representing the game map
    :return: List[List[int]] - The modified game map
    """
    for row in game_map:
        try:
            first_one_index = row.index(1)
            for i in range(first_one_index):
                row[i] = 2
        except ValueError:
            # No '1' in the current row, do nothing
            pass
    return game_map

