def factorial(n):
    """
    Returns the factorial of a given non-negative integer n.
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    if n == 0:
        return 1  # Base case
    else:
        return n * factorial(n-1)

