def fibonacci(n):
    """
    Returns the Fibonacci series value at position n.
    Raises a ValueError for incorrect inputs.
    """
    if not isinstance(n, int):
        return "Invalid input: Input must be an integer."
    if n < 0:
        return "Invalid input: Input must be a non-negative integer."
    if n == 0:
        return 0
    if n == 1:
        return 1
    return fibonacci(n - 1) + fibonacci(n - 2)

