def sum_of_differences(tuples_list):
    """
    Returns the sum of the differences (a - b) for tuples (a, b) where a >= 2 * b.
    """
    total_sum = 0
    for a, b in tuples_list:
        if a >= 2 * b:
            total_sum += (a - b)
    return total_sum

