def fizz_buzz_gen(n):
    """
    Generator function that yields FizzBuzz results for numbers from 1 to n.
    """
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            yield 'FizzBuzz'
        elif i % 3 == 0:
            yield 'Fizz'
        elif i % 5 == 0:
            yield 'Buzz'
        else:
            yield str(i)

def reverse_and_stringify(numbers):
    """
    Takes a list of numbers, reverses it, and converts it to a string representation.
    """
    reversed_numbers = []
    for i in range(len(numbers)-1, -1, -1):
        reversed_numbers.append(numbers[i])
    return str(reversed_numbers)

