def average_word_count(strings):
    """
    Returns the average number of words per string in the input list of strings.

    :param strings: A list of strings
    :return: The average number of words across all strings
    """
    if not strings:
        return 0.0

    total_words = 0
    for s in strings:
        total_words += len(s.split())

    return total_words / len(strings)

