def is_valid_ipv4_address(address):
    """
    Returns True if the provided string is a valid IPv4 address, False otherwise.
    """
    parts = address.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        # Check if the part is a number
        if not part.isdigit():
            return False
        # Check if the number is between 0 and 255
        num = int(part)
        if num < 0 or num > 255:
            return False
        # Check for leading zeros
        if part.startswith('0') and len(part) > 1:
            return False

    return True

def first_odd_occurrence(nums):
    """
    Returns the first integer that appears an odd number of times in the list.
    If no such integer is found, returns None.
    """
    count_dict = {}
    for num in nums:
        count_dict[num] = count_dict.get(num, 0) + 1

    for num in nums:
        if count_dict[num] % 2 != 0:
            return num

    return None

