def test_rotate_byte_sequence_left():
    assert rotate_byte_sequence(b'\x01', 'left', 1) == b'\x02'
    assert rotate_byte_sequence(b'\x80', 'left', 1) == b'\x01'
    assert rotate_byte_sequence(b'\xaa', 'left', 3) == b'U'

def test_rotate_byte_sequence_right():
    assert rotate_byte_sequence(b'\x01', 'right', 1) == b'\x80'
    assert rotate_byte_sequence(b'\x02', 'right', 1) == b'\x01'
