def calculate_fibonacci(n, starting_values=[0, 1]):
    """
    Calculates the nth Fibonacci number using iteration.
    Allows for custom starting values of the Fibonacci sequence.

    :param n: The position in the Fibonacci sequence.
    :param starting_values: A list of two integers to start the Fibonacci sequence.
    :return: The nth Fibonacci number.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if len(starting_values) != 2:
        raise ValueError("starting_values must contain exactly two elements")

    a, b = starting_values
    if n == 0:
        return a
    elif n == 1:
        return b

    for _ in range(2, n+1):
        a, b = b, a + b

    return b

