def transpose_matrix(matrix):
    """
    Transposes a non-square 2D matrix in-place and returns the transposed matrix.
    """
    if not matrix:
        return matrix

    row, col = len(matrix), len(matrix[0])

    # If matrix is not square, let's create a new transposed matrix
    transposed = [[None]*row for _ in range(col)]

    for r in range(row):
        for c in range(col):
            transposed[c][r] = matrix[r][c]

    return transposed

