def char_frequency(strings):
    """
    Returns a dictionary containing the frequency of each unique character across all strings in the list.
    """
    frequency_dict = {}

    for string in strings:
        for char in string:
            if char in frequency_dict:
                frequency_dict[char] += 1
            else:
                frequency_dict[char] = 1

    return frequency_dict

