def enhance_person_info(person_list):
    """
    Enhance a list of person dicts into a more detailed dict with average age and occupation counts.

    Parameters:
    person_list (list): A list of dicts with 'name', 'age', and 'occupation' as keys.

    Returns:
    dict: A dict with a 'name' key and dict value containing 'average_age' and 'occupations'.
    """
    if not person_list:
        return {}

    total_age = 0
    occupations_count = {}

    for person in person_list:
        total_age += person['age']

        occupation = person['occupation']
        if occupation not in occupations_count:
            occupations_count[occupation] = 0
        occupations_count[occupation] += 1

    average_age = total_age / len(person_list)
    occupations = [{'occupation': occ, 'count': count} for occ, count in occupations_count.items()]

    result = {
        'average_age': average_age,
        'occupations': occupations
    }

    return {'name': 'EnhancedPersonInfo', 'details': result}

