def hygiene_update(bias):
    """
    Updates extreme hygiene practices based on the given bias.

    Parameters:
    bias (str): The bias indicating the state of illness. Possible values are:
                "cough", "sneeze", "both", "none"

    Returns:
    str: A message with recommended hygiene practices.
    """

    if bias == "cough":
        return "Cover your mouth and nose with a tissue when you cough. Dispose of the tissue properly and wash your hands."
    elif bias == "sneeze":
        return "Cover your mouth and nose with a tissue when you sneeze. Dispose of the tissue properly and wash your hands."
    elif bias == "both":
        return "Cover your mouth and nose with a tissue when you cough or sneeze. Dispose of the tissue properly and wash your hands frequently."
    elif bias == "none":
        return "Maintain good hygiene practices regardless of symptoms to prevent illness."
    else:
        return "Invalid input. Please provide one of the following values for bias: 'cough', 'sneeze', 'both', 'none'."

