def delete_all_occurrences(lst, element):
    """
    Deletes all occurrences of a specific element from the list without using the built-in remove() function.
    """
    write_index = 0
    for read_index in range(len(lst)):
        if lst[read_index] != element:
            lst[write_index] = lst[read_index]
            write_index += 1

    # Resize the list to the new size after deletions
    while len(lst) > write_index:
        lst.pop()

    return lst

