def create_set_and_find_duplicates(iterable, ignore_case=False):
    """
    Create a set from the iterable and find duplicate elements with their counts.

    Parameters:
    iterable (iterable): The input iterable to process.
    ignore_case (bool): Whether to ignore case for string values.

    Returns:
    tuple: A tuple containing the set of unique elements and a dictionary of duplicate elements with their counts.
    """
    element_count = {}
    duplicates = {}

    for elem in iterable:
        if ignore_case and isinstance(elem, str):
            elem = elem.lower()

        if elem in element_count:
            element_count[elem] += 1
        else:
            element_count[elem] = 1

    unique_elements = set(iterable)
    for key, count in element_count.items():
        if count > 1:
            duplicates[key] = count

    return unique_elements, duplicates

