def create_index_product_dict(list1, list2):
    """
    Creates a dictionary with elements from two lists as keys. The value for each key
    is a list of tuples, where each tuple contains the index of the element in the first list,
    the index of the element in the second list, and the product of these elements along with
    their total occurrences in both lists.
    """
    result = {}
    combined_list = list1 + list2

    for element in set(combined_list):
        result[element] = []
        total_count = combined_list.count(element)
        for i, el1 in enumerate(list1):
            if el1 == element:
                for j, el2 in enumerate(list2):
                    if el2 == element:
                        result[element].append((i, j, el1 * el2, total_count))
    return result

