def rotate_matrix(matrix, angle):
    """
    Rotates the given matrix by the specified angle in the clockwise direction.

    Parameters:
    matrix (list of list of int): The matrix to be rotated.
    angle (int): The angle by which to rotate the matrix (90, 180, 270, 360).

    Returns:
    list of list of int: The rotated matrix.
    """
    def rotate_90(mat):
        return [list(reversed(col)) for col in zip(*mat)]

    def rotate_180(mat):
        return [row[::-1] for row in mat[::-1]]

    def rotate_270(mat):
        return [list(col) for col in zip(*mat)][::-1]

    if angle == 90:
        return rotate_90(matrix)
    elif angle == 180:
        return rotate_180(matrix)
    elif angle == 270:
        return rotate_270(matrix)
    elif angle == 360:
        return [row[:] for row in matrix]
    else:
        raise ValueError("Angle must be one of the following values: 90, 180, 270, 360")

