def prime_factors(n, factor=2):
    """
    Returns a list of prime factors of a given number n using recursive method.
    """
    if n <= 1:
        return []
    if n % factor == 0:
        return [factor] + prime_factors(n // factor, factor)
    else:
        return prime_factors(n, factor + 1)

