def intersperse(arr, delimiter):
    """
    Returns a new array with the elements of arr interspersed with delimiter.
    """
    if not arr:
        return []

    result = []
    for i in range(len(arr)):
        result.append(arr[i])
        if i != len(arr) - 1:
            result.append(delimiter)

    return result

