def compare_strings(str1, str2):
    """
    Compares two strings lexicographically without using built-in functions.
    Returns:
        -1 if str1 < str2
         0 if str1 == str2
         1 if str1 > str2
    """
    min_len = min(len(str1), len(str2))

    for i in range(min_len):
        if str1[i] < str2[i]:
            return -1
        elif str1[i] > str2[i]:
            return 1

    if len(str1) < len(str2):
        return -1
    elif len(str1) > len(str2):
        return 1
    else:
        return 0

