def find_n_second_largest(lst, n):
    """
    Returns the n-th second largest number in the list.
    If the n-th second largest number does not exist, returns None.
    """
    if not lst or n < 1:
        return None

    lst = list(set(lst))  # Remove duplicates
    lst.sort(reverse=True)

    if len(lst) >= n + 1:
        return lst[n]
    else:
        return None

def compress_string(input_string):
    """
    Returns the compressed version of the given string.
    If a character is repeated consecutively, it is represented by that character followed by the count of repetitions.
    """
    if not input_string:
        return ""

    compressed_str = []
    count = 1
    prev_char = input_string[0]

    for char in input_string[1:]:
        if char == prev_char:
            count += 1
        else:
            compressed_str.append(prev_char + str(count))
            prev_char = char
            count = 1

    compressed_str.append(prev_char + str(count))  # for the last character group

    return ''.join(compressed_str)

