def gcd(a, b):
    """
    Returns the Greatest Common Divisor (GCD) of two integers a and b using Euclid's algorithm.
    """
    if a == 0: return abs(b)
    if b == 0: return abs(a)

    while b != 0:
        a, b = b, a % b
    return abs(a)

def construct_square_dict_with_parity(numbers):
    """
    This function takes a list of numbers and returns a dictionary with two keys: 'Even' and 'Odd'.
    Each key maps to another dictionary where the keys are the numbers from the input list, and the 
    values are their squares. Whether the square is even or odd determines which main key it belongs to.

    :param numbers: List of integers
    :return: Dictionary with keys 'Even' and 'Odd'
    """
    result = {'Even': {}, 'Odd': {}}
    for number in numbers:
        square = number ** 2
        if square % 2 == 0:
            result['Even'][number] = square
        else:
            result['Odd'][number] = square
    return result

