import math


def is_perfect_square(n):
    """
    Checks whether a number is a perfect square.
    Returns a tuple (valid, result). `valid` is False if the input is non-integer or negative,
    and `result` contains the appropriate error message or the True/False result of the perfect square check.
    """
    if not isinstance(n, int):
        return (False, "Input is not an integer")
    if n < 0:
        return (False, "Input is not positive")

    sqrt_n = int(math.sqrt(n))
    return (True, sqrt_n * sqrt_n == n)

