def catalan_number(n, memo=None):
    """
    Returns the nth Catalan number using memoization.
    """
    if memo is None:
        memo = {}

    if n in memo:
        return memo[n]

    if n == 0:
        return 1

    result = 0
    for i in range(n):
        result += catalan_number(i, memo) * catalan_number(n - 1 - i, memo)

    memo[n] = result
    return result

def separate_numbers(arr):
    """
    Separates the negative numbers from the positive numbers in the given array.

    Parameters:
    arr (list of int): List of integers.

    Returns:
    dict: A dictionary with two keys 'positive' and 'negative', containing lists of positive and negative numbers respectively.
    """
    result = {"positive": [], "negative": []}
    for num in arr:
        if num < 0:
            result["negative"].append(num)
        elif num >= 0:
            result["positive"].append(num)
    return result

