def permute_string(s):
    """
    Generates all possible permutations of the input string s.
    """
    def permute(prefix, suffix, result):
        if len(suffix) == 0:
            result.append(prefix)
        else:
            for i in range(len(suffix)):
                new_prefix = prefix + suffix[i]
                new_suffix = suffix[:i] + suffix[i+1:]
                permute(new_prefix, new_suffix, result)

    result = []
    permute('', s, result)
    return result

