def remove_duplicates(nums):
    """
    Given the sorted array of integers nums, returns the array sorted 
    in strictly increasing order after removing the duplicates in place.
    """
    if not nums:
        return nums

    write_index = 1
    for i in range(1, len(nums)):
        if nums[i] != nums[i - 1]:
            nums[write_index] = nums[i]
            write_index += 1

    return nums[:write_index]

