def is_symmetric(matrix):
    """
    Returns True if the matrix is symmetric, False otherwise.
    A matrix is symmetric if matrix[i][j] == matrix[j][i] for all valid i and j.
    """
    if not matrix:
        return True

    m = len(matrix)
    n = len(matrix[0])

    if m != n:
        return False

    for i in range(m):
        for j in range(n):
            if matrix[i][j] != matrix[j][i]:
                return False
    return True

