def rotational_cipher(text, rotation_factor):
    """
    Encrypts the input text using a rotational cipher with the given rotation_factor.
    """
    result = []

    for char in text:
        if char.isalpha():
            if char.islower():
                result.append(chr((ord(char) - ord('a') + rotation_factor) % 26 + ord('a')))
            else:
                result.append(chr((ord(char) - ord('A') + rotation_factor) % 26 + ord('A')))
        elif char.isdigit():
            result.append(chr((ord(char) - ord('0') + rotation_factor) % 10 + ord('0')))
        else:
            result.append(char)

    return ''.join(result)

