def sort_dict_by_value_ignore_multiples_of_3(d):
    """
    Returns a dictionary sorted by its values in ascending order, 
    ignoring any values that are multiples of 3.

    The returned dictionary should preserve the original order 
    for keys with the same value.
    """
    sorted_dict = {}
    for key, value in sorted(d.items(), key=lambda item: (item[1], list(d).index(item[0]))):
        if value % 3 != 0:
            sorted_dict[key] = value
    return sorted_dict

