def additive_cipher(message, key):
    """
    Encrypts the given message using an additive cipher with the given key.

    Parameters:
    message (str): The message to encrypt.
    key (int): The key used for the encryption which is the shift value.

    Returns:
    str: The encrypted message.
    """
    encrypted_message = []
    for char in message:
        if char.isalpha():  # Only encrypt alphabetic characters
            shift = key % 26
            if char.islower():
                shifted = ord(char) + shift
                if shifted > ord('z'):
                    shifted -= 26
                encrypted_message.append(chr(shifted))
            elif char.isupper():
                shifted = ord(char) + shift
                if shifted > ord('Z'):
                    shifted -= 26
                encrypted_message.append(chr(shifted))
        else:
            encrypted_message.append(char)  # Non-alphabetic characters are not changed
    return ''.join(encrypted_message)

def dfs_cycle_detection(graph):
    """
    Perform a depth first search to detect a cycle in an undirected graph
    and return the first instance of a cycle identified by the nodes that form the cycle.

    :param graph: Dictionary representation of an undirected graph where key is node
                  and value is a list of connected nodes.
    :return: List of nodes that form the first detected cycle or None if no cycle is found.
    """
    visited = set()
    parent = {}

    def dfs(node, parent_node):
        visited.add(node)
        parent[node] = parent_node

        for neighbor in graph[node]:
            if neighbor not in visited:
                cycle_path = dfs(neighbor, node)
                if cycle_path:
                    return cycle_path
            elif neighbor != parent_node:
                # Cycle detected, construct the cycle path
                cycle_path = []
                current_node = node
                while current_node != neighbor:
                    cycle_path.append(current_node)
                    current_node = parent[current_node]
                cycle_path.append(neighbor)
                cycle_path.append(node)
                return cycle_path

        return None

    for node in graph:
        if node not in visited:
            cycle_path = dfs(node, None)
            if cycle_path:
                return cycle_path

    return None

