def complement_dna(dna):
    """
    Returns the complement of a DNA string by mapping each letter to its complement.
    """
    complement = {'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G'}
    return ''.join(complement[base] for base in dna)

