def count_unique_in_set(set1, set2):
    """
    This function takes two sets of integers and returns a dictionary with the counts
    of unique numbers in the first set that occur at least once in the second set.
    The function is optimized for handling large sets efficiently.
    """
    result = {}
    for num in set1:
        if num in set2:
            result[num] = result.get(num, 0) + 1
    return result

