def count_nucleotides(genomic_sequence):
    """
    Count the number of occurrences of each nucleotide ('A', 'C', 'G', 'T') in the given genomic sequence.

    Parameters:
    genomic_sequence (str): A string representation of the genomic sequence.

    Returns:
    dict: A dictionary with nucleotides as keys and their counts as values.
    """
    counts = {'A': 0, 'C': 0, 'G': 0, 'T': 0}

    for nucleotide in genomic_sequence:
        if nucleotide in counts:
            counts[nucleotide] += 1

    return counts

