def dict_from_nested_list(nested_list):
    """
    Returns a dictionary where keys are the strings present in the nested list,
    and values are lists of the surrounding items including relatives.
    """
    result = {}

    def get_surrounding(lst, item):
        """
        Helper function to get surrounding items of a specific item in the nested list.
        """
        surrounding = []
        for sub_lst in lst:
            if item in sub_lst:
                surrounding.extend(sub_lst)
        return surrounding

    for sublist in nested_list:
        for item in sublist:
            # Make sure the key is a string
            if isinstance(item, str):
                result[item] = get_surrounding(nested_list, item)

    return result

