def parse_string(input_string):
    """
    Parses the input string containing key-value pairs separated by colons and each pair separated by a comma.
    Returns a dictionary with the parsed key-value pairs.

    :param input_string: str, input string containing key-value pairs
    :return: dict, dictionary with key-value pairs
    """
    if not input_string:
        return {}

    result = {}
    pairs = input_string.split(',')

    for pair in pairs:
        key, value = pair.split(':')
        result[key.strip()] = value.strip()

    return result

