def compute_average(numbers):
    """
    Returns the average of a list of numbers, ignoring non-numeric values.
    If the list is empty or contains no numeric values, returns 0.
    """
    if not numbers:
        return 0

    valid_numbers = [num for num in numbers if isinstance(num, (int, float))]

    if not valid_numbers:
        return 0

    return sum(valid_numbers) / len(valid_numbers)

