def chatbot(prompt):
    """
    Simple chatbot that answers questions about a restaurant menu.
    """
    menu = {
        "appetizers": ["fries", "garlic bread", "mozzarella sticks"],
        "mains": ["cheeseburger", "grilled chicken", "vegan sandwich"],
        "desserts": ["ice cream", "apple pie", "chocolate cake"],
        "drinks": ["soda", "lemonade", "coffee", "tea"]
    }

    prompt = prompt.lower()

    if "appetizer" in prompt:
        return "Our appetizers are: " + ", ".join(menu["appetizers"])
    elif "main" in prompt:
        return "Our main dishes are: " + ", ".join(menu["mains"])
    elif "dessert" in prompt:
        return "Our desserts are: " + ", ".join(menu["desserts"])
    elif "drink" in prompt:
        return "Our drinks are: " + ", ".join(menu["drinks"])
    else:
        return "I'm sorry, I can only answer questions about appetizers, mains, desserts, and drinks."

