def even_fibonacci_sequence(terms):
    """
    Generates the Fibonacci sequence up to a given number of terms
    and returns only the even-valued terms.
    """
    a, b = 0, 1
    even_terms = []

    for _ in range(terms):
        a, b = b, a + b
        if a % 2 == 0:
            even_terms.append(a)

    return even_terms, sum(even_terms)

