def analyze_numbers(numbers):
    """
    Accepts a list of numbers and returns a dictionary containing 
    the minimum, maximum, and average of the numbers in the list.

    If the list is empty, returns an empty dictionary.
    """
    if not numbers:
        return {}

    min_num = min(numbers)
    max_num = max(numbers)
    avg_num = sum(numbers) / len(numbers)

    return {
        'min': min_num,
        'max': max_num,
        'average': avg_num
    }

