def calculate_averages(students_marks):
    """
    Adds an 'Average' key to each student's dictionary with the average mark for each subject.

    Params:
    students_marks (dict): Dictionary with student names as keys, and dictionaries of subject marks as values.

    Returns:
    dict: Updated dictionary with 'Average' key added for each student.
    """
    for student, subjects in students_marks.items():
        average_marks = {}
        for subject, marks in subjects.items():
            if isinstance(marks, list) and marks:
                average_marks[subject] = sum(marks) / len(marks)
        subjects["Average"] = average_marks
    return students_marks

