def list_people_above_30(people):
    """
    This function takes a list of dictionaries with keys 'name', 'age', and 'city', and returns 
    a formatted string listing all the people above 30 years old, with each person's information on a new line.
    """
    result = []
    for person in people:
        if person['age'] > 30:
            result.append(f"{person['name']}, {person['age']}, {person['city']}")

    if result:
        return "\n".join(result)
    else:
        return "No one is above 30."

