def to_hex(n):
    """
    Returns the hexadecimal representation of a number as a string, prefixed with '0x'.
    For negative numbers, two's complement form with a 32-bit integer representation is used.
    """
    if n >= 0:
        return hex(n)
    else:
        return hex((1 << 32) + n)

