def guess_number_game(target, guesses):
    """
    Simulates a guessing game. Returns feedback and the number of attempts to 
    guess the target.

    :param target: The number to guess (between 1 and 100 inclusive).
    :param guesses: A list of guesses made by the user.
    :return: A tuple containing the feedback for each guess and the number of attempts.
    """
    feedback = []
    for guess in guesses:
        if guess < target:
            feedback.append("Too low")
        elif guess > target:
            feedback.append("Too high")
        else:
            feedback.append("Correct")
            return feedback, len(feedback)

    # If the loop finishes without a correct guess
    return feedback, len(feedback)

def fizz_buzz(n):
    """
    Generates a list of numbers from 1 to n (inclusive), with numbers 
    divisible by 3 replaced by "Fizz", numbers divisible by 5 replaced 
    by "Buzz", and numbers divisible by both 3 and 5 replaced by "FizzBuzz".

    :param n: The upper limit of the range (inclusive).
    :return: The resulting list.
    """
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(i)
    return result

