def find_smallest_element_and_index(nums):
    """
    Returns a tuple containing the smallest element in the list and its index.
    """
    if not nums:
        raise ValueError("The list is empty")

    min_element = min(nums)
    min_index = nums.index(min_element)

    return (min_element, min_index)

