def calculate_total_cost(menu, items):
    """
    Calculates the total cost of the given items based on the prices in the menu.

    Parameters:
    menu (dict): A dictionary where keys are item names and values are their prices.
    items (list): A list of item names to be checked/purchased.

    Returns:
    float: Total cost of the items.

    Raises:
    ValueError: If an item is not found in the menu.
    """
    total_cost = 0
    try:
        for item in items:
            if item not in menu:
                raise ValueError(f"Item '{item}' not found in the menu")
            total_cost += menu[item]
    except ValueError as e:
        return str(e)
    return total_cost

