def sum_of_first_100_divisible_by_4(numbers):
    """
    This function takes a list of integers as input and returns the sum of the first 100 integers 
    from the list that are divisible by 4. If there are fewer than 100 such integers,
    the function returns the sum of all such integers. If there are no integers in the list 
    that are divisible by 4, the function returns 0.
    """
    sum_div4 = 0
    count = 0
    for number in numbers:
        if number % 4 == 0:
            sum_div4 += number
            count += 1
        if count == 100:
            break
    return sum_div4

