def construct_multilevel_dict(key_value_pairs, delimiter):
    """
    Constructs a multi-level dictionary from a list of key-value pairs, 
    where the keys are split by a specified delimiter to create a nested structure.

    :param key_value_pairs: List of tuples, each tuple contains (key, value)
    :param delimiter: String delimiter to split the keys
    :return: Multi-level dictionary
    """
    result = {}

    for key, value in key_value_pairs:
        keys = key.split(delimiter)
        d = result
        for k in keys[:-1]:
            if k not in d:
                d[k] = {}
            d = d[k]
        d[keys[-1]] = value

    return result

