def collatz_sequence(n):
    """
    Generates the Collatz conjecture sequence for a given positive integer n.
    Returns a list containing the sequence.
    """
    if n <= 0:
        raise ValueError("Input must be a positive integer.")

    sequence = [n]
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        sequence.append(n)
    return sequence

