def caesar_cipher(text, shift):
    """
    Encrypts the input text using Caesar cipher with the given shift value.

    Parameters:
    text (str): The string to be encrypted.
    shift (int): The shift value for the Caesar cipher.

    Returns:
    str: The encrypted string.
    """
    encrypted_text = []

    for char in text:
        if char.isalpha():
            shift_amount = shift % 26
            if char.islower():
                start = ord('a')
            else:
                start = ord('A')

            encrypted_char = chr(start + (ord(char) - start + shift_amount) % 26)
            encrypted_text.append(encrypted_char)
        else:
            encrypted_text.append(char)

    return ''.join(encrypted_text)

