def calculate_relative_frequencies(word_count_tuples):
    """
    Takes a list of tuples (word, count) and returns a dictionary with words as keys
    and their relative frequency as values. The relative frequency is the count of the word
    divided by the total number of words.

    :param word_count_tuples: List of tuples [(word1, count1), (word2, count2), ...]
    :return: Dictionary {word1: relative_frequency1, word2: relative_frequency2, ...}
    """
    total_count = sum(count for word, count in word_count_tuples)
    if total_count == 0:
        return {word: 0 for word, count in word_count_tuples}

    relative_frequencies = {word: count / total_count for word, count in word_count_tuples}
    return relative_frequencies

