def pyramid_pattern(n):
    """
    Creates a pyramid pattern using asterisks (*) for a given number of levels n.
    """
    pattern = []
    for i in range(n):
        spaces = ' ' * (n - i - 1)
        stars = '*' * (2 * i + 1)
        pattern.append(spaces + stars + spaces)
    return '\n'.join(pattern)

