def string_length_dict(string_list):
    """
    Creates a dictionary where each unique string in the list is a key,
    and the value is the length of that string.
    """
    length_dict = {}

    for string in string_list:
        if string not in length_dict:
            length = 0
            for char in string:
                length += 1
            length_dict[string] = length

    return length_dict

