def find_shortest_string(strings):
    """
    Returns the shortest string in the list. If there are multiple shortest strings, 
    returns the first one encountered. If the list is empty, returns None.
    """
    if not strings:
        return None

    shortest_string = strings[0]
    for string in strings[1:]:
        if len(string) < len(shortest_string):
            shortest_string = string
    return shortest_string

