def extract_user_data(json_obj):
    """
    Function to extract 'username', 'email', and 'registration_date' from a given JSON object,
    handling variability in the structure.
    :param json_obj: JSON object (dict)
    :return: Dictionary with extracted data or None if data not found
    """

    def find_key_recursively(obj, key):
        """ Helper function to recursively find a key in nested dictionaries and lists """
        if isinstance(obj, dict):
            if key in obj:
                return obj[key]
            for k, v in obj.items():
                result = find_key_recursively(v, key)
                if result is not None:
                    return result
        elif isinstance(obj, list):
            for item in obj:
                result = find_key_recursively(item, key)
                if result is not None:
                    return result
        return None

    user_data = {
        'username': find_key_recursively(json_obj, 'username'),
        'email': find_key_recursively(json_obj, 'email'),
        'registration_date': find_key_recursively(json_obj, 'registration_date')
    }

    if all(user_data.values()):
        return user_data
    return None

