def remove_double_characters(s):
    """
    Returns a new string with all double characters removed.
    """
    result = []
    i = 0
    while i < len(s):
        result.append(s[i])
        if i + 1 < len(s) and s[i] == s[i + 1]:
            i += 2
        else:
            i += 1
    return ''.join(result)

