def generate_combinations(lst, length):
    """
    Generate all possible combinations of the given list 'lst' without duplicates for a specified length.
    """
    if length == 0:
        return ['']
    if length == 1:
        return [str(e) for e in lst]

    combinations = []
    for i in range(len(lst)):
        element = lst[i]
        rest_combinations = generate_combinations(lst[:i] + lst[i+1:], length - 1)
        for combination in rest_combinations:
            combinations.append(str(element) + combination)

    return combinations

