def query_handler(query_params, query_types):
    """
    Handles different types of queries on the `query_params` dictionary as specified in `query_types`.

    Parameters:
    - query_params (dict): A dictionary containing the data to be queried.
    - query_types (dict): A dictionary containing the queries to be handled.

    Returns:
    dict: A dictionary containing the results for each query type.
    """
    results = {}

    for query_type, query_value in query_types.items():
        if query_type == 'simple_query':
            results[query_type] = query_params.get(query_value, None)

        elif query_type == 'range_query':
            start_key, end_key = query_value
            results[query_type] = {k: v for k, v in query_params.items() 
                                   if start_key <= k <= end_key}

        elif query_type == 'contains_query':
            results[query_type] = [k for k in query_params.keys() 
                                   if query_value in k]

    return results

