def number_to_words(number):
    """
    Takes a number and returns the corresponding word for each digit in the number.
    """
    digit_to_word = {
        '0': 'zero', '1': 'one', '2': 'two', '3': 'three',
        '4': 'four', '5': 'five', '6': 'six', '7': 'seven', 
        '8': 'eight', '9': 'nine'
    }
    num_str = str(number)
    words = [digit_to_word[digit] for digit in num_str]
    return ' '.join(words)

