def fizzbuzz(n):
    """
    Returns a list of strings representing the FizzBuzz sequence up to `n`.
    For multiples of three, it adds "Fizz". 
    For multiples of five, it adds "Buzz".
    For multiples of both three and five, it adds "FizzBuzz".
    Otherwise, it adds the number itself as a string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

