def smallest_odd(numbers):
    """
    Returns the smallest odd number in the list of integers.
    If there are no odd numbers, returns a message indicating that.
    """
    odd_numbers = [num for num in numbers if num % 2 != 0]
    if not odd_numbers:
        return "There are no odd numbers."
    return min(odd_numbers)

