def find_factors(numbers):
    """
    Returns a list of lists where each list contains the factors of the corresponding number
    from the input list `numbers`.
    """
    def factors(n):
        result = []
        for i in range(1, n + 1):
            if n % i == 0:
                result.append(i)
        return result

    return [factors(num) for num in numbers]

