def find_first_even_pair(lst):
    """
    Finds the first pair of even elements in the list.

    Parameters:
    lst (list): A list of integers.

    Returns:
    tuple: A tuple containing the first pair of even elements, or an empty tuple if no such pair exists.
    """
    for i in range(len(lst) - 1):
        if lst[i] % 2 == 0:
            for j in range(i + 1, len(lst)):
                if lst[j] % 2 == 0:
                    return (lst[i], lst[j])
    return ()

