def number_pattern(n):
    """
    Generates a number pattern where each number from 1 to n is repeated as many times as its value.
    Returns a string with the pattern.
    """
    pattern = []
    for i in range(1, n + 1):
        pattern.extend([str(i)] * i)
    return ' '.join(pattern)

