    json_response (dict): JSON dictionary object

    Returns:
    dict: A dictionary containing user's name and email
    """
    user_info = {'name': None, 'email': None}

    if 'user' in json_response:
        user_data = json_response['user']
        if 'name' in user_data:
            user_info['name'] = user_data['name']
        if 'email' in user_data:
            user_info['email'] = user_data['email']
    elif 'userInfo' in json_response:
        user_data = json_response['userInfo']
        if 'fullName' in user_data:
            user_info['name'] = user_data['fullName']
        if 'emailAddress' in user_data:
            user_info['email'] = user_data['emailAddress']

    return user_info

