def list_to_nested_dict(paths):
    """
    Convert a list of strings into a nested dictionary.
    Each string in the list acts as a path separator.
    """

    root = {}

    for path in paths:
        parts = path.split('/')
        current = root
        for part in parts:
            if part not in current:
                current[part] = {}
            current = current[part]

    return root

