def calculator(num1, num2, operation):
    """
    This function performs basic arithmetic operations: addition, subtraction, multiplication, and division.
    Parameters:
    - num1: First number (float or int)
    - num2: Second number (float or int)
    - operation: The operation to perform (str): 'add', 'subtract', 'multiply', 'divide'

    Returns:
    Result of the arithmetic operation (float or int), or an error message if invalid operation or division by zero.
    """
    if operation == 'add':
        return num1 + num2
    elif operation == 'subtract':
        return num1 - num2
    elif operation == 'multiply':
        return num1 * num2
    elif operation == 'divide':
        if num2 == 0:
            return "Error: Division by zero"
        return num1 / num2
    else:
        return "Error: Invalid operation"

