def sum_of_even_numbers(number_string):
    """
    Takes a string of space-separated numbers and returns the sum of the even numbers.
    If there are no even numbers, returns 'No even numbers found'.
    """
    numbers = map(int, number_string.split())
    even_numbers = [num for num in numbers if num % 2 == 0]

    if not even_numbers:
        return 'No even numbers found'

    return sum(even_numbers)

