def fibonacci(n):
    """
    Returns the first n terms of the Fibonacci sequence.
    """
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]

    fib_seq = fibonacci(n - 1)
    fib_seq.append(fib_seq[-1] + fib_seq[-2])
    return fib_seq

