def two_sum(nums, target):
    """
    Returns the 1-based indices of the two numbers in nums that add up to target.

    :param nums: List of integers
    :param target: Integer target sum
    :return: List with 1-based indices of the two numbers that add up to target
    """
    num_to_index = {}
    for index, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return [num_to_index[complement] + 1, index + 1]
        num_to_index[num] = index

