def compare_strings(str1, str2):
    """
    Returns the number of characters that match at the same position in both strings.
    Assumes both strings are of equal length.
    """
    count = 0
    for i in range(len(str1)):
        if str1[i] == str2[i]:
            count += 1
    return count

