from collections import deque


def bfs_detect_cycle(graph):
    """
    Detects a cycle in an undirected graph using BFS.

    :param graph: Adjacency list representation of the graph.
    :return: True if there is a cycle, False otherwise.
    """
    visited = set()

    for start_node in graph:
        if start_node not in visited:
            queue = deque([(start_node, None)])  # (current_node, parent_node)
            while queue:
                current_node, parent_node = queue.popleft()
                if current_node in visited:
                    return True
                visited.add(current_node)
                for neighbor in graph[current_node]:
                    if neighbor != parent_node:  # Check to avoid considering the edge to parent
                        queue.append((neighbor, current_node))
    return False

