def count_palindromic_substrings(s: str) -> int:
    """
    Returns the number of palindromic substrings in the given string.
    """
    def is_palindrome(sub: str) -> bool:
        return sub == sub[::-1]

    n = len(s)
    count = 0
    for i in range(n):
        for j in range(i, n):
            if is_palindrome(s[i:j+1]):
                count += 1
    return count

