def evaluate_postfix(expression):
    """
    Evaluates a mathematical expression given in postfix notation (Reverse Polish Notation, RPN).
    :param expression: List of strings representing the postfix expression
    :return: Result of the evaluated expression
    """
    stack = []
    operators = {'+', '-', '*', '/'}

    for token in expression:
        if token not in operators:
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                result = a + b
            elif token == '-':
                result = a - b
            elif token == '*':
                result = a * b
            elif token == '/':
                result = int(a / b)  # use int() to perform integer division
            stack.append(result)

    return stack[0]

