def binomial_coefficient(n, k, memo=None):
    """
    Returns the binomial coefficient "n choose k" using memoization.
    """
    if memo is None:
        memo = {}

    if (n, k) in memo:
        return memo[(n, k)]

    # Base cases
    if k == 0 or k == n:
        return 1

    # Recursive formula using the property: C(n, k) = C(n-1, k-1) + C(n-1, k)
    memo[(n, k)] = binomial_coefficient(n-1, k-1, memo) + binomial_coefficient(n-1, k, memo)
    return memo[(n, k)]

