def count_occurrences(lst):
    """
    Returns a dictionary with the count of occurrences of each unique element in the list.
    Handles both integers and strings.
    """
    occurrence_dict = {}
    for item in lst:
        if item in occurrence_dict:
            occurrence_dict[item] += 1
        else:
            occurrence_dict[item] = 1
    return occurrence_dict

