def get_primes(n, primes=None, current=2):
    """
    Returns a list of all prime numbers up to and including n using recursion.
    """
    if primes is None:
        primes = []

    if current > n:
        return primes

    if all(current % p != 0 for p in primes):
        primes.append(current)

    return get_primes(n, primes, current + 1)

