def count_words(text):
    """
    Returns a dictionary with the count of each unique word in the input string.
    """
    words = text.split()
    word_count = {}

    for word in words:
        word = word.lower()  # to ensure the word count is case insensitive
        word_count[word] = word_count.get(word, 0) + 1

    return word_count

