import re


def common_words(string1, string2):
    """
    Returns a list of common words between two strings, case-insensitive, and without any punctuation.
    """
    # Function to remove punctuation and convert to lower case
    def preprocess(string):
        # Remove punctuation using regex and convert to lower case
        return set(re.sub(r'[^\w\s]', '', string).lower().split())

    words1 = preprocess(string1)
    words2 = preprocess(string2)

    return list(words1 & words2)

