def find_median(nums):
    """
    Returns the median of a list of integers.
    If the list is empty, returns None.
    """
    if not nums:
        return None

    nums.sort()
    n = len(nums)
    mid = n // 2

    if n % 2 == 0:
        return (nums[mid - 1] + nums[mid]) / 2
    else:
        return float(nums[mid])

