def merge_dictionaries(dict1, dict2):
    """
    Merges two dictionaries into one while combining values of common keys.
    For common keys, the values will be combined into a list including values from both dictionaries.
    """
    merged_dict = {}

    # Collect keys from both dictionaries
    all_keys = set(dict1.keys()).union(set(dict2.keys()))

    for key in all_keys:
        # If the key exists in both dictionaries
        if key in dict1 and key in dict2:
            # Combine values into a list and use set to avoid duplicates
            merged_values = [dict1[key]] if not isinstance(dict1[key], list) else dict1[key]
            if isinstance(dict2[key], list):
                merged_values.extend(dict2[key])
            else:
                merged_values.append(dict2[key])
            # Remove duplicates by converting to set and back to list
            merged_dict[key] = list(set(merged_values))
        # If the key exists only in dict1
        elif key in dict1:
            merged_dict[key] = dict1[key]
        # If the key exists only in dict2
        else:
            merged_dict[key] = dict2[key]

    return merged_dict

