def is_valid_parentheses(s):
    """
    Returns True if the string s containing only parentheses "(" and ")" is valid.
    A string is valid if all parentheses are closed in the correct order.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

