def is_balanced(s):
    """
    Determine if the parentheses in the string are balanced.

    Args:
    s (str): A string containing only '(' and ')'.

    Returns:
    bool: True if the parentheses are balanced, False otherwise.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack.pop() != '(':
                return False
    return not stack

