def create_word_count_dict(text):
    """
    This function takes a string of text as input and returns a dictionary where the keys are
    the words in the text and the values are the number of times each word appears.

    Args:
        text (str): The input text string.

    Returns:
        dict: A dictionary containing word counts.
    """
    word_counts = {}
    for word in text.lower().split():
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1
    return word_counts

