def diff_dicts(dict1, dict2):
    """
    Finds the difference between two dictionaries.

    Args:
        dict1: The first dictionary.
        dict2: The second dictionary.

    Returns:
        A new dictionary containing the differences between dict1 and dict2.
    """
    diff_dict = {}

    # Check for differences or unique keys in dict1
    for key in dict1:
        if key not in dict2:
            diff_dict[key] = dict1[key]
        elif dict1[key] != dict2[key]:
            diff_dict[key] = dict1[key]

    # Check for unique keys in dict2
    for key in dict2:
        if key not in dict1:
            diff_dict[key] = dict2[key]

    return diff_dict

