def factorial(n):
    """
    Calculate the factorial of a given unsigned integer n using recursion.

    Parameters:
    n (int): The non-negative integer to calculate the factorial of.

    Returns:
    int/str: The factorial of n, or "Invalid input" if n > 12.
    """
    if n == 0:
        return 1
    elif n > 12:
        return "Invalid input"
    else:
        return n * factorial(n - 1)

