def firstUniqChar(s):
    """
    Returns the first non-repeating character in the given string.
    If all characters are repeating, returns '_'.
    """
    # Using a single pass through the string to create a count dictionary and a set for unique characters
    char_counts = {}
    for char in s:
        char_counts[char] = char_counts.get(char, 0) + 1

    # Iterate over string characters to find the first unique one
    for char in s:
        if char_counts[char] == 1:
            return char

    return "_"

