def longest_common_prefix_length(str1, str2):
    """
    Returns the length of the longest common prefix of two strings.
    """
    if not str1 or not str2:
        return 0
    if str1[0] == str2[0]:
        return 1 + longest_common_prefix_length(str1[1:], str2[1:])
    else:
        return 0

