def count_integers(data, processor=None):
    """
    Returns a dictionary with the integers as keys and the number of their occurrences in the list as values.
    If a processor function is provided, apply this function to each integer before counting.
    Non-integer values in the list are ignored.

    Parameters:
    data (list): List of elements where integers are counted.
    processor (function, optional): A function to process each integer before counting. Defaults to None.

    Returns:
    dict: Dictionary with integer keys and their counts as values.
    """
    counts = {}
    for item in data:
        if isinstance(item, int):
            if processor:
                processed = processor(item)
            else:
                processed = item
            counts[processed] = counts.get(processed, 0) + 1
    return counts

