from typing import List, Dict


def find_components(adj_list: Dict[int, List[int]]) -> List[List[int]]:
    """
    Finds and returns all the connected components of an undirected graph
    represented by the given adjacency list.

    :param adj_list: A dictionary where keys are vertex identifiers and values are lists of adjacent vertices.
    :return: A list of lists, each containing the vertices in one connected component, sorted in ascending order.
    """
    visited = set()
    components = []

    def dfs(vertex, current_component):
        stack = [vertex]
        while stack:
            v = stack.pop()
            if v not in visited:
                visited.add(v)
                current_component.append(v)
                for neighbor in adj_list[v]:
                    if neighbor not in visited:
                        stack.append(neighbor)

    for vertex in adj_list:
        if vertex not in visited:
            current_component = []
            dfs(vertex, current_component)
            components.append(sorted(current_component))

    # sort list of components by the first element of each component
    return sorted(components, key=lambda x: x[0])

