def update_robot_position(instructions):
    """
    Simulates the robot's movement and picking of items based on provided instructions.
    """
    current_shelf = None
    picked_items = []

    for instruction, value in instructions:
        if instruction == "move":
            current_shelf = value
        elif instruction == "pick":
            picked_items.append(value)

    return {
        "current_shelf": current_shelf,
        "picked_items": picked_items
    }

