def calculate_average_rating(reviews):
    """
    Calculate the average rating for each product.

    :param reviews: List of review dictionaries, each containing 'product_id' and 'rating'.
    :return: Dictionary with product_id as keys and the average rating as values (rounded to one decimal place).
    """
    # Step 1: Create a dictionary to keep track of the total ratings and counts for each product
    rating_data = {}

    # Step 2: Process each review to update the dictionary
    for review in reviews:
        product_id = review['product_id']
        rating = review['rating']

        if product_id in rating_data:
            rating_data[product_id]['total'] += rating
            rating_data[product_id]['count'] += 1
        else:
            rating_data[product_id] = {'total': rating, 'count': 1}

    # Step 3: Calculate the average rating for each product
    average_ratings = {}
    for product_id, data in rating_data.items():
        total = data['total']
        count = data['count']
        average_ratings[product_id] = round(total / count, 1)

    # Step 4: Return the resulting dictionary with averages rounded to one decimal place
    return average_ratings

