def strings_by_length(strings: list):
    """
    Returns a dictionary with the lengths of each string as keys and 
    lists of strings of that length as values. The keys are sorted
    and the lists are sorted alphabetically.
    """
    result = {}
    for string in strings:
        length = len(string)
        if length not in result:
            result[length] = []
        result[length].append(string)

    sorted_result = {}
    for key in sorted(result.keys()):
        sorted_result[key] = sorted(result[key])

    return sorted_result

