def rearrange_nested_dict(nested_dict, delimiter):
    """
    Flattens a nested dictionary by concatenating keys with a given delimiter and ensures all keys are in lowercase.
    """
    def flatten(d, parent_key=''):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{delimiter}{k.lower()}" if parent_key else k.lower()
            if isinstance(v, dict):
                items.extend(flatten(v, new_key).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten(nested_dict)

