def character_frequency(string_list):
    """
    Returns a dictionary where the keys are the unique characters found in all the strings,
    and the values are the number of times each character appears across all the strings.
    This function treats characters case-insensitively.
    """
    frequency_dict = {}
    for string in string_list:
        for char in string.lower():
            if char in frequency_dict:
                frequency_dict[char] += 1
            else:
                frequency_dict[char] = 1
    return frequency_dict

