def categorize_books(book_list):
    """
    Categorize books based on genre, year, and title.

    :param book_list: List of dictionaries, where each dictionary contains
                      information about a book with keys: 'title', 'author', 
                      'genre', and 'year'.
    :return: Nested dictionary with genre as the first level key, year as the 
             second level key, and a list of book titles as the values.
    """
    categorized_books = {}
    for book in book_list:
        genre = book['genre']
        year = book['year']
        title = book['title']

        if genre not in categorized_books:
            categorized_books[genre] = {}

        if year not in categorized_books[genre]:
            categorized_books[genre][year] = []

        categorized_books[genre][year].append(title)

    return categorized_books

