def find_common_elements(dicts_list):
    """
    Returns a sorted list of elements that are present in the value lists of all dictionaries in the input list.
    """
    if not dicts_list:
        return []

    # Get all the values from the first dictionary
    common_elements = set()
    for key in dicts_list[0]:
        common_elements.update(dicts_list[0][key])

    # Intersect with values from all other dictionaries
    for dictionary in dicts_list[1:]:
        current_values = set()
        for key in dictionary:
            current_values.update(dictionary[key])
        common_elements.intersection_update(current_values)

    return sorted(list(common_elements))

