def unique_sorted_elements(arr: list[int]) -> list[int]:
    """
    Given a sorted list of integers, returns a list containing only the unique elements in the same order.
    """
    if not arr:
        return []

    unique_elements = [arr[0]]
    for i in range(1, len(arr)):
        if arr[i] != arr[i - 1]:
            unique_elements.append(arr[i])
    return unique_elements

