def deepest_directory_depth(directory_structure: dict, current_depth=1) -> int:
    """
    Returns the depth of the deepest directory in a nested dictionary structure.
    """
    max_depth = current_depth
    for item in directory_structure.values():
        if isinstance(item, list):
            for sub_item in item:
                if isinstance(sub_item, dict):
                    for sub_dir in sub_item:
                        max_depth = max(max_depth, deepest_directory_depth(sub_item, current_depth + 1))
    return max_depth

