def collatz_cycle_length(n: int) -> int:
    """
    Returns the length of the Collatz cycle for a given positive integer n until n reaches 1.
    """
    count = 1
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        count += 1
    return count

