def shift_string(s: str) -> str:
    """
    Shifts each letter in the string by one position in the alphabet, preserving case.
    """
    result = []
    for char in s:
        if char.islower():
            if char == 'z':
                result.append('a')
            else:
                result.append(chr(ord(char) + 1))
        elif char.isupper():
            if char == 'Z':
                result.append('A')
            else:
                result.append(chr(ord(char) + 1))
    return ''.join(result)

