from typing import List, Tuple, Dict


def categorize_books(books: List[Tuple[str, str]]) -> Dict[str, int]:
    """
    Categorizes books based on their genres and calculates the total number of books in each genre.

    Parameters:
        books (List[Tuple[str, str]]): A list of tuples where each tuple contains the title and genre of a book.

    Returns:
        Dict[str, int]: A dictionary where the keys are genres and the values are the number of books in each genre.
    """
    genres_count = {}
    for title, genre in books:
        if not genre:
            genre = "Unknown"
        if genre in genres_count:
            genres_count[genre] += 1
        else:
            genres_count[genre] = 1
    return genres_count

