from typing import List, Dict


def summarize_orders(orders: List[Dict[str, int]]) -> Dict[str, int]:
    """
    Aggregates orders from multiple tables into a single dictionary 
    that contains the total count of each item ordered.
    """
    summary = {}
    for table_order in orders:
        for item, count in table_order.items():
            if item in summary:
                summary[item] += count
            else:
                summary[item] = count
    return dict(sorted(summary.items()))

