def find_path_to_destination(path):
    """
    Determines if a given list of floor positions represents a valid path for the robot.

    Parameters:
    path (list of int): A list of integers representing floor positions.

    Returns:
    bool: True if the path is valid, False otherwise.
    """
    if not path: 
        return True
    if len(path) == 1:
        return path[0] >= 0

    for i in range(1, len(path)):
        if path[i] != path[i - 1] + 1:
            return False

    return True

