def count_unique_words(text: str) -> dict:
    """
    Takes a string 'text' and returns a dictionary where the keys 
    are unique words in alphabetical order and the values are the 
    number of times each word appears in the text.
    """
    words = text.split()
    word_counts = {}

    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1

    sorted_word_counts = dict(sorted(word_counts.items()))
    return sorted_word_counts

