def is_rotation(arr1, arr2):
    """
    Determines if arr2 is a rotated version of arr1.
    """
    if len(arr1) != len(arr2):
        return False

    if not arr1:  # both arrays are empty
        return True

    concatenated = arr1 + arr1
    return ''.join(map(str, arr2)) in ''.join(map(str, concatenated))

