def generate_binary_strings(length: int) -> list:
    """
    Generate all possible combinations of binary strings of a given length.

    :param length: Length of the binary strings to be generated
    :return: A list containing all possible binary strings of the specified length
    """
    def generate(current, remaining_length):
        if remaining_length == 0:
            return [current]
        else:
            with_zero = generate(current + "0", remaining_length - 1)
            with_one = generate(current + "1", remaining_length - 1)
            return with_zero + with_one

    return generate("", length)

