from typing import List
import math


def least_common_interval(tasks: List[int]) -> int:
    """
    Calculate the least common interval (LCI) for the given list of task intervals.
    """
    def lcm(a, b):
        return abs(a * b) // math.gcd(a, b)

    current_lcm = tasks[0]
    for task in tasks[1:]:
        current_lcm = lcm(current_lcm, task)

    return current_lcm

