def generate_permutations(elements):
    """
    Generates all permutations of a list of distinct integers in lexicographical order.
    :param elements: List of distinct integers.
    :return: List of lists containing all permutations in lexicographical order.
    """
    def helper(current, remaining):
        if not remaining:
            permutations.append(current)
        else:
            for i in range(len(remaining)):
                helper(current + [remaining[i]], remaining[:i] + remaining[i+1:])

    elements.sort()  # Ensure that permutations are in lexicographical order
    permutations = []
    helper([], elements)
    return permutations

