def compute_factorial(n):
    """
    Computes the factorial of a given non-negative integer n.

    :param n: Integer, the number for which the factorial is to be computed.
    :return: A string representing the factorial of the given number or 'Invalid input' if n is negative.
    """
    if n < 0:
        return "Invalid input"

    result = 1
    for i in range(2, n + 1):
        result *= i

    return str(result)

