def frequency_count(numbers):
    """
    Returns a dictionary containing the frequency count of each unique integer in the list.
    If the input is not a list or contains non-integer elements, returns an appropriate error message.
    """
    if not isinstance(numbers, list):
        return "Error: Input should be a list."

    frequency = {}
    for number in numbers:
        if not isinstance(number, int):
            return "Error: List should only contain integers."
        frequency[number] = frequency.get(number, 0) + 1

    return frequency

