def count_file_extensions(file_list):
    """
    Returns a dictionary with extensions as keys and counts as values.

    Args:
    file_list (list of str): List of filenames with extensions.

    Returns:
    dict: Dictionary with extensions as keys and their counts as values.
    """
    extension_count = {}
    for filename in file_list:
        # Split the filename to separate the extension
        parts = filename.rsplit('.', 1)
        if len(parts) == 2:
            extension = parts[1]
            if extension in extension_count:
                extension_count[extension] += 1
            else:
                extension_count[extension] = 1
    return extension_count

