def categorize_by_type(items):
    """
    Categorizes items in a list by their datatype.

    Parameters:
    items (list): A list of mixed datatypes (integers, floats, and strings)

    Returns:
    dict: A dictionary where keys are datatypes ('int', 'float', 'str')
          and values are lists of items of that type.
    """
    categorized = {'int': [], 'float': [], 'str': []}

    for item in items:
        if isinstance(item, int):
            categorized['int'].append(item)
        elif isinstance(item, float):
            categorized['float'].append(item)
        elif isinstance(item, str):
            categorized['str'].append(item)

    return categorized

