def evaluate_expression(expression):
    """
    Evaluates a mathematical expression string containing integers and 
    the plus (+) and minus (-) operators and returns the result.
    """
    total = 0
    current_number = 0
    operator = '+'

    for char in expression:
        if char.isdigit():
            current_number = current_number * 10 + int(char)
        else:
            if operator == '+':
                total += current_number
            elif operator == '-':
                total -= current_number
            operator = char
            current_number = 0

    # To process the last number
    if operator == '+':
        total += current_number
    elif operator == '-':
        total -= current_number

    return total

