def unique_substrings(s, k):
    """
    Identifies all unique substrings of length k that appear in the string s.
    Returns them in an alphabetically sorted list.
    """
    if k > len(s):
        return []

    substrings = set()
    for i in range(len(s) - k + 1):
        substrings.add(s[i:i+k])

    return sorted(substrings)

