def count_vowels_consonants(s):
    """
    Calculate the number of vowels and consonants in the given string.

    Paramegers:
    s (str): The input string containing alphabetic characters and spaces.

    Returns:
    (int, int): A tuple containing the counts of vowels and consonants.
    """
    vowels = "aeiouAEIOU"
    vowel_count = 0
    consonant_count = 0

    for char in s:
        if char.isalpha():
            if char in vowels:
                vowel_count += 1
            else:
                consonant_count += 1

    return (vowel_count, consonant_count)

