def sum_and_product(arr):
    """
    Accept an array of integers and returns an object with two properties:
    'sum' containing the total sum of all integers, and 'product' containing the product of all integers.
    If the array is empty, the function returns { 'sum': 0, 'product': 1 }.
    """
    if not arr:
        return {'sum': 0, 'product': 1}

    total_sum = sum(arr)
    total_product = 1
    for num in arr:
        total_product *= num

    return {'sum': total_sum, 'product': total_product}

