def count_frequency(elements):
    """
    Returns a dictionary with the frequency of each integer in the list.
    Ignores any elements that are not integers.
    """
    frequency = {}
    for element in elements:
        if isinstance(element, int):
            if element in frequency:
                frequency[element] += 1
            else:
                frequency[element] = 1
    return frequency

