def calculate_frequency(input_string: str) -> dict:
    """
    Takes a string as input and returns a dictionary with the frequency of each character in the string.
    Ignores spaces and punctuation, and treats uppercase and lowercase characters as the same.
    """
    # Convert the input string to lowercase
    input_string = input_string.lower()

    # Initialize an empty dictionary to store the frequency of characters
    frequency_dict = {}

    # Iterate through each character in the string
    for char in input_string:
        # Ignore spaces and punctuation
        if char.isalnum():  # Checks if the character is alphanumeric (no spaces or punctuation)
            if char in frequency_dict:
                frequency_dict[char] += 1
            else:
                frequency_dict[char] = 1

    return frequency_dict

