def even_digit_sum(n: int) -> int:
    """
    Returns the sum of all even digits present in the integer n.
    If there are no even digits, the function returns 0.
    """
    sum_even_digits = 0
    for digit in str(n):
        if int(digit) % 2 == 0:
            sum_even_digits += int(digit)
    return sum_even_digits

