def letter_frequency(s):
    """
    Returns a dictionary with the frequency count of each letter in the string.
    The function is case-insensitive and ignores non-letter characters.
    """
    from collections import defaultdict
    frequency = defaultdict(int)

    for char in s:
        if char.isalpha():
            char = char.lower()
            frequency[char] += 1

    return dict(frequency)

