def is_bracket_sequence_valid(s):
    """
    Determines whether a given string contains properly nested and matched brackets.
    Returns True if the string consists of matching brackets, and False otherwise.
    """
    stack = []
    bracket_pair = {')': '(', ']': '[', '}': '{', '>': '<'}

    for char in s:
        if char in bracket_pair.values():  # opening brackets
            stack.append(char)
        elif char in bracket_pair:  # closing brackets
            if stack and stack[-1] == bracket_pair[char]:
                stack.pop()
            else:
                return False

    return len(stack) == 0

def process_numbers(numbers):
    """
    Processes a list of integers and returns a dictionary with keys:
    - "even_squares": a list of squares of all even numbers.
    - "odd_cubes": a list of cubes of all odd numbers.

    Parameters:
    numbers (list): List of integers to process.

    Returns:
    dict: A dictionary with "even_squares" and "odd_cubes" lists.
    """
    result = {
        "even_squares": [],
        "odd_cubes": []
    }

    for num in numbers:
        if num % 2 == 0:
            result["even_squares"].append(num**2)
        else:
            result["odd_cubes"].append(num**3)

    return result

