def count_pairs_with_sum(nums, k):
    """
    Returns the number of pairs of integers in the list that add up to k.

    Parameters:
    nums (list): List of integers.
    k (int): Target sum.

    Returns:
    int: Number of pairs that add up to k.
    """
    seen = {}
    count = 0

    for num in nums:
        complement = k - num
        if complement in seen:
            count += seen[complement]

        if num in seen:
            seen[num] += 1
        else:
            seen[num] = 1

    return count

