def palindromic_substrings(s):
    """
    Returns a list of all possible palindromic substrings in the input string s.
    """
    def is_palindrome(substr):
        return substr == substr[::-1]

    n = len(s)
    palindromes = []

    for i in range(n):
        for j in range(i, n):
            substr = s[i:j+1]
            if is_palindrome(substr):
                palindromes.append(substr)

    return palindromes

