def find_pairs_with_sum(list_of_integers, target):
    """
    Returns a list of unique tuples, each containing two distinct integers from 
    the input list that sum up to the target. Handles non-integer elements gracefully.
    """
    # Filter out non-integer elements
    valid_integers = set()
    for item in list_of_integers:
        if isinstance(item, int):
            valid_integers.add(item)

    seen = set()  # to keep track of numbers we have processed
    pairs = set()  # to store unique pairs

    for number in valid_integers:
        complement = target - number
        if complement in seen:
            pairs.add(tuple(sorted((number, complement))))
        seen.add(number)

    return list(pairs)

