def even_odd_dict(input_list):
    """
    Returns a dictionary with two keys, "even" and "odd". The value for each
    key is a list of integers from the input list that are even or odd, respectively.
    If the input list is empty, returns a dictionary with empty lists for both keys.
    """
    return {
        "even": [x for x in input_list if x % 2 == 0],
        "odd": [x for x in input_list if x % 2 != 0]
    }

