def is_balanced_parentheses(s):
    """
    Returns True if the parentheses string is balanced, False otherwise.
    """
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1

        # At any point, balance should not be negative
        if balance < 0:
            return False

    # The balance should be zero if the string is balanced
    return balance == 0

