def balanced_parentheses(s):
    """
    Check if the input string has balanced parentheses.

    Parameters:
    s (str): The input string containing parentheses.

    Returns:
    bool: True if the parentheses are balanced, False otherwise.
    """
    stack = []
    matching_parentheses = {
        ')': '(',
        ']': '[',
        '}': '{'
    }

    for char in s:
        if char in matching_parentheses.values():
            stack.append(char)
        elif char in matching_parentheses.keys():
            if stack == [] or matching_parentheses[char] != stack.pop():
                return False
    return len(stack) == 0

