def move_zeroes(nums: list):
    """
    Moves all zeroes in the list 'nums' to the end while maintaining the order of non-zero elements.
    The operation should be performed in-place with optimal time and space complexity.
    """
    zero_index = 0  # position to put the next non-zero element
    for i in range(len(nums)):
        if nums[i] != 0:
            nums[zero_index], nums[i] = nums[i], nums[zero_index]
            zero_index += 1

