def split_number(n):
    """
    Splits the number `n` into two parts where:
    - Both parts are positive integers.
    - Neither part contains the digit `2` or `6` in their decimal representation.

    Returns:
        list: A list [A, B] where A + B = n and neither A nor B contains the digit `2` or `6`.
    """
    def contains_unwanted_digits(number):
        return '2' in str(number) or '6' in str(number)

    for i in range(1, n):
        if not contains_unwanted_digits(i) and not contains_unwanted_digits(n - i):
            return [i, n - i]

