def merge_dictionaries(input_list, key_name):
    """
    Merge dictionaries in the input list based on the specified key.
    If multiple dictionaries have the same value for the key, their non-key values are combined into a list.

    Args:
    input_list (list): List of dictionaries.
    key_name (str): The key name to merge dictionaries by.

    Returns:
    list: A new list of dictionaries with merged results.
    """
    if not input_list:
        return []

    merged_dict = {}

    for item in input_list:
        key_value = item[key_name]

        if key_value not in merged_dict:
            merged_dict[key_value] = {k: [v] for k, v in item.items() if k != key_name}
        else:
            for k, v in item.items():
                if k != key_name:
                    merged_dict[key_value][k].append(v)

    return [{key_name: k, **{nk: nv for nk, nv in v.items()}} for k, v in merged_dict.items()]

def summarize_list_elements(lst):
    """
    Takes a list of integers and returns a dictionary summarizing the list's elements.

    :param lst: List of integers
    :return: Dictionary with counts of 'positive', 'negative', 'zero', 'even', 'odd', and the 'sum' of the list
    """
    summary = {
        'positive': 0,
        'negative': 0,
        'zero': 0,
        'even': 0,
        'odd': 0,
        'sum': 0
    }

    for num in lst:
        if num > 0:
            summary['positive'] += 1
        elif num < 0:
            summary['negative'] += 1
        else:
            summary['zero'] += 1

        if num % 2 == 0:
            summary['even'] += 1
        else:
            summary['odd'] += 1

        summary['sum'] += num

    return summary

