def evaluate(expression):
    """
    Evaluates an algebraic expression containing integers, +, and * operators.
    Respects standard operator precedence (multiplication before addition).
    """
    def evaluate_multiplication(expression):
        parts = expression.split('*')
        result = 1
        for part in parts:
            result *= int(part)
        return result

    add_parts = expression.split('+')
    total = 0
    for part in add_parts:
        if '*' in part:
            total += evaluate_multiplication(part)
        else:
            total += int(part)
    return total

