def maximum_product_of_three(nums):
    """
    Returns the maximum product that can be obtained by multiplying any three distinct numbers from the list.
    If the list contains fewer than three integers, return None.
    """
    if len(nums) < 3:
        return None

    nums.sort()
    return max(nums[-1] * nums[-2] * nums[-3], nums[0] * nums[1] * nums[-1])

