def find_pairs_with_sum(input_list, target_sum):
    """
    Returns a list of unique tuples with two distinct integers from the input list that add up to the target sum.
    """
    seen = set()
    pairs = set()

    for number in input_list:
        complement = target_sum - number
        if complement in seen:
            pair = tuple(sorted((number, complement)))
            pairs.add(pair)
        seen.add(number)

    return list(pairs)

