def employees_by_department(employees):
    """
    Takes a list of employee dictionaries and returns a dictionary where keys are department names
    and values are lists of employee names sorted in descending order by their years of experience.
    """
    if not employees:
        return {}

    dept_dict = {}
    for emp in employees:
        department = emp.get('department')
        name = emp.get('name')
        years_exp = emp.get('years_of_experience')

        if department not in dept_dict:
            dept_dict[department] = []

        dept_dict[department].append((name, years_exp))

    for dept in dept_dict:
        dept_dict[dept].sort(key=lambda x: x[1], reverse=True)
        dept_dict[dept] = [name for name, _ in dept_dict[dept]]

    return dept_dict

