def longest_subsequence(arr):
    """
    This function finds the length of the longest subsequence such that every adjacent element
    in the subsequence has a difference of either 1 or -1.

    :param arr: List of integers
    :return: Length of the longest subsequence with adjacent elements differing by 1 or -1
    """
    if not arr:
        return 0

    longest_length = 1
    current_length = 1

    for i in range(1, len(arr)):
        if abs(arr[i] - arr[i - 1]) == 1:
            current_length += 1
        else:
            longest_length = max(longest_length, current_length)
            current_length = 1

    return max(longest_length, current_length)

