def get_level(scores):
    """
    Returns a list of level strings based on the input list of scores.

    The levels are defined as follows:
    - 'beginner' if the score is less than 50
    - 'intermediate' if the score is between 50 and 80 (inclusive)
    - 'advanced' if the score is between 81 and 100 (inclusive)
    - 'expert' if the score is greater than 100
    """
    levels = []

    for score in scores:
        if score < 50:
            levels.append('beginner')
        elif 50 <= score <= 80:
            levels.append('intermediate')
        elif 81 <= score <= 100:
            levels.append('advanced')
        else:
            levels.append('expert')

    return levels

