def intersect(nums1, nums2):
    """
    Find the intersection of two integer arrays.
    Elements in the intersection are those present in both arrays.
    Each element in the result must be present in both arrays as many times as it shows in both arrays.
    """
    d = {}
    result = []
    for num in nums1:
        d[num] = d.get(num, 0) + 1
    for num in nums2:
        if num in d and d[num] > 0:
            d[num] -= 1
            result.append(num)
    return result

