from collections import defaultdict


def count_scc(graph):
    """
    Count the number of strongly connected components in a directed graph.

    Parameters:
    - graph (dict): A dictionary representing the adjacency list of the directed graph.

    Returns:
    - int: The number of strongly connected components.
    """
    def dfs(v, visited, stack):
        visited.add(v)
        for neighbor in graph[v]:
            if neighbor not in visited:
                dfs(neighbor, visited, stack)
        stack.append(v)

    def reverse_graph():
        reversed_g = defaultdict(list)
        for v in graph:
            for neighbor in graph[v]:
                reversed_g[neighbor].append(v)
        return reversed_g

    def fill_order():
        visited = set()
        stack = []

        for v in graph:
            if v not in visited:
                dfs(v, visited, stack)

        return stack

    def dfs_scc(v, visited):
        visited.add(v)
        for neighbor in reversed_graph[v]:
            if neighbor not in visited:
                dfs_scc(neighbor, visited)

    stack = fill_order()
    reversed_graph = reverse_graph()
    visited = set()
    scc_count = 0

    while stack:
        v = stack.pop()
        if v not in visited:
            dfs_scc(v, visited)
            scc_count += 1

    return scc_count

