def categorize_student(siblings):
    """
    Categorizes a student based on the number of siblings they have.

    Args:
    siblings (int): Number of siblings the student has.

    Returns:
    str: The category of the student based on the number of siblings.
    """
    if siblings < 0:
        return 'Invalid number of siblings'
    elif siblings == 0:
        return 'Only Child'
    elif siblings == 1:
        return 'One Sib'
    elif siblings == 2:
        return 'Two Sibs'
    else:
        return f'{siblings} Sibs'

