def make_complete_graph(nVertices, directed=False):
    """
    Creates a complete graph.

    Parameters:
    nVertices (int): Number of vertices in the graph.
    directed (bool): Whether the graph is directed or not.

    Returns:
    list: List of edges in the graph.
    """
    if nVertices < 2:
        return []

    edges = []
    for i in range(nVertices):
        for j in range(i + 1, nVertices):
            if directed:
                edges.append((i, j))
                edges.append((j, i))
            else:
                edges.append((i, j))
    return edges

