def fizz_buzz(n):
    """
    Generate the FizzBuzz sequence up to n.

    :param n: The upper limit of the sequence.
    :return: A list of the FizzBuzz sequence up to n.
    """
    # Helper function to apply FizzBuzz rules
    def apply_rules(num):
        if num % 3 == 0 and num % 5 == 0:
            return "fizzbuzz"
        elif num % 3 == 0:
            return "fizz"
        elif num % 5 == 0:
            return "buzz"
        else:
            return str(num)

    # Generate the FizzBuzz sequence using a list comprehension
    return [apply_rules(i) for i in range(1, n + 1)]

