def subarray_sum(array, target_sum):
    """
    Returns the number of subarrays with the given sum.
    """
    count = 0
    current_sum = 0
    prefix_sums = {0: 1}

    for num in array:
        current_sum += num

        if current_sum - target_sum in prefix_sums:
            count += prefix_sums[current_sum - target_sum]

        if current_sum in prefix_sums:
            prefix_sums[current_sum] += 1
        else:
            prefix_sums[current_sum] = 1

    return count

