import string


def count_letters_in_word(word):
    """
    Returns a dictionary with the count of each distinct letter in the word.
    The function is case insensitive and ignores spaces and punctuation.
    """
    word = word.lower()
    letter_counts = {}
    for letter in word:
        if letter in string.ascii_lowercase:  # Check if the character is a letter
            if letter in letter_counts:
                letter_counts[letter] += 1
            else:
                letter_counts[letter] = 1
    return letter_counts

