def classify_characters(s):
    """
    Classifies the characters in the given string into four categories:
    digits, uppercase letters, lowercase letters, and special characters.

    Parameters:
        s (str): The input string.

    Returns:
        dict: A dictionary containing four keys 'digits', 'uppercase', 'lowercase', and 'special'
              with lists of corresponding characters.
    """
    classified = {
        'digits': [],
        'uppercase': [],
        'lowercase': [],
        'special': []
    }

    for char in s:
        if char.isdigit():
            classified['digits'].append(char)
        elif char.isupper():
            classified['uppercase'].append(char)
        elif char.islower():
            classified['lowercase'].append(char)
        else:
            classified['special'].append(char)

    return classified

