def trivia_game_framework(category, difficulty):
    """
    Function to return a trivia question based on category and difficulty.
    """
    questions = {
        "Science": {
            "easy": "What planet is known as the Red Planet?",
            "medium": "What is the chemical symbol for the element Oxygen?",
            "hard": "What is the most abundant gas in Earth's atmosphere?"
        },
        "History": {
            "easy": "Who was the first President of the United States?",
            "medium": "In what year did the Titanic sink?",
            "hard": "Who was the leader of the Soviet Union during WWII?"
        }
    }

    answers = {
        "Science": {
            "easy": "Mars",
            "medium": "O",
            "hard": "Nitrogen"
        },
        "History": {
            "easy": "George Washington",
            "medium": "1912",
            "hard": "Joseph Stalin"
        }
    }

    question = questions[category][difficulty]
    answer = answers[category][difficulty]

    return question, answer

