def palindromic_substrings(s):
    """
    Returns all palindromic substrings in the input string.
    """
    def is_palindrome(sub):
        return sub == sub[::-1]

    result = []
    n = len(s)

    for i in range(n):
        for j in range(i + 1, n + 1):
            substr = s[i:j]
            if is_palindrome(substr):
                result.append(substr)

    return result

