def valid_parentheses(s):
    """
    Function to check if a string of parentheses is valid.
    A string is valid if all open brackets are closed by the same type of brackets in the correct order.
    """
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}
    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if stack == [] or mapping[char] != stack.pop():
                return False
    return stack == []

def move_robot(position, direction):
    """
    Moves the robot from the current position in the specified direction.

    Parameters:
        position (tuple): A tuple (x, y) representing the current position of the robot.
        direction (str): A string representing the direction to move in, 
                         it can be 'up', 'down', 'left', or 'right'.

    Returns:
        tuple: A new position (x, y) after the move.
    """
    x, y = position

    if direction == "up":
        y += 1
    elif direction == "down":
        y -= 1
    elif direction == "left":
        x -= 1
    elif direction == "right":
        x += 1
    else:
        raise ValueError("Invalid direction. Choose from 'up', 'down', 'left', or 'right'.")

    return (x, y)

