def moveZeroes(nums):
    """
    This function moves all the zeros in the list 'nums' to the end, 
    while maintaining the relative order of the non-zero elements with O(1) space complexity.
    """
    insert_pos = 0

    for num in nums:
        if num != 0:
            nums[insert_pos] = num
            insert_pos += 1

    for i in range(insert_pos, len(nums)):
        nums[i] = 0

    return nums

