def is_prime(num, divisor=None):
    """
    Recursively checks if a number is prime.

    Args:
    num (int): The number to check.
    divisor (int, optional): The divisor to check divisibility.

    Returns:
    bool: True if the num is prime, False otherwise.
    """
    if num <= 1:
        return False
    if divisor is None:
        divisor = num - 1
    if divisor == 1:
        return True
    if num % divisor == 0:
        return False
    return is_prime(num, divisor - 1)

