def rotations(s):
    """
    Given a string s, return a list of strings, each of which is a rotation of the original string.
    """
    if len(s) == 0:
        return []
    if len(s) == 1:
        return [s]

    # Include the original string and generate all rotations
    return [s[i:] + s[:i] for i in range(len(s))]

