def calculate_overlap(a, b):
    """
    Calculates the overlap between vectors a and b.
    The overlap is defined as the number of matching elements divided by the length of the shorter vector.
    """
    if not a or not b:
        return 0.0

    b_set = set(b)
    matches = sum(1 for element in a if element in b_set)

    return matches / min(len(a), len(b))

