def char_frequency_map(s: str) -> dict:
    """
    Generates a dictionary with unique characters of the string as keys
    and their frequency as values, ignoring spaces and case sensitivity.

    Parameters:
    s (str): The input string.

    Returns:
    dict: A dictionary containing character frequencies.
    """
    frequency = {}
    for char in s.lower():
        if char != ' ':
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1
    return frequency

