def process_integer(input_value):
    """
    Returns the square of the input_value if it is an odd integer.
    If the input_value is not an odd integer, returns an appropriate error message.
    """
    try:
        value = int(input_value)
        if value % 2 == 0:
            return "The integer is not odd."
        return value ** 2
    except ValueError:
        return "The input is not an integer."

