def set_operation(set1, set2, operation_type=None):
    """
    Performs a set operation on two sets based on the operation type.

    Parameters:
    set1 (set): The first set.
    set2 (set): The second set.
    operation_type (str): The type of operation to perform ('and' for intersection, 'or' for union).

    Returns:
    set: The result of the set operation.

    Raises:
    ValueError: If operation_type is not provided or is invalid.
    """
    if operation_type == "and":
        return set1.intersection(set2)
    elif operation_type == "or":
        return set1.union(set2)
    else:
        raise ValueError("Invalid operation type. Must be 'and' or 'or'.")

