def lowercase_strings(array):
    """
    Transforms each distinct string in the array into its lowercase counterpart.
    Returns an error message if the array includes any non-string types.
    """
    try:
        # Check that all elements in array are strings
        if not all(isinstance(item, str) for item in array):
            raise ValueError("All elements in the array must be strings.")

        # Convert each string in the array to lowercase
        return [item.lower() for item in array]
    except Exception as e:
        return str(e)

