def remove_consecutive_repeats(s):
    """
    Removes consecutive repeating characters in a given string, while keeping the first character of each sequence of 
    repeating characters intact.
    """
    if not s:
        return s

    result = [s[0]]

    for char in s[1:]:
        if char != result[-1]:
            result.append(char)

    return ''.join(result)

