def words_frequency(words_list):
    """
    Converts a list of strings into a dictionary with each unique word as a key
    and its value as the number of times it appears in the strings (case insensitive).

    :param words_list: List of strings.
    :return: Dictionary with word frequencies.
    """
    frequency = {}
    for phrase in words_list:
        words = phrase.lower().split()
        for word in words:
            frequency[word] = frequency.get(word, 0) + 1
    return frequency

