def find_element_in_nested_array(nested_array, element):
    """
    Searches for an element in a nested array. If found, returns a tuple with the index position
    in the outer and inner array. If not found, returns a message stating the element is not present.

    :param nested_array: List of lists (nested array)
    :param element: Element to search for
    :return: Tuple of indices (outer, inner) or a string message
    """
    for outer_index, inner_list in enumerate(nested_array):
        if element in inner_list:
            inner_index = inner_list.index(element)
            return (outer_index, inner_index)
    return "Element is not present"

