import re


def is_strong_password(password):
    """
    Checks if the password is strong. A strong password contains at least 12 characters,
    one uppercase letter, one lowercase letter, and one digit.
    """
    if len(password) < 12:
        return False
    if not re.search(r'[A-Z]', password):
        return False
    if not re.search(r'[a-z]', password):
        return False
    if not re.search(r'\d', password):
        return False
    return True

