def count_duplicates(input_list):
    """
    Identify duplicate elements in a list and count the number of occurrences for each duplicate element.
    The function returns a dictionary with elements as keys and their counts as values.
    Time complexity: O(n), where n is the size of the input list.
    """
    element_count = {}
    for element in input_list:
        if element in element_count:
            element_count[element] += 1
        else:
            element_count[element] = 1

    duplicates_count = {}
    for element, count in element_count.items():
        if count > 1:
            duplicates_count[element] = count

    return duplicates_count

