def top_3_most_common(numbers):
    """
    Returns the top 3 most common numbers along with their frequencies.

    :param numbers: List of integers within the range of 0 to 100
    :return: List of tuples where each tuple contains a number and its frequency
    """
    frequency_dict = {}
    for number in numbers:
        if number in frequency_dict:
            frequency_dict[number] += 1
        else:
            frequency_dict[number] = 1

    sorted_by_frequency = sorted(frequency_dict.items(), key=lambda x: (-x[1], numbers.index(x[0])))

    return sorted_by_frequency[:3]

