def form_word_chain(words):
    """
    Forms a chain using the given list of words where the next word should 
    start with the last character of the previous word.
    If the chain is broken at any point, returns 'No valid chain found'.
    """
    if not words:
        return "No valid chain found"

    for i in range(len(words) - 1):
        if words[i][-1] != words[i + 1][0]:
            return "No valid chain found"

    return " -> ".join(words)

