def sum_nested_dict(d):
    """
    Calculate the sum of all numerical values in a nested dictionary.

    :param d: Dictionary which may contain nested dictionaries
    :return: Sum of all numerical values
    """
    total_sum = 0

    for value in d.values():
        if isinstance(value, dict):
            total_sum += sum_nested_dict(value)
        elif isinstance(value, (int, float)):
            total_sum += value

    return total_sum

