def max_product_of_three(nums):
    """
    Returns the maximum product of three numbers in the list.
    If the list has less than three elements, return None.
    """
    if len(nums) < 3:
        return None

    nums.sort()

    return max(nums[0] * nums[1] * nums[-1], nums[-1] * nums[-2] * nums[-3])

