def analyze_string(s):
    """
    Analyzes the string s to determine the count of alphabetical characters,
    numerical digits, and special characters. Also, returns the frequency of 
    uppercase and lowercase letters.

    Parameters:
    s (str): The input string to analyze.

    Returns:
    dict: A dictionary with counts of 'alphabets', 'digits', 'special_characters', 
          'uppercase', and 'lowercase'.
    """
    counts = {
        'alphabets': 0,
        'digits': 0,
        'special_characters': 0,
        'uppercase': 0,
        'lowercase': 0
    }

    for char in s:
        if char.isalpha():
            counts['alphabets'] += 1
            if char.isupper():
                counts['uppercase'] += 1
            else:
                counts['lowercase'] += 1
        elif char.isdigit():
            counts['digits'] += 1
        else:
            counts['special_characters'] += 1

    return counts

