def categorize_even_odd(numbers):
    """
    Categorizes numbers into even and odd.

    Args:
    numbers (list): A list of integers.

    Returns:
    dict: A dictionary with keys as True (even) and False (odd) and their respective category lists as values.
    """
    result = {True: [], False: []}
    for number in numbers:
        if number % 2 == 0:
            result[True].append(number)
        else:
            result[False].append(number)
    return result

