def merge_dictionaries(*dicts):
    """
    Merges multiple dictionaries into one. In case of key conflicts, later dictionaries' values overwrite earlier ones'.

    Parameters:
    *dicts (Dict): A variable number of dictionaries to merge

    Returns:
    dict: A single merged dictionary
    """
    merged_dict = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("All arguments must be dictionaries")
        for key, value in d.items():
            if key in merged_dict and type(merged_dict[key]) is not type(value):
                raise TypeError(f"Type mismatch for key '{key}': {type(merged_dict[key]).__name__} vs {type(value).__name__}")
            merged_dict[key] = value
    return merged_dict

