def calc_factorial(n):
    """
    Returns the factorial of n using recursion.
    """
    assert isinstance(n, int) and n >= 0, "Input must be a non-negative integer."

    if n == 0 or n == 1:
        return 1
    else:
        return n * calc_factorial(n - 1)

