def remove_duplicates(input_list):
    """
    Removes duplicate elements from the input list while maintaining the order of elements in the original list.
    This function handles elements of any data type, including nested lists, dictionaries, and sets.
    """
    seen = set()
    result = []

    def to_hashable(item):
        """
        Converts unhashable types into hashable ones. Specifically, it converts lists and sets to tuples.
        """
        if isinstance(item, list):
            return tuple(to_hashable(x) for x in item)
        if isinstance(item, set):
            return frozenset(to_hashable(x) for x in item)
        if isinstance(item, dict):
            return tuple(sorted((k, to_hashable(v)) for k, v in item.items()))
        return item

    for item in input_list:
        hashable_item = to_hashable(item)
        if hashable_item not in seen:
            seen.add(hashable_item)
            result.append(item)

    return result

