def longest_common_subsequence(seq1, seq2):
    """
    Returns the longest common subsequence of two sequences.
    """
    def lcs_helper(seq1, seq2, m, n, memo):
        if m == 0 or n == 0:
            return 0
        if (m, n) in memo:
            return memo[(m, n)]

        if seq1[m-1] == seq2[n-1]:
            memo[(m, n)] = 1 + lcs_helper(seq1, seq2, m-1, n-1, memo)
        else:
            memo[(m, n)] = max(lcs_helper(seq1, seq2, m, n-1, memo), 
                               lcs_helper(seq1, seq2, m-1, n, memo))

        return memo[(m, n)]

    memo = {}
    return lcs_helper(seq1, seq2, len(seq1), len(seq2), memo)

