def array_intersection_with_count(arr1, arr2):
    """
    Returns the intersection of two arrays along with the occurrence count of each common element.

    Args:
    arr1: List of elements (First Array)
    arr2: List of elements (Second Array)

    Returns:
    A dictionary with the common elements as keys and their occurrence counts as values.
    """
    intersection_count = {}

    for element in arr1:
        if element in arr2:
            if element in intersection_count:
                intersection_count[element] += 1
            else:
                intersection_count[element] = 1

    return intersection_count

