def min_edits_to_monotonic(matrix):
    """
    Returns the minimum number of edits required to make each row and column
    monotonically increasing.
    """
    def min_edits_to_increase_list(arr):
        n = len(arr)
        dp = [1] * n

        for i in range(1, n):
            for j in range(i):
                if arr[i] >= arr[j]:
                    dp[i] = max(dp[i], dp[j] + 1)

        return n - max(dp)

    row_edits = 0
    for row in matrix:
        row_edits += min_edits_to_increase_list(row)

    col_edits = 0
    for col in zip(*matrix):
        col_edits += min_edits_to_increase_list(col)

    return row_edits + col_edits

