def extract_values(key, json, path=None):
    """
    Recursively search for values of a given key in a nested JSON document.
    """
    if path is None:
        path = []

    results = []

    def search(k, v, current_path):
        if isinstance(v, dict):
            for sub_k, sub_v in v.items():
                search(sub_k, sub_v, current_path + [sub_k])
        elif isinstance(v, list):
            for i, item in enumerate(v):
                search(k, item, current_path + [i])
        elif k == key:
            results.append((v, current_path))
        return

    search(None, json, path)

    return results

