def get_permutations(s):
    """
    Returns a list of all permutations of the string s.
    """
    if len(s) == 0:
        return ['']
    permutations = []
    for i, char in enumerate(s):
        for perm in get_permutations(s[:i] + s[i+1:]):
            permutations.append(char + perm)
    return permutations

