def count_occurrences(arr, x):
    """
    Returns the number of occurrences of x in the sorted array arr.
    """
    def binary_search_left(arr, x):
        left, right = 0, len(arr)
        while left < right:
            mid = (left + right) // 2
            if arr[mid] < x:
                left = mid + 1
            else:
                right = mid
        return left

    def binary_search_right(arr, x):
        left, right = 0, len(arr)
        while left < right:
            mid = (left + right) // 2
            if arr[mid] <= x:
                left = mid + 1
            else:
                right = mid
        return left

    left_index = binary_search_left(arr, x)
    right_index = binary_search_right(arr, x)

    return right_index - left_index

