def sum_numerics(lst):
    """
    Returns the sum of all numeric types in a list, ignoring non-numeric types.
    Handles TypeError for non-numeric types gracefully.
    """
    total = 0
    for item in lst:
        try:
            total += item
        except TypeError:
            continue
    return total

