def find_unique_substrings(S):
    """
    Returns all unique substrings of string S in lexicographical order along with their first occurrence index
    and frequency count.

    Parameters:
    S (str): The input string.

    Returns:
    dict: A dictionary where keys are substrings and values are lists containing the start index of the first occurrence
          of the substring and its frequency [first_index, frequency].
    """
    substrings = {}

    for i in range(len(S)):
        for j in range(i + 1, len(S) + 1):
            substring = S[i:j]
            if substring not in substrings:
                substrings[substring] = [i, 1]
            else:
                substrings[substring][1] += 1

    sorted_substrings = dict(sorted(substrings.items()))

    return sorted_substrings

