def max_and_avg_string_lengths(strings):
    """
    Given a list of strings, prints the maximum and average lengths of the strings in the list.
    """
    if not strings:  # handle the case when the list is empty
        return (0, 0.0)

    lengths = [len(s) for s in strings]
    max_length = max(lengths)
    avg_length = sum(lengths) / len(strings)
    return (max_length, avg_length)

