def identify_sorting_technique(arr):
    """
    Identifies the sorting technique used on a list, if possible.
    This is a conceptual function as identifying the exact sorting algorithm used
    on an already sorted list is not typically feasible without additional metadata.
    Here we will just check if it's sorted in ascending or descending order.
    """
    if arr == sorted(arr):
        return "ascending"
    elif arr == sorted(arr, reverse=True):
        return "descending"
    else:
        return "unsorted"

