def char_frequency(s):
    """
    Returns a dictionary with the frequency of each character in the string.
    Ignores spaces and punctuation. Case sensitive.
    """
    freq = {}
    for char in s:
        if char.isalnum():  # Consider only alphanumeric characters
            if char in freq:
                freq[char] += 1
            else:
                freq[char] = 1
    return freq

