def max_repeated_char_frequency(s):
    """
    Given a string of characters, return the maximum repeated character frequency 
    in the sequence.

    Parameters:
    s (str): The input string

    Returns:
    int: The maximum frequency of any repeated character in the string
    """
    if not s:
        return 0

    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    max_frequency = max(char_count.values())

    return max_frequency

