def find_max_and_index(nums):
    """
    Returns the maximum number and its index in the list of integers.
    If the list is empty, returns (None, None).

    Parameters:
        nums (list of int): The list of integers to search.

    Returns:
        tuple: A tuple containing the maximum number and its index.
    """
    if not nums:
        return (None, None)

    max_num = nums[0]
    max_index = 0

    for index, num in enumerate(nums):
        if num > max_num:
            max_num = num
            max_index = index

    return (max_num, max_index)

