def count_emojis(text: str) -> tuple:
    """
    Counts the number of 😊, 👍, and 👎 emojis in the given text.

    Args:
    text (str): The text to search for emojis.

    Returns:
    tuple: A tuple containing the count of each emoji in the order of 😊, 👍, and 👎.
    """
    count_emojis_dict = {}
    emojis = ['😊', '👍', '👎']

    for emoji in emojis:
        count_emojis_dict[emoji] = text.count(emoji)

    return tuple(count_emojis_dict[emoji] for emoji in emojis)

