def index_of_largest(numbers):
    """
    Returns the index of the largest number in the list.
    If the list is empty, returns None.
    """
    if not numbers:
        return None

    largest_idx = 0
    for i in range(1, len(numbers)):
        if numbers[i] > numbers[largest_idx]:
            largest_idx = i

    return largest_idx

