def string_to_char_count_list(strings):
    """
    Takes a list of strings and returns a list of lists, where each sublist contains the 
    original string and a dictionary mapping each unique character in the string to 
    the number of times it appears in the string.

    Parameters:
    strings (list of str): List of strings to process.

    Returns:
    list of lists: Each sublist contains a string and its corresponding character count dictionary.
    """
    result = []
    for s in strings:
        char_count = {}
        for char in s:
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1
        result.append([s, char_count])
    return result

