def convert_to_dict(lst):
    """
    Converts a list of tuples into a dictionary, where each tuple consists of a key and a list of values. 
    If a key appears more than once, the values are appended to the list of the existing key.

    Parameters:
    lst (list): A list of tuples

    Returns:
    dict: A dictionary where each key has a list of values.
    """
    result_dict = {}
    for item in lst:
        if len(item) >= 2:
            key = item[0]
            values = list(item[1:])
            if key in result_dict:
                result_dict[key].extend(values)
            else:
                result_dict[key] = values
    return result_dict

