def calculate(operation, numbers):
    """
    Performs the given arithmetic operation on the provided list of two integers.

    :param operation: A string representing the arithmetic operation ('+', '-', '*', '/')
    :param numbers: A list of two integers
    :return: Result of the operation or None in case of division by zero
    """
    if operation == '+':
        return numbers[0] + numbers[1]
    elif operation == '-':
        return numbers[0] - numbers[1]
    elif operation == '*':
        return numbers[0] * numbers[1]
    elif operation == '/':
        if numbers[1] == 0:
            return None
        return numbers[0] / numbers[1]
    else:
        raise ValueError("Invalid operation. Supported operations are: '+', '-', '*', '/'")

