def increment_values(d):
    """
    Takes a dictionary and returns a new dictionary with all numerical values incremented by 10.
    Handles nested dictionaries and only increments number values.

    Parameters:
        d (dict): Input dictionary

    Returns:
        dict: New dictionary with values incremented by 10
    """
    new_dict = {}
    for key, value in d.items():
        if isinstance(value, dict):
            new_dict[key] = increment_values(value)
        elif isinstance(value, (int, float)):
            new_dict[key] = value + 10
        else:
            new_dict[key] = value
    return new_dict

