def respond_to_query(query):
    """
    Responds to a simple user query using predefined rules.

    Parameters:
    query (str): The user query as a string.

    Returns:
    str: The response to the query.
    """
    query = query.lower()
    if "hello" in query:
        return "Hello! How can I assist you today?"
    elif "how are you" in query:
        return "I'm just a computer program, but I'm here to help you!"
    elif "weather" in query:
        return "I'm not sure about the weather, but you can check your local weather service."
    elif "name" in query:
        return "I'm your friendly assistant. What can I do for you?"
    elif "bye" in query:
        return "Goodbye! Have a great day!"
    else:
        return "I'm sorry, I don't understand that question. Can you please rephrase?"

