def extract_uppercase_substrings(s):
    """
    Extracts and returns all uppercase substrings from the given string.
    """
    substrings = []
    current_substring = ""

    for char in s:
        if char.isupper():
            current_substring += char
        else:
            if current_substring:
                substrings.append(current_substring)
                current_substring = ""

    if current_substring:
        substrings.append(current_substring)

    return substrings

