def group_consecutive_integers(lst):
    """
    Given a list of integers, returns a list of strings where each string is a
    group of consecutive integers from the original list that have the same parity.
    """
    result = []
    current_group = []
    for num in lst:
        if not current_group or num % 2 == current_group[0] % 2:
            current_group.append(num)
        else:
            result.append(", ".join(map(str, current_group)))
            current_group = [num]
    if current_group:
        result.append(", ".join(map(str, current_group)))
    return result

