def all_unique_characters(s):
    """
    Check if all characters in the string are unique without using additional data structures.

    :param s: string to check
    :return: True if all characters are unique, False otherwise
    """
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n):
            if s[i] == s[j]:
                return False
    return True

