def hex_to_rgb(hex_colors):
    """
    Converts a list of hex color values to a list of RGB tuples.

    Args:
    hex_colors (list): A list of hex color values as strings.

    Returns:
    list: A list of RGB tuples or an error message string for invalid inputs.
    """
    rgb_colors = []

    for hex_value in hex_colors:
        if isinstance(hex_value, str) and len(hex_value) == 7 and hex_value.startswith('#'):
            try:
                rgb_colors.append(tuple(int(hex_value[i:i+2], 16) for i in (1, 3, 5)))
            except ValueError:
                return "Invalid hex color value in the list."
        else:
            return "Invalid hex color value in the list."

    return rgb_colors

