def decimal_to_formatted_binary(n):
    """
    Converts a decimal number to a binary string enclosed in Angle Brackets ('<' and '>')
    and without leading '0's unless the number is exactly 0.
    """
    if n == 0:
        return "<0>"
    else:
        return f"<{bin(n)[2:]}>"

