def find_first_occurrence(lst, element):
    """
    Returns the index of the first occurrence of element in a nested list flattened
    If the element is not found, returns -1.
    """
    def flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    flat_list = list(flatten(lst))
    try:
        return flat_list.index(element)
    except ValueError:
        return -1

