def string_to_char_dict(text):
    """
    Converts a given string into a dictionary where each key is a unique 
    character from the string and the value is the number of occurrences 
    of that character. Ignores case and non-alphabetic characters.
    """
    char_dict = {}
    text = text.lower()

    for char in text:
        if char.isalpha():
            if char in char_dict:
                char_dict[char] += 1
            else:
                char_dict[char] = 1

    return char_dict

