def find_max_value_and_index(numbers):
    """
    Finds the maximum value and its index in a given list of numbers.
    If the list is empty, returns (None, -1).
    If there are multiple occurrences of the maximum value, returns the index of the first occurrence.

    Parameters:
    numbers (list): A list of numbers.

    Returns:
    (max_value, index) (tuple): A tuple containing the maximum value and its index.
    """
    if not numbers:
        return (None, -1)

    max_value = numbers[0]
    max_index = 0

    for i, num in enumerate(numbers):
        if num > max_value:
            max_value = num
            max_index = i

    return (max_value, max_index)

