def fibonacci(n):
    """
    Returns a string containing the first n terms of the Fibonacci sequence, separated by commas.
    """
    if n < 1:
        return ""
    if n == 1:
        return "0"

    fib_sequence = [0, 1]
    for i in range(2, n):
        fib_sequence.append(fib_sequence[-1] + fib_sequence[-2])

    return ', '.join(map(str, fib_sequence))

