def shortest_palindrome(s):
    """
    Returns the shortest palindrome that can be formed by appending characters to the end of the input string.
    """
    def is_palindrome(st):
        return st == st[::-1]

    for i in range(len(s)):
        if is_palindrome(s[i:]):
            return s + s[:i][::-1]
    return ""

