def greet_person(person):
    """
    Generates a greeting message based on the person's name and gender.

    Args:
    person (dict): A dictionary containing 'name' and 'gender'.

    Returns:
    str: A greeting message or 'Invalid input' if the input is not as expected.
    """
    if not isinstance(person, dict):
        return "Invalid input"

    name = person.get('name')
    gender = person.get('gender')

    if not name or not gender:
        return "Invalid input"

    if gender == 'male':
        return f"Hello, Mr. {name}"
    elif gender == 'female':
        return f"Hello, Ms. {name}"
    else:
        return f"Hello, {name}"

