from typing import List, Union


def sort_people(people: List[List[Union[str, int]]], key: str) -> List[List[Union[str, int]]]:
    """
    Sorts a list of people's information based on name, age, or occupation.

    :param people: List of people information. Each inner list contains name, age, and occupation.
    :param key: The key to sort by, can be 'name', 'age', or 'occupation'.
    :returns: Sorted list of people information.
    """

    key_index = {'name': 0, 'age': 1, 'occupation': 2}

    if key not in key_index:
        raise ValueError("Key must be 'name', 'age', or 'occupation'")

    return sorted(people, key=lambda x: x[key_index[key]])

