def fibonacci_up_to_n(n):
    """
    Generates a list containing the Fibonacci sequence up to, but not including, the number n.
    """
    if n <= 0:
        return []

    fibonacci_sequence = [0, 1]
    while True:
        next_val = fibonacci_sequence[-1] + fibonacci_sequence[-2]
        if next_val >= n:
            break
        fibonacci_sequence.append(next_val)

    return fibonacci_sequence

