def add_space_before_uppercase(input_string):
    """
    Takes a string and adds a space before each uppercase letter,
    except if it's the first character of the string.
    """
    if not input_string:
        return input_string

    result = input_string[0]  # Start with the first character as is
    for char in input_string[1:]:
