def find_odd_occurrences(arr):
    """
    Returns a list of elements that appear an odd number of times in the input array.

    :param arr: List[int] - an array of integers
    :return: List[int] - a list of integers that appear an odd number of times
    """
    count_dict = {}
    for num in arr:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    result = [num for num, count in count_dict.items() if count % 2 != 0]
    return result

