def fibonacci(n):
    """
    Returns a list containing the Fibonacci sequence up to n.
    """
    if n < 0:
        return []

    sequence = [0, 1]

    while sequence[-1] + sequence[-2] <= n:
        sequence.append(sequence[-1] + sequence[-2])

    # Remove the first element if n == 0
    if n == 0:
        return [0]

    return sequence

