def nearest_smaller_to_left(arr):
    """
    Returns a list containing the nearest smaller number to the left for each element in the list.
    If there is no smaller number to the left, returns -1 for that position.
    """
    result = []
    stack = []

    for num in arr:
        while stack and stack[-1] >= num:
            stack.pop()
        if stack:
            result.append(stack[-1])
        else:
            result.append(-1)
        stack.append(num)

    return result

