def allocate_tasks_to_workers(tasks, workers):
    """
    Allocate tasks to workers ensuring no worker exceeds their capacity.

    :param tasks: dict, keys are task ids and values are task requirements
    :param workers: dict, keys are worker ids and values are capacities
    :return: dict, keys are worker ids and values are lists of assigned task ids
    """
    allocation = {worker_id: [] for worker_id in workers}
    remaining_capacity = workers.copy()

    for task_id, requirement in tasks.items():
        for worker_id, capacity in remaining_capacity.items():
            if requirement <= capacity:
                allocation[worker_id].append(task_id)
                remaining_capacity[worker_id] -= requirement
                break

    assigned_tasks = sum([len(tasks) for tasks in allocation.values()])
    if assigned_tasks < len(tasks):
        return None  # Not all tasks could be allocated

    return allocation

