    and the total counts of letters and numbers.
    """
    counts = {}
    total_letters = 0
    total_numbers = 0

    for char in input_string:
        if char.isalpha() or char.isdigit():
            counts[char] = counts.get(char, 0) + 1
            if char.isalpha():
                total_letters += 1
            elif char.isdigit():
                total_numbers += 1

    counts['Total Letters'] = total_letters
    counts['Total Numbers'] = total_numbers

    return counts

