def caesar_cipher(text, shift):
    """
    Encrypts the input text using the Caesar cipher technique with the given shift.

    Parameters:
    - text (str): The input text to be encrypted.
    - shift (int): The number of positions to shift each character.

    Returns:
    - str: The encrypted text.
    """
    result = []

    for char in text:
        if char.isalpha():
            shift_amount = shift % 26
            if char.islower():
                start = ord('a')
                result.append(chr(((ord(char) - start + shift_amount) % 26) + start))
            elif char.isupper():
                start = ord('A')
                result.append(chr(((ord(char) - start + shift_amount) % 26) + start))
        else:
            result.append(char)

    return ''.join(result)

import json


def extract_emails(json_data):
    """
    Extract all email addresses from the JSON data.

    Parameters:
        json_data (str): A JSON formatted string.

    Returns:
        list: A list of email addresses found in the JSON data.
    """
    data = json.loads(json_data)
    emails = []

    def find_emails(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if key == 'email':
                    emails.append(value)
                find_emails(value)
        elif isinstance(obj, list):
            for item in obj:
                find_emails(item)

    find_emails(data)
    return emails

