def max_independent_selection(nums):
    """
    Returns the maximum number of elements from the list nums
    that can be selected such that no two selected elements are divisible by each other.
    """
    if not nums:
        return 0

    nums.sort()
    dp = [1] * len(nums)

    for i in range(len(nums)):
        for j in range(i):
            if nums[i] % nums[j] != 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

