def generate_balance_report(journal):
    """
    Generates a balance report from a journal.

    Args:
    journal (list of tuples): Each tuple contains an account name (str),
                              transaction type (str, either 'debit' or 'credit'),
                              and an amount (float).

    Returns:
    dict: A dictionary with account names as keys and their final balances as values.
    """
    balance_sheet = {}

    for account, trans_type, amount in journal:
        if account not in balance_sheet:
            balance_sheet[account] = 0
        if trans_type == 'debit':
            balance_sheet[account] += amount
        elif trans_type == 'credit':
            balance_sheet[account] -= amount

    return dict(sorted(balance_sheet.items()))

