def chatbot_response(message):
    """
    Simulates a simple chatbot that responds to greetings and farewells.
    """
    greetings = ["hello", "hi"]
    farewells = ["goodbye", "bye", "see you"]

    message_cleaned = message.lower().strip()

    if message_cleaned in greetings:
        return "Hello! How can I help you today?"
    elif message_cleaned in farewells:
        return "Goodbye! Have a great day!"
    else:
        return "I'm sorry, I can only respond to basic greetings and farewells."

