def count_characters(strings):
    """
    Takes a list of strings and returns a dictionary with the count of each string's characters.
    Each key in the dictionary is a string from the input list,
    and its value is another dictionary with character counts.
    """
    result = {}
    for string in strings:
        char_count = {}
        for char in string:
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1
        result[string] = char_count
    return result

