def cumulative_product(numbers):
    """
    Returns a new list where each element is the cumulative product of the elements up to that point in the given list.
    """
    if not numbers:
        return []
    cum_prod = [numbers[0]]
    for num in numbers[1:]:
        cum_prod.append(cum_prod[-1] * num)
    return cum_prod

