def bottles_of_beer(x):
    """
    Returns the "99 Bottles of Beer" song verses starting from `x` bottles down to 1.
    If `x` is not a positive integer, it returns an appropriate message.
    """
    if not isinstance(x, int) or x <= 0:
        return "Input must be a positive integer."

    verses = []
    for i in range(x, 0, -1):
        if i == 1:
            verses.append(f"{i} bottle of beer on the wall, {i} bottle of beer.")
            verses.append("Take one down and pass it around, no more bottles of beer on the wall.")
        elif i == 2:
            verses.append(f"{i} bottles of beer on the wall, {i} bottles of beer.")
            verses.append("Take one down and pass it around, 1 bottle of beer on the wall.")
        else:
            verses.append(f"{i} bottles of beer on the wall, {i} bottles of beer.")
            verses.append(f"Take one down and pass it around, {i-1} bottles of beer on the wall.")

    return "\n".join(verses)

