def count_occurrences(lst, num):
    """
    Returns the number of times num appears in the list lst.
    """
    count_dict = {}
    for item in lst:
        if item in count_dict:
            count_dict[item] += 1
        else:
            count_dict[item] = 1
    return count_dict.get(num, 0)

