def fizzbuzz(n):
    """
    This function prints numbers from 1 to n, replacing multiples of 3 with "Fizz", multiples of 5 with "Buzz", 
    and multiples of both 3 and 5 with "FizzBuzz".

    Args:
        n: An integer representing the upper limit of the range.

    Returns:
        A list containing strings and numbers representing the FizzBuzz sequence.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(i)
    return result

