def convert_list_of_lists_to_dict(list_of_lists):
    """
    Converts a list of lists into a dictionary where the first element 
    of each sublist is the key and the second element is the value.
    If a key is repeated, the values are stored in a list.

    Args:
        list_of_lists (list): List of lists, where each sublist contains two elements.

    Returns:
        dict: Dictionary with the first elements of sublists as keys and the second 
              elements as values. If a key repeats, the values are stored in a list.
    """
    new_dict = {}
    for inner_list in list_of_lists:
        key, value = inner_list[0], inner_list[1]
        if key in new_dict:
            if isinstance(new_dict[key], list):
                new_dict[key].append(value)
            else:
                new_dict[key] = [new_dict[key], value]
        else:
            new_dict[key] = value
    return new_dict

