def find_min_index(data):
    """
    Finds the index of the smallest element in the list.
    Returns -1 for empty lists.
    """
    if not data:
        return -1

    min_index = 0
    for i in range(1, len(data)):
        if data[i] < data[min_index]:
            min_index = i
    return min_index

