def frequency_array(A):
    """
    Given an array A, return a new array B such that B[i] is the frequency of A[i] in A.
    """
    # Calculate frequencies of each element in A
    freq = {}
    for num in A:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Create the result array B using the frequencies in freq
    B = [freq[num] for num in A]

    return B

def find_first_and_last_occurrence(lst, element):
    """
    Returns the first and last occurrence indices of the specified element in the list.
    If the element is not found, it returns (-1, -1).

    :param lst: A list of elements
    :param element: The element to find the first and last occurrence of
    :return: A tuple containing the first and last occurrence indices of the element
    """
    try:
        first_occurrence = lst.index(element)
        last_occurrence = len(lst) - 1 - lst[::-1].index(element)
        return (first_occurrence, last_occurrence)
    except ValueError:
        return (-1, -1)

