def find_max_consecutive_ones(nums):
    """
    Finds the maximum number of consecutive 1's in a binary array.

    :param nums: List[int] - The binary array.
    :return: int - The maximum number of consecutive 1's.
    """
    max_count = 0
    current_count = 0

    for num in nums:
        if num == 1:
            current_count += 1
        else:
            max_count = max(max_count, current_count)
            current_count = 0

    return max(max_count, current_count)

