def solve_linear_equation(a, b):
  """Solves a simple linear equation of the form ax + b = 0.

  Args:
    a: The coefficient of x.
    b: The constant term.

  Returns:
    The solution for x, or a string indicating infinite solutions if both coefficients are zero or None if there is no solution.
  """
  if a == 0:
    if b == 0:
      return "Infinite solutions"
    else:
      return None  
  else:
    return -b / a

