def get_user_data(include=None, exclude=None):
    """
    Returns user data with options to include or exclude certain properties.

    Parameters:
        include (list): List of properties to include in the returned object. Takes precedence over exclude.
        exclude (list): List of properties to exclude from the returned object.

    Returns:
        dict: A dictionary containing the user data with specified inclusions/exclusions.
    """
    user_data = {
        'name': 'John',
        'age': 30,
        'email': 'john@example.com',
        'phone': '123-456-7890',
        'address': '123 Main St'
    }

    if include is not None:
        return {key: user_data[key] for key in include if key in user_data}

    if exclude is not None:
        return {key: user_data[key] for key in user_data if key not in exclude}

    return user_data

