def diff_vowels_consonants(string_list):
    """
    Returns the difference between the total number of vowels and consonants across all strings in the list.

    :param string_list: List of strings 
    :return: Difference between the total number of vowels and consonants across all strings
    """
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    vowel_count = 0
    consonant_count = 0

    for string in string_list:
        for char in string:
            if char in vowels:
                vowel_count += 1
            else:
                consonant_count += 1

    return vowel_count - consonant_count

