def compress_string(data):
    """
    Compress a string using run-length encoding.
    """
    if not data:
        return ""

    compressed = []
    count = 1
    previous_char = data[0]

    for i in range(1, len(data)):
        if data[i] == previous_char:
            count += 1
        else:
            compressed.append(f"{previous_char}{count}")
            previous_char = data[i]
            count = 1

    # Append the last accumulated character and its count
    compressed.append(f"{previous_char}{count}")

    return ''.join(compressed)

