def simulate_bird_movement(initial_x, initial_y, directions):
    """
    Simulates bird movement on a grid based on a list of directions.

    :param initial_x: int, initial x-coordinate (east-west direction)
    :param initial_y: int, initial y-coordinate (north-south direction)
    :param directions: list of str, list of directions ("N", "S", "E", "W")
    :return: tuple of int, final (x, y) position of the bird
    """
    x, y = initial_x, initial_y
    for direction in directions:
        if direction == "N":
            y += 1
        elif direction == "S":
            y -= 1
        elif direction == "E":
            x += 1
        elif direction == "W":
            x -= 1
    return x, y

