def top_students_by_course(students):
    """
    Analyzes student performance across multiple courses and returns a dictionary
    mapping each course name to the name of the student(s) with the highest score in that course.

    :param students: List of dictionaries, each containing student's name and scores in different courses
    :type students: list
    :return: Dictionary mapping course names to student(s) with highest score in that course
    :rtype: dict
    """
    course_toppers = {}

    for student in students:
        name = student['name']
        scores = student['scores']

        for course, score in scores.items():
            if course not in course_toppers:
                course_toppers[course] = (score, [name])
            else:
                current_top_score, current_top_students = course_toppers[course]
                if score > current_top_score:
                    course_toppers[course] = (score, [name])
                elif score == current_top_score:
                    current_top_students.append(name)

    # Formatting the output dictionary as required
    result = {course: names for course, (score, names) in course_toppers.items()}

    return result

