def fizz_buzz_customized(numbers, fizz_num, buzz_num):
    """
    This function takes a list of numbers and two divisors (fizz_num and buzz_num).
    It returns a list where each element corresponds to:
    - "FizzBuzz" if the number is divisible by both fizz_num and buzz_num,
    - "Fizz" if the number is divisible by fizz_num,
    - "Buzz" if the number is divisible by buzz_num,
    - the number itself if none of these conditions are met.
    """
    result = []
    for number in numbers:
        if number % fizz_num == 0 and number % buzz_num == 0:
            result.append("FizzBuzz")
        elif number % fizz_num == 0:
            result.append("Fizz")
        elif number % buzz_num == 0:
            result.append("Buzz")
        else:
            result.append(number)
    return result

