def categorize_integers(int_list):
    """
    Categorizes a list of integers into three lists based on their divisibility by 2, 3, or neither.

    Parameters:
    int_list (list): A list of integers to be categorized.

    Returns:
    dict: A dictionary with keys 'Divisible by 2', 'Divisible by 3', and 'Neither'.
    """
    divisible_by_2 = []
    divisible_by_3 = []
    neither = []

    for number in int_list:
        if number % 2 == 0:
            divisible_by_2.append(number)
        elif number % 3 == 0:
            divisible_by_3.append(number)
        else:
            neither.append(number)

    return {
        'Divisible by 2': divisible_by_2,
        'Divisible by 3': divisible_by_3,
        'Neither': neither
    }

