def computeTF(documents: list) -> list:
    """
    Compute the term frequency for each document in the given list of documents.

    Parameters:
    documents (list): A list of strings, where each string represents a document.

    Returns:
    list: A list of dictionaries, where each dictionary contains the term frequencies for a document.
    """
    tf_list = []

    for doc in documents:
        words = doc.split()
        term_freq_dict = {}

        for word in words:
            if word in term_freq_dict:
                term_freq_dict[word] += 1
            else:
                term_freq_dict[word] = 1

        tf_list.append(term_freq_dict)

    return tf_list

def find_redundant_directed_edge(edges):
    """
    Finds the redundant edge in a directed graph that can be removed
    so that the graph remains a Directed Acyclic Graph (DAG).
    If multiple redundant edges exist, returns the edge that occurs
    last in the list.
    """
    parent = {}
    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_u] = root_v

    cycle_edge = (-1, -1)
    for u, v in edges:
        parent[u] = u
        parent[v] = v

    for u, v in edges:
        if find(u) == find(v):
            cycle_edge = (u, v)
        else:
            union(u, v)

    return cycle_edge

