def normalize_vector(x, y):
    """
    Normalizes a 2D vector (x, y) to have a magnitude of 1 while maintaining its direction.

    Parameters:
    x (float): The x-component of the vector.
    y (float): The y-component of the vector.

    Returns:
    tuple: A tuple (nx, ny) representing the normalized vector components.
    """
    magnitude = (x**2 + y**2) ** 0.5
    if magnitude == 0:
        return (0, 0)
    return (x / magnitude, y / magnitude)

