def verify_relationship(tree_data: list, parent: int, child: int) -> bool:
    """
    Verify if one node is a child of another in a given tree.

    :param tree_data: list of tuples (parent, child) representing the tree's structure
    :param parent: an integer representing the parent node
    :param child: an integer representing the child node
    :return: boolean indicating whether the child is under the given parent
    """
    if parent == child:
        return False

    # Build a dictionary where each key is a parent and value is the list of children
    tree = {}
    for p, c in tree_data:
        if p in tree:
            tree[p].append(c)
        else:
            tree[p] = [c]

    # Helper function to perform DFS search
    def is_child(current_node, target):
        if current_node not in tree:
            return False
        if target in tree[current_node]:
            return True
        for child in tree[current_node]:
            if is_child(child, target):
                return True
        return False

    return is_child(parent, child)

