from typing import List, Dict


def count_tlds(domains: List[str]) -> Dict[str, int]:
    """
    Categorizes domain names by their TLDs and returns a dictionary
    where the keys are the TLDs and the values are the counts of domain names for each TLD.
    """
    tld_counts = {}
    for domain in domains:
        tld = domain.split('.')[-1]
        if tld in tld_counts:
            tld_counts[tld] += 1
        else:
            tld_counts[tld] = 1
    return tld_counts

