def find_anagram_pairs(strings):
    """
    Given a list of strings, find all pairs of strings that are anagrams of each other.

    Args:
    strings (list of str): A list containing n strings.

    Returns:
    list of tuples: A list containing tuples, where each tuple has two strings that are anagrams of each other.
    """
    # Helper function to check if two strings are anagrams
    def are_anagrams(s1, s2):
        return sorted(s1) == sorted(s2)

    anagram_pairs = []
    length = len(strings)

    for i in range(length):
        for j in range(i + 1, length):
            if are_anagrams(strings[i], strings[j]):
                anagram_pairs.append((strings[i], strings[j]))

    return anagram_pairs

