def longest_subsequence_by_sum(arr, target_sum):
    """
    Finds the longest subsequence within the array `arr` such that
    the sum of its elements is less than or equal to `target_sum`.

    Args:
    arr (list[int]): The input array.
    target_sum (int): The target sum.

    Returns:
    tuple: A tuple containing the length of the longest subsequence and the subsequence itself.
    """
    n = len(arr)
    if n == 0:
        return (0, [])

    max_length = 0
    longest_subseq = []

    for i in range(n):
        current_sum = 0
        current_subseq = []

        for j in range(i, n):
            if current_sum + arr[j] <= target_sum:
                current_sum += arr[j]
                current_subseq.append(arr[j])

                if len(current_subseq) > max_length:
                    max_length = len(current_subseq)
                    longest_subseq = current_subseq.copy()
            else:
                break

    return (max_length, longest_subseq)

from typing import List


def smooth_sequence(arr: List[int]) -> List[float]:
    """
    Computes the moving average of the input list of integers.
    """
    if len(arr) == 1:
        return [float(arr[0])]

    result = []
    for i in range(len(arr)):
        if i == 0:
            avg = (arr[i] + arr[i + 1]) / 2
        elif i == len(arr) - 1:
            avg = (arr[i] + arr[i - 1]) / 2
        else:
            avg = (arr[i - 1] + arr[i] + arr[i + 1]) / 3
        result.append(avg)
    return result

