from typing import List, Any


def sum_nested_list(nested_list: List[Any]) -> int:
    """
    Calculate the sum of all integer elements in a potentially nested list.

    Args:
    nested_list (List[Any]): A potentially nested list of integers.

    Returns:
    int: The sum of all integer elements in the nested list.
    """
    def helper(lst):
        total = 0
        for elem in lst:
            if isinstance(elem, list):
                total += helper(elem)
            elif isinstance(elem, int):
                total += elem
        return total

    return helper(nested_list)

