def cumulative_sum(collection: list[int]) -> list[int]:
    """
    Returns a list where each element is the cumulative sum of the elements up to that point in the input list.
    """
    if not collection:
        return []

    result = [collection[0]]
    for i in range(1, len(collection)):
        result.append(result[-1] + collection[i])
    return result

