def max_rocks_sequence(rocks: list) -> int:
    """
    Returns the length of the longest sequence of consecutive days during which 
    the number of rocks thrown is non-decreasing.
    """
    if not rocks:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(rocks)):
        if rocks[i] >= rocks[i - 1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

