from collections import deque


def min_connections(graph, user1, user2):
    """
    Returns the minimum number of connections required to connect user1 and user2 in the social network graph.
    """
    if user1 not in graph or user2 not in graph:
        return -1

    if user1 == user2:
        return 0

    # Breadth-First Search (BFS) to find the shortest path
    queue = deque([(user1, 0)])
    visited = set([user1])

    while queue:
        current_user, distance = queue.popleft()

        for neighbour in graph[current_user]:
            if neighbour == user2:
                return distance + 1
            if neighbour not in visited:
                visited.add(neighbour)
                queue.append((neighbour, distance + 1))

    return -1

