def factorial(n: int) -> int:
    """
    Returns the factorial of a non-negative integer n using recursion.
    Raises ValueError if the input is not a non-negative integer.
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return 1
    return n * factorial(n - 1)

def text_to_html(text: str) -> str:
    """
    Converts a given text into a simplified HTML structure.

    Headers marked with '#' (for <h1>), '##' (for <h2>), and plain text into <p>.
    """
    # Define a list to hold the HTML lines
    html_lines = []

    # Split the text into lines
    lines = text.split('\n')

    # Process each line
    for line in lines:
        stripped_line = line.strip()

        if stripped_line.startswith('# '):
            html_lines.append(f"<h1>{stripped_line[2:]}</h1>")
        elif stripped_line.startswith('## '):
            html_lines.append(f"<h2>{stripped_line[3:]}</h2>")
        elif stripped_line:
            html_lines.append(f"<p>{stripped_line}</p>")

    # Join the HTML lines into a single string
    return ''.join(html_lines)

from typing import List
import bisect


def length_of_LIS(prices: List[int]) -> int:
    """
    This function returns the length of the longest increasing subsequence 
    of the given list of stock prices 'prices'.
    """
    if not prices:
        return 0

    lis = []
    for price in prices:
        pos = bisect.bisect_left(lis, price)
        if pos < len(lis):
            lis[pos] = price
        else:
            lis.append(price)

    return len(lis)

