from itertools import permutations


def unique_substrings_count(s: str, n: int) -> int:
    """
    Given a string s and an integer n, return the count of unique substrings of length n
    from the permutations of the string s.
    """
    perm_set = set(''.join(p) for p in permutations(s))
    unique_substrings = set()

    for perm in perm_set:
        for i in range(len(perm) - n + 1):
            unique_substrings.add(perm[i:i+n])

    return len(unique_substrings)

