def remove_k_consecutive_duplicates(s: str, k: int) -> str:
    """
    Removes k consecutive duplicate characters from the string s iteratively
    until no such duplicates exist.
    """
    stack = []

    for char in s:
        if stack and stack[-1][0] == char:
            stack[-1][1] += 1
        else:
            stack.append([char, 1])

        if stack[-1][1] == k:
            stack.pop()

    result = ''.join(char * count for char, count in stack)
    return result

