from typing import List


def sort_list_custom(arr: List[int], order: str) -> List[int]:
    """
    Sorts the given list according to the specified order.

    Parameters:
    arr (List[int]): A list of integers to sort.
    order (str): The order in which to sort the list. Either 'ascending' or 'descending'.

    Returns:
    List[int]: A new list sorted according to the specified order.

    Raises:
    ValueError: If the `order` is neither 'ascending' nor 'descending'.
    """
    if order == 'ascending':
        return sorted(arr)
    elif order == 'descending':
        return sorted(arr, reverse=True)
    else:
        raise ValueError("`order` must be either 'ascending' or 'descending'")

