def optimized_compress(s: str) -> str:
    """
    Compresses the input string by replacing sequences of the same character with the character 
    followed by the count of repeated occurrences. Single characters that are not part of a repeating sequence will remain unchanged.

    :param s: A string comprised of lowercase and uppercase alphabets.
    :return: A compressed version of the given string.
    """
    if not s:
        return ""

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            compressed.append(s[i-1])
            if count > 1:
                compressed.append(str(count))
            count = 1

    # Handle the last sequence
    compressed.append(s[-1])
    if count > 1:
        compressed.append(str(count))

    return ''.join(compressed)

