def transpose_matrix(matrix):
    """
    Given a 2-dimensional list (matrix), return its transpose.
    """
    if not matrix:
        return []

    m, n = len(matrix), len(matrix[0])
    transpose = [[None]*m for _ in range(n)]

    for i in range(m):
        for j in range(n):
            transpose[j][i] = matrix[i][j]

    return transpose

def find_duplicates(n: int, arr: list[int]) -> list[int]:
    """
    Returns a list of integers that appear exactly twice in the input array.
    """
    element_count = {}
    for num in arr:
        if num in element_count:
            element_count[num] += 1
        else:
            element_count[num] = 1

    duplicates = [num for num, count in element_count.items() if count == 2]
    return sorted(duplicates)

