from typing import List


def grade_exam(answers: List[str], key: List[str], points: int, penalty: int) -> int:
    """
    Grades an exam based on student's answers and the answer key, awarding points
    for correct answers and deducting points for incorrect answers.
    """
    total_score = 0

    for student_answer, correct_answer in zip(answers, key):
        if student_answer == '':
            continue  # Ignore unanswered questions
        elif student_answer == correct_answer:
            total_score += points
        else:
            total_score -= penalty

    return total_score

