from typing import List


def longest_sentence(sentences: List[str]) -> str:
    """
    Returns the longest sentence from the list of sentences. If there are multiple sentences
    with the same length, it returns the first one.
    """
    if not sentences:
        return ""

    longest = sentences[0]
    for sentence in sentences[1:]:
        if len(sentence) > len(longest):
            longest = sentence

    return longest

