def IndexParity(arr):
    """
    Returns a dictionary with the keys "even" and "odd". 
    The values are lists of indices where even and odd 
    numbers occur in the original list, respectively.
    """
    result = {"even": [], "odd": []}
    for index, value in enumerate(arr):
        if value % 2 == 0:
            result["even"].append(index)
        else:
            result["odd"].append(index)
    return result

