def replace_digits_with_words(text):
    """
    Replaces all digits with their corresponding English words in the input string.

    Parameters:
    text (str): The input string containing a mix of lowercase letters and digits.

    Returns:
    str: The string with digits replaced by their corresponding English words.
    """
    digit_to_word = {
        '0': 'zero', '1': 'one', '2': 'two', '3': 'three',
        '4': 'four', '5': 'five', '6': 'six', '7': 'seven',
        '8': 'eight', '9': 'nine'
    }

    result = []
    for char in text:
        if char.isdigit():
            result.append(digit_to_word[char])
        else:
            result.append(char)

    return ''.join(result)

