def merge_dictionaries(dict1, dict2):
    """
    Merges two dictionaries, combining values for each key that appears in both dictionaries.
    If the key exists only in one of the dictionaries, retains its existing value.
    Assumes the values are always integers.

    Raises:
        ValueError: If any value in the dictionaries is not an integer.
    """
    result_dict = dict1.copy()

    for key, value in dict2.items():
        if not isinstance(value, int):
            raise ValueError(f"Value for key '{key}' in the second dictionary is not an integer.")
        if key in result_dict:
            if not isinstance(result_dict[key], int):
                raise ValueError(f"Value for key '{key}' in the first dictionary is not an integer.")
            result_dict[key] += value
        else:
            result_dict[key] = value

    return result_dict

