def fibonacci_sequence(n):
    """
    This function takes an integer n as input and returns a list containing the first n numbers in the Fibonacci sequence.
    """
    if n <= 0:
        return []
    fib_seq = [0]
    if n == 1:
        return fib_seq
    fib_seq.append(1)
    for i in range(2, n):
        fib_seq.append(fib_seq[-1] + fib_seq[-2])
    return fib_seq

