from typing import List, Dict


def count_string_occurrences(lst: List[str]) -> Dict[str, int]:
    """
    Counts the occurrences of each unique string in the list.

    Args:
    lst (List[str]): A list of strings.

    Returns:
    Dict[str, int]: A dictionary with the count of occurrences of each unique string.
    """
    occurrence_dict = {}
    for string in lst:
        if string in occurrence_dict:
            occurrence_dict[string] += 1
        else:
            occurrence_dict[string] = 1
    return occurrence_dict

