def calculate_frequency(s):
    """
    Returns a dictionary where each key is a unique character from the string s (ignoring spaces and case),
    and its value is the frequency of that character.
    """
    frequency_dict = {}
    for char in s.lower():
        if char.isalpha():
            if char in frequency_dict:
                frequency_dict[char] += 1
            else:
                frequency_dict[char] = 1
    return frequency_dict

