def find_pairs_with_sum(int_list, target_sum):
    """
    Returns a list of all pairs of integers in the list that add up to the target sum.
    Each pair is returned as a tuple, and the list of pairs is sorted in ascending order
    by the first value of each tuple.
    """
    pairs = []
    int_list = sorted(int_list)  # sort the input list to handle pairs in the ascending order

    for i in range(len(int_list)):
        for j in range(i + 1, len(int_list)):
            if int_list[i] + int_list[j] == target_sum:
                pairs.append((int_list[i], int_list[j]))

    return pairs

