import bisect


def length_of_LIS(nums):
    """
    Returns the length of the longest strictly increasing subsequence in nums.
    Uses a time complexity of O(n log n) where n is the number of elements in the list.

    Args:
    nums (list): A list of integers

    Returns:
    int: The length of the longest strictly increasing subsequence
    """
    if not nums:
        return 0

    sub = []
    for x in nums:
        if len(sub) == 0 or x > sub[-1]:
            sub.append(x)
        else:
            idx = bisect.bisect_left(sub, x)
            sub[idx] = x

    return len(sub)

