def separate_positive_negative(numbers):
    """
    Takes a list of strings where each string can be either a positive or a negative integer,
    and returns a dictionary with two keys: "positive" and "negative".
    The value associated with each key is a list of integers that are either positive or negative,
    sorted in ascending order.

    Args:
    numbers (list of str): List of strings representing integers.

    Returns:
    dict: A dictionary with two keys: "positive" and "negative".
    """
    positive = []
    negative = []

    for num in numbers:
        try:
            num_int = int(num)
            if num_int >= 0:
                positive.append(num_int)
            else:
                negative.append(num_int)
        except ValueError:
            continue

    return {
        "positive": sorted(positive),
        "negative": sorted(negative)
    }

