from typing import List, Dict


def count_occurrences_with_mode(input_list: List[int]) -> Dict:
    """
    Processes a list of integers and returns a dictionary containing the number of occurrences
    of each integer and the mode (the integer that appears the most frequently).
    """
    if not input_list:
        return {"mode": None} # handle empty list case

    occurrence_dict = {}
    for number in input_list:
        if number in occurrence_dict:
            occurrence_dict[number] += 1
        else:
            occurrence_dict[number] = 1

    # find the mode
    mode = max(occurrence_dict, key=occurrence_dict.get)
    occurrence_dict["mode"] = mode

    return occurrence_dict

