def shift_letters(input_string):
    """
    Returns a new string where all the letters are shifted to their next letter in the alphabet
    and all digits remain unchanged. 'z' or 'Z' wraps around to 'a' or 'A' respectively.
    """
    def shift_char(c):
        if c.isalpha():
            if c == 'z':
                return 'a'
            elif c == 'Z':
                return 'A'
            else:
                return chr(ord(c) + 1)
        else:
            return c

    return ''.join(shift_char(c) for c in input_string)

