def longest_subsequence_with_target_sum(arr, target):
    """
    Returns the length of the longest contiguous subsequence that sums to the target value.
    If no such subsequence exists, returns 0.
    """
    prefix_sum = 0
    prefix_sum_index_map = {0: -1}
    max_length = 0

    for index, num in enumerate(arr):
        prefix_sum += num
        if prefix_sum - target in prefix_sum_index_map:
            max_length = max(max_length, index - prefix_sum_index_map[prefix_sum - target])

        if prefix_sum not in prefix_sum_index_map:
            prefix_sum_index_map[prefix_sum] = index

    return max_length

