def longest_zero_sum_subarray(arr):
    """
    Returns the length of the longest contiguous subarray with sum equal to zero.
    """
    sum_index_map = {}  # To store the first occurrence of a sum
    max_length = 0
    current_sum = 0

    for index, value in enumerate(arr):
        current_sum += value

        if current_sum == 0:
            max_length = index + 1

        if current_sum in sum_index_map:
            max_length = max(max_length, index - sum_index_map[current_sum])
        else:
            sum_index_map[current_sum] = index

    return max_length

