def intersect_lists_preserve_order(list1, list2):
    """
    Returns a list of integers that are present in both input lists, preserving the order they appear 
    in the first list. If there are duplicated values in the first list, they should be included in 
    the result the same number of times they appear in the first list, provided they also appear in 
    the second list at least that many times.
    """
    result = []
    count_map = {}

    for num in list2:
        count_map[num] = count_map.get(num, 0) + 1

    for num in list1:
        if count_map.get(num, 0) > 0:
            result.append(num)
            count_map[num] -= 1

    return result

