def intersection(collection1, collection2):
    """
    Returns the intersection of two collections as a list.
    The collections can be either sets or lists.
    """
    if not isinstance(collection1, (set, list)) or not isinstance(collection2, (set, list)):
        raise TypeError("Both arguments must be of type set or list")

    set1, set2 = set(collection1), set(collection2)
    return list(set1 & set2)

