def intersect(tuple_list):
    """
    Returns a list of the intersection between all tuples in the tuple_list.

    Each element in the tuple_list is a tuple containing integers. 
    The function should return a list containing the integers that appear in every tuple.
    """
    if not tuple_list:
        return []

    # Get the intersection of all tuples
    result_set = set(tuple_list[0])
    for t in tuple_list[1:]:
        result_set &= set(t)

    return list(result_set)

