def find_consecutive_ones(items):
    """
    Returns the index of the first sequence of 5 consecutive 1's in the list.
    If no such sequence exists, returns -1.
    """
    for i in range(len(items) - 4):
        if all(x == 1 for x in items[i:i+5]):
            return i
    return -1

