def generate_sequence(n):
    """
    Generate a sequence where each term is a sum of two previous terms and is a multiple of 3.
    """
    if n == 1:
        return [3]
    elif n == 2:
        return [3, 6]

    sequence = [3, 6]
    for i in range(2, n):
        next_term = sequence[i-1] + sequence[i-2]
        sequence.append(next_term)
    return sequence

