def does_signal_match_pattern(signal, pattern):
    """
    Returns whether the signal matches the pattern.
    The wildcard character in the pattern is represented by '.' and can match any non-negative integer.
    """
    if len(signal) != len(pattern):
        return False

    for s, p in zip(signal, pattern):
        if p != '.' and s != int(p):
            return False

    return True

