def count_occurrences(char_list, target_char):
    """
    Returns the frequency of the specified character in the list, ignoring case.
    If the list is empty, returns None.
    """
    if not char_list:
        return None

    target_char = target_char.lower()
    count = 0

    for char in char_list:
        if char.lower() == target_char:
            count += 1

    return count

