def sum_elements_in_range(numbers):
    """
    Returns the sum of all elements in the list that are greater than 2 and less than 6.
    If there are no such elements, returns None.
    """
    try:
        valid_elements = [num for num in numbers if 2 < num < 6]
        if not valid_elements:
            return None
        return sum(valid_elements)
    except TypeError:
        raise ValueError("Input must be a list of integers")

