import re


def strings_to_dict(strings):
    """
    Takes a list of strings and returns a dictionary with the strings as keys and their lengths as values.
    Ignores strings that contain numbers or special characters and handles duplicates by including only the first occurrence.
    """
    result = {}
    for string in strings:
        if not re.search(r'[^a-zA-Z]', string) and string not in result:
            result[string] = len(string)
    return result

