def count_characters(s):
    """
    Counts the number of uppercase letters, lowercase letters, digits,
    and special characters in the given string `s`.

    Parameters:
    s (str): The input string to be analyzed.

    Returns:
    dict: A dictionary with counts of uppercase, lowercase, digits, and special characters.
    """
    counts = {
        'uppercase': 0,
        'lowercase': 0,
        'digits': 0,
        'special': 0
    }

    for char in s:
        if char.isupper():
            counts['uppercase'] += 1
        elif char.islower():
            counts['lowercase'] += 1
        elif char.isdigit():
            counts['digits'] += 1
        else:
            counts['special'] += 1

    return counts

