def sum_of_dict(d):
    """
    Returns the sum of all items in a given dictionary with integer values.
    The dictionary may contain nested dictionaries as values.
    """
    total = 0
    for key, value in d.items():
        if isinstance(value, dict):
            total += sum_of_dict(value)
        elif isinstance(value, int):
            total += value
    return total

