def tuple_list_to_freq_dict(tuple_list):
    """
    Given a list of tuples, returns a dictionary where the keys are the integer values
    from the tuples and the values are the frequencies of these integers across all tuples.
    """
    freq_dict = {}
    for tup in tuple_list:
        for elem in tup:
            if isinstance(elem, (int, float)):
                key = int(elem)
                if key in freq_dict:
                    freq_dict[key] += 1
                else:
                    freq_dict[key] = 1
    return freq_dict

