def check_course_enrollment_status(education_level):
    """
    Determines if a professional with a given education level is eligible 
    for a special analysis course enrollment.

    Parameters:
    education_level (str): The education level of the professional.

    Returns:
    str: The enrollment status message.
    """
    if education_level == "High School":
        return "Eligible for foundational courses only."
    elif education_level == "Associate Degree":
        return "Eligible for introductory analysis courses."
    elif education_level == "Bachelor's Degree":
        return "Eligible for all analysis courses."
    elif education_level == "Master's Degree" or education_level == "PhD":
        return "Eligible for advanced analysis courses."
    else:
        return "Education level not recognized for enrollment."

