def get_first_and_last_word(sentence):
    """
    Returns the first and last word of the given sentence.
    If the sentence is empty or has only one word, both words returned would be the same.
    """
    words = sentence.split()
    if not words:
        return ("", "")
    if len(words) == 1:
        return (words[0], words[0])
    return (words[0], words[-1])

