def separate_even_odd(numbers):
    """
    Returns two lists: one containing the even numbers and the other containing the odd numbers from the input list.
    """
    even_numbers = []
    odd_numbers = []

    for number in numbers:
        if number % 2 == 0:
            even_numbers.append(number)
        else:
            odd_numbers.append(number)

    return even_numbers, odd_numbers

