def programmers_switcheroo(matrix):
    """
    Perform a "Programmer's Switcheroo" on the matrix by swapping its first and last column.
    """
    if not matrix or not matrix[0]:
        return matrix

    for row in matrix:
        row[0], row[-1] = row[-1], row[0]
    return matrix

