def contains_all_letters(s):
    """
    Check if the input string contains all lowercase English letters exactly once.
    """
    letters_set = set('abcdefghijklmnopqrstuvwxyz')

    if len(s) != 26:
        return False

    for char in s:
        if char not in letters_set:
            return False
        letters_set.remove(char)

    return len(letters_set) == 0

