def extract_odd_numbers(int_list):
    """
    Accepts a list of integers and returns a list containing only the odd numbers from the input list.
    If the input list contains any non-integer values, it returns an empty list.
    """
    try:
        # Verify all elements in the list are integers
        if not all(isinstance(i, int) for i in int_list):
            return []
        # Filter and return odd numbers
        return [num for num in int_list if num % 2 != 0]
    except Exception:
        return []

