from decimal import Decimal, InvalidOperation


def is_factor(str_num1, str_num2):
    """
    Determines if the first number (str_num1) is a factor of the second number (str_num2).
    Both inputs are strings representing decimal numbers which may be very large.
    Returns True if str_num1 is a factor of str_num2, and False otherwise.
    """
    try:
        num1 = Decimal(str_num1)
        num2 = Decimal(str_num2)
    except InvalidOperation:
        return False

    if num1 == 0:
        return False

    if num2 % num1 == 0:
        return True
    else:
        return False

