def alternate_chars(str1, str2):
    """
    Returns a new string with characters alternated from str1 and str2.
    If one string is longer than the other, the rest of the characters
    from the longer string are appended at the end.
    """
    result = []
    len1, len2 = len(str1), len(str2)
    length = max(len1, len2)

    for i in range(length):
        if i < len1:
            result.append(str1[i])
        if i < len2:
            result.append(str2[i])

    return ''.join(result)

