def f(x):
    """
    Returns True if x is a prime number, otherwise False.
    Includes error checking for non-integer inputs.
    """
    if not isinstance(x, int):
        return False

    if x <= 1:
        return False

    for i in range(2, int(x**0.5) + 1):
        if x % i == 0:
            return False

    return True

