def identify_type(value):
    """
    Identifies the type of a value without using built-in type function.
    Returns a string indicating the type: 'int', 'float', 'str', 'bool', 'list', or 'NoneType'.
    """
    if value is None:
        return 'NoneType'
    if isinstance(value, bool):
        return 'bool'
    if isinstance(value, int):
        return 'int'
    if isinstance(value, float):
        return 'float'
    if isinstance(value, str):
        return 'str'
    if isinstance(value, list):
        return 'list'

    # If the type is not one of the expected ones
    return 'unknown'

