def sort_even_odd(nums):
    """
    Modifies the list in-place such that all even numbers appear before all odd numbers.
    The original order of the even and odd numbers is maintained.
    """
    even_idx = 0  # pointer for the next position to place an even number

    for i in range(len(nums)):
        if nums[i] % 2 == 0:
            nums.insert(even_idx, nums.pop(i))
            even_idx += 1

import string


def find_most_common_letter(s):
    """
    Finds the most common letter in the provided string, case-insensitive.
    Punctuation is ignored.

    :param s: The input string
    :return: A tuple containing the most common letter and its frequency
    """
    s = s.translate(str.maketrans('', '', string.punctuation)).lower()
    letter_counts = {}

    for char in s:
        if char.isalpha():
            if char in letter_counts:
                letter_counts[char] += 1
            else:
                letter_counts[char] = 1

    most_common = max(letter_counts, key=letter_counts.get)

    return most_common, letter_counts[most_common]

