def normalize_points(points):
    """
    Normalizes the x and y values of each tuple in the input list of points
    to be between 0 and 1 based on the minimum and maximum x and y values.
    """
    if not points:
        return []

    xs, ys = zip(*points)

    min_x, max_x = min(xs), max(xs)
    min_y, max_y = min(ys), max(ys)

    if min_x == max_x and min_y == max_y:
        return [(0.5, 0.5)] * len(points)

    def normalize(val, min_val, max_val):
        return (val - min_val) / (max_val - min_val) if max_val != min_val else 0.5

    return [(normalize(x, min_x, max_x), normalize(y, min_y, max_y)) for x, y in points]

