    Converts all the values in the input dictionary to integers. If a value 
    is a float, it is rounded to the nearest integer. If a value is a string 
    that can be converted to a number, it is converted to an integer. 
    If a value cannot be converted to an integer, it is set to 0.

    Args:
    input_dict (dict): Dictionary with values to be converted.

    Returns:
    dict: New dictionary with the same keys but values as integers.
    """
    output_dict = {}

    def convert_value(value):
        try:
            # attempt to convert via float first, to accommodate numeric strings and pure floats
            return int(round(float(value)))
        except ValueError:
            # if that does not work, return 0
            return 0

    for key, value in input_dict.items():
        output_dict[key] = convert_value(value)

    return output_dict

