def fibonacci(n):
    """
    Returns the n-th Fibonacci number using recursion, where n is a non-negative integer.
    Handles edge cases for negative inputs by raising a ValueError.
    """
    if n < 0:
        raise ValueError("Input should be a non-negative integer")
    if n in [0, 1]:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

