def convert_list_to_string(numbers):
    """
    Converts a list of numbers into a comma-separated string,
    where every third number is highlighted with asterisks before and after it.

    Parameters:
    numbers (list): List of integers

    Returns:
    str: Formatted string
    """
    result = []
    for i, num in enumerate(numbers):
        if (i + 1) % 3 == 0:
            result.append(f"*{num}*")
        else:
            result.append(str(num))
    return ",".join(result)

