def find_max_length_list(lists):
    """
    Returns the list with the maximum length and its length as a tuple.

    Parameters:
    lists (list of lists): A list containing other lists.

    Returns:
    tuple: A tuple containing the list with the maximum length and its length.
    """
    if not lists:
        return ([], 0)

    max_list = lists[0]
    max_length = len(max_list)

    for lst in lists[1:]:
        current_length = len(lst)
        if current_length > max_length:
            max_list = lst
            max_length = current_length

    return (max_list, max_length)

