def sum_nested_list(lst):
    """
    Sums all integers in a potentially nested list.
    """
    total = 0
    for item in lst:
        if isinstance(item, list):
            total += sum_nested_list(item)
        elif isinstance(item, int):
            total += item
        else:
            raise TypeError("The list must only contain integers or lists")
    return total

