def flatten_json(json_obj, parent_key='', sep='.'):
    """
    Flatten a nested JSON structure into a list of key-value pairs.

    :param json_obj: The JSON object to flatten.
    :param parent_key: The base key to use for nested keys (used in recursion, default is empty string).
    :param sep: The separator to use between keys.
    :return: A list of key-value pairs.
    """
    items = []
    if isinstance(json_obj, dict):
        for k, v in json_obj.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            items.extend(flatten_json(v, new_key, sep=sep))
    elif isinstance(json_obj, list):
        for i, v in enumerate(json_obj):
            new_key = f"{parent_key}{sep}{i}" if parent_key else str(i)
            items.extend(flatten_json(v, new_key, sep=sep))
    else:
        items.append((parent_key, json_obj))
    return items

