def sum_of_squares(float_list):
    """
    Takes a list of floating point numbers and returns the sum of the squares of all the elements.
    """
    if not isinstance(float_list, list):
        raise ValueError("Input should be a list.")
    for i in float_list:
        if not isinstance(i, (int, float)):
            raise ValueError("All items in the list should be numbers.")
    return sum(x ** 2 for x in float_list)

