def word_lines(input_string):
    """
    Returns a dictionary where keys are unique words and values are lists of line numbers on which each word appears.
    """
    lines = input_string.splitlines()
    word_dict = {}

    for line_number, line in enumerate(lines, start=1):
        words = line.split()
        for word in words:
            if word not in word_dict:
                word_dict[word] = []
            if line_number not in word_dict[word]:
                word_dict[word].append(line_number)

    return word_dict

