def calculate_length_of_string(s, reverse=False):
    """
    Returns the length of string s if reverse is False.
    Returns the reversed string if reverse is True.
    If s is None, returns 0.
    """
    if s is None:
        return 0
    if reverse:
        return s[::-1]
    return len(s)

