import json


def count_key_occurrences(json_str, key):
    """
    Returns the total number of occurrences of the specific key in the JSON string.

    Args:
    json_str (str): A JSON formatted string.
    key (str): The key to count occurrences of.

    Returns:
    int: The count of occurrences of the specified key.
    """
    def recursive_count(d, key):
        count = 0
        if isinstance(d, dict):
            for k, v in d.items():
                if k == key:
                    count += 1
                count += recursive_count(v, key)
        elif isinstance(d, list):
            for item in d:
                count += recursive_count(item, key)
        return count

    data = json.loads(json_str)
    return recursive_count(data, key)

