def count_even_odd_nonnumeric(s):
    """
    Counts the number of even digits, odd digits, and non-numeric characters in the string s.

    Parameters:
    s (str): The input string.

    Returns:
    tuple: A tuple containing the counts of even digits, odd digits, and non-numeric characters.
    """
    even_count = 0
    odd_count = 0
    non_numeric_count = 0

    for char in s:
        if char.isdigit():
            if int(char) % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
        else:
            non_numeric_count += 1

    return (even_count, odd_count, non_numeric_count)

