def calculate_differences(numbers):
    """
    Calculates the differences between consecutive numbers in a list.
    If the list contains only one number, returns an empty list.
    If it contains less than one number, returns a message indicating that 
    the list is too short to calculate differences.
    """
    if len(numbers) < 1:
        return "The list is too short to calculate differences."
    elif len(numbers) == 1:
        return []
    else:
        differences = []
        for i in range(1, len(numbers)):
            differences.append(numbers[i] - numbers[i-1])
        return differences

