def longest_alternating_subsequence(arr):
    """
    Returns the length of the longest alternating subsequence in a given list of numbers.
    """
    n = len(arr)
    if n == 0:
        return 0

    # Initialize the lengths of longest alternating subsequences ending at each index
    inc = 1
    dec = 1

    for i in range(1, n):
        if arr[i] > arr[i - 1]:
            inc = dec + 1
        elif arr[i] < arr[i - 1]:
            dec = inc + 1

    return max(inc, dec)

