def sum_array(arr):
    """
    Returns the sum of an array of integers using recursion.

    Parameters:
    arr (list of int): The list of integers to sum up.

    Returns:
    int: The sum of the integers in the array.
    """
    if len(arr) == 0:
        return 0
    elif len(arr) == 1:
        return arr[0]
    else:
        return arr[0] + sum_array(arr[1:])

