def count_characters(s):
    """
    This function takes a string input and counts the number of uppercase letters,
    lowercase letters, digits, and other characters in the string.
    """
    uppercase_count = 0
    lowercase_count = 0
    digit_count = 0
    other_count = 0

    for char in s:
        if char.isupper():
            uppercase_count += 1
        elif char.islower():
            lowercase_count += 1
        elif char.isdigit():
            digit_count += 1
        else:
            other_count += 1

    return uppercase_count, lowercase_count, digit_count, other_count

