def max_distance_between_char(s, c):
    """
    Returns the maximum distance between the target character `c` in the string `s`.
    If `c` does not appear in `s`, returns -1.
    """
    positions = [index for index, char in enumerate(s) if char == c]
    if not positions:
        return -1
    return max(positions) - min(positions)

