def smallest_missing_positive(arr):
    """
    Finds the smallest positive integer missing from an unsorted array.
    """
    if not arr:
        return 1

    n = len(arr)

    # Place each number in its right place, e.g., 5 in index 4
    for i in range(n):
        while 1 <= arr[i] <= n and arr[arr[i] - 1] != arr[i]:
            correct_index = arr[i] - 1
            arr[i], arr[correct_index] = arr[correct_index], arr[i]

    # Find the first index which is not filled correctly
    for i in range(n):
        if arr[i] != i + 1:
            return i + 1

    # If all indexes are filled correctly, the missing number is n + 1
    return n + 1

