def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in a given string along with its index.
    If there is no non-repeating character, returns None.

    :param s: The input string.
    :return: A tuple containing the character and its index, or None if there is no non-repeating character.
    """
    char_count = {}
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    for index, char in enumerate(s):
        if char_count[char] == 1:
            return (char, index)

    return None

