def simple_calculator(expression):
    """
    Evaluates a simple arithmetic expression of the form "num1 operator num2".

    Args:
    expression (str): A string containing two numbers and an operator.

    Returns:
    int/str: The result of the arithmetic operation or an error message for division by zero.
    """
    try:
        parts = expression.split()
        num1 = int(parts[0])
        operator = parts[1]
        num2 = int(parts[2])
    except (IndexError, ValueError):
        return "Error: Invalid input format"

    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 == 0:
            return "Error: Division by zero"
        return round(num1 / num2)
    else:
        return "Error: Invalid operator"

