def max_sum_no_adjacent(nums):
    """
    Returns the maximum sum of a subsequence where no two elements are adjacent.
    """
    if not nums:
        return 0
    if len(nums) == 1:
        return nums[0]

    incl = nums[0]
    excl = 0

    for i in range(1, len(nums)):
        new_excl = max(excl, incl)
        incl = excl + nums[i]
        excl = new_excl

    return max(incl, excl)

