def chatbot_response(message):
    """
    Returns a chatbot response based on the user's message.
    """
    message = message.lower()
    if "quit" in message or "exit" in message:
        return "Goodbye! Have a nice day!"
    elif "hello" in message or "hi" in message:
        return "Hello there!"
    elif "how are you" in message:
        return "I'm just a bot, but I'm doing great! How can I help you today?"
    elif "thank you" in message or "thanks" in message:
        return "You're welcome!"
    elif "weather" in message:
        return "I'm not sure about the weather, but I hope it's nice!"
    elif "name" in message:
        return "I am the Simple Chatbot."
    else:
        return "I'm not sure how to respond to that."

