def count_words(text):
    """
    Returns a dictionary with the count of each unique word in the input string.

    :param text: A string containing the text to be analyzed
    :return: A dictionary with words as keys and their counts as values
    """
    words = text.split()
    word_count = {}

    for word in words:
        word = word.lower()
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    return word_count

