def solution(S):
    """
    Checks whether the given string S containing parentheses is balanced.
    """
    stack = []
    for i in S:
        if i == "(":
            stack.append(i)
        elif i == ")":
            if len(stack) > 0 and stack[-1] == "(":
                stack.pop()
            else:
                return 0
    return 1 if len(stack) == 0 else 0

def find_pair(nums, target):
    """
    Finds the first pair of elements in an unsorted array that sum to a given target.
    """
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                return [nums[i], nums[j]]
    return []

