def flatten_dict(nested_dict, delimiter):
    """
    Flattens a nested dictionary into a single level dictionary with concatenated keys.

    Parameters:
    nested_dict (dict): The input dictionary to flatten.
    delimiter (str): The delimiter used to concatenate the keys.

    Returns:
    dict: The flattened dictionary with concatenated keys.
    """
    def _flatten(current_dict, parent_key=''):
        items = {}
        for k, v in current_dict.items():
            new_key = f"{parent_key}{delimiter}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    return _flatten(nested_dict)

