def simulate_journey(commands):
    """
    Simulates the movement of a character in a 2D grid.

    Parameters:
    commands (list): A list of strings, where each string is one of the allowed movement commands.

    Returns:
    tuple: The final position (x, y) of the character after all commands have been executed.
    """
    # Initial position
    x, y = 0, 0

    # Process each command
    for command in commands:
        if command == "left":
            x -= 1
        elif command == "right":
            x += 1
        elif command == "up":
            y += 1
        elif command == "down":
            y -= 1

    # Return final position
    return (x, y)

