def hangman(word, guesses):
    """
    Simulates a simple version of the game Hangman.

    Parameters:
        word (str): The word to be guessed.
        guesses (list of str): The player's guesses.

    Returns:
        tuple: The current guessed state of the word and the number of incorrect guesses.
    """
    guessed_state = ['_'] * len(word)
    incorrect_guesses = 0

    for guess in guesses:
        if guess in word:
            for i, char in enumerate(word):
                if char == guess:
                    guessed_state[i] = guess
        else:
            incorrect_guesses += 1

    return ''.join(guessed_state), incorrect_guesses

