def max_subarray_length(nums, k):
    """
    Finds the maximum length of a subarray that sums to k.
    """
    # Dictionary to store the first occurrence of a particular cumulative sum
    sum_indices = {0: -1}
    curr_sum = 0
    max_length = 0

    for i, num in enumerate(nums):
        curr_sum += num

        if curr_sum - k in sum_indices:
            max_length = max(max_length, i - sum_indices[curr_sum - k])

        if curr_sum not in sum_indices:
            sum_indices[curr_sum] = i

    return max_length

