def alphabet_position(text: str) -> str:
    """
    Converts each alphabetical character in the input text to its corresponding number 
    based on its position in the alphabet. Non-alphabet characters are ignored.

    :param text: The input string containing any characters.
    :return: A string containing the numerical positions separated by spaces.
    """
    positions = []
    for char in text:
        if char.isalpha():
            positions.append(str(ord(char.lower()) - ord('a') + 1))
    return " ".join(positions)

