def is_valid_parentheses(expression: str) -> bool:
    """
    Returns True if the parentheses in the expression are valid, otherwise False.
    A valid expression has every opening parenthesis properly closed in the correct order.
    """
    stack = []
    parentheses_map = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in parentheses_map.values():
            stack.append(char)
        elif char in parentheses_map.keys():
            if stack == [] or parentheses_map[char] != stack.pop():
                return False
            elif not stack:
                return True
        else:
            continue  # ignore other characters

    return stack == []

