from bisect import bisect_left


def max_increasing_puzzle_sequence(puzzles):
    """
    Returns the length of the longest increasing subsequence of difficulty levels in puzzles.

    Args:
    puzzles (list of int): List of integers representing the difficulty levels of puzzles.

    Returns:
    int: Length of the longest increasing subsequence of difficulty levels.
    """
    if not puzzles:
        return 0

    lis = []
    for difficulty in puzzles:
        pos = bisect_left(lis, difficulty)
        if pos == len(lis):
            lis.append(difficulty)
        else:
            lis[pos] = difficulty

    return len(lis)

