from typing import List, Dict, Any


def find_top_selling_product(transactions: List[Dict[str, Any]]) -> str:
    """
    Given a list of product transactions, returns the name of the product with the highest sales.
    If no transactions are given, returns None.
    """
    if not transactions:
        return None

    product_sales = {}

    for transaction in transactions:
        product = transaction["product"]
        quantity = transaction["quantity"]

        if product in product_sales:
            product_sales[product] += quantity
        else:
            product_sales[product] = quantity

    # Find the product with the highest sales
    top_selling_product = max(product_sales, key=product_sales.get)

    return top_selling_product

