def analyze_word_frequencies(text: str) -> dict:
    """
    Calculate the frequency of each unique word in a given string.

    Args:
    text (str): A string containing multiple words.

    Returns:
    dict: A dictionary with words as keys and their frequencies as values.
    """
    word_frequencies = {}

    words = text.split()
    for word in words:
        if word in word_frequencies:
            word_frequencies[word] += 1
        else:
            word_frequencies[word] = 1

    return word_frequencies

