from typing import List


def subarray_sum(nums: List[int], k: int) -> int:
    """
    Counts the number of continuous subarrays whose sum equals to a given target integer k.
    """
    cumulative_sum = 0
    count = 0
    prefix_sums = {0: 1}

    for num in nums:
        cumulative_sum += num
        if cumulative_sum - k in prefix_sums:
            count += prefix_sums[cumulative_sum - k]
        if cumulative_sum in prefix_sums:
            prefix_sums[cumulative_sum] += 1
        else:
            prefix_sums[cumulative_sum] = 1

    return count

