def flatten_dictionary(nested_dict, delimiter="."):
    """
    Flattens a nested dictionary by concatenating keys with a specified delimiter.

    Args:
        nested_dict (dict): The dictionary to flatten.
        delimiter (str): The delimiter to use for concatenating keys.

    Returns:
        dict: A flattened dictionary.
    """
    def _flatten(current_dict, parent_key, result_dict):
        for k, v in current_dict.items():
            new_key = f"{parent_key}{delimiter}{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten(v, new_key, result_dict)
            else:
                result_dict[new_key] = v

    result = {}
    _flatten(nested_dict, '', result)
    return result

