from typing import List


def find_majority_element(nums: List[int]) -> int:
    """
    Returns the majority element if it exists, otherwise returns -1.
    A majority element is an element that appears more than floor(n/2) times.
    """
    n = len(nums)
    count = {}
    majority_count = n // 2

    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1
        if count[num] > majority_count:
            return num

    return -1

