from bisect import bisect_left
from typing import List


def longest_increasing_subsequence(arr: List[int]) -> int:
    """
    Function to find the length of the longest strictly increasing subsequence in the given array.
    """
    if not arr:
        return 0

    dp = []  # This will store the smallest tail of all increasing subsequences of given lengths

    for num in arr:
        # Find the index where this num can be placed in the dp list
        index = bisect_left(dp, num)

        # If index is equal to the length of dp array, append num
        if index == len(dp):
            dp.append(num)
        else:
            # Otherwise, replace the existing value with num to maintain minimum tail value
            dp[index] = num

    return len(dp)

