def reorder_string(s: str) -> str:
    """
    Reorders the input string such that all digits are moved to the front,
    followed by alphabetic characters, and then special characters.
    The relative order of each category (digits, alphabetic characters,
    special characters) is preserved.

    :param s: Input string containing digits, alphabetic characters, and special characters
    :return: Reordered string
    """
    digits = []
    alphabets = []
    specials = []

    for char in s:
        if char.isdigit():
            digits.append(char)
        elif char.isalpha():
            alphabets.append(char)
        else:
            specials.append(char)

    return ''.join(digits + alphabets + specials)

