def longest_subarray_with_sum_k(nums, k):
    """
    Returns the length of the longest contiguous subarray whose sum is equal to k.

    :param nums: List of integers, the input array
    :param k: Integer, the target sum
    :return: Integer, the length of the longest subarray with sum equal to k
    """
    prefix_sum_map = {}
    current_sum = 0
    max_length = 0

    for i in range(len(nums)):
        current_sum += nums[i]

        if current_sum == k:
            max_length = i + 1

        if current_sum - k in prefix_sum_map:
            max_length = max(max_length, i - prefix_sum_map[current_sum - k])

        if current_sum not in prefix_sum_map:
            prefix_sum_map[current_sum] = i

    return max_length

