def average_scores(scores):
    """
    Compute the average scores for each athlete.
    """
    averages = []
    for athlete_scores in scores:
        valid_scores = [score for score in athlete_scores if score >= 0]
        if valid_scores:
            avg_score = round(sum(valid_scores) / len(valid_scores), 2)
        else:
            avg_score = 0.0
        averages.append(avg_score)
    return averages

