def rle_encode(input_str):
    """
    Compress the input string using Run-Length Encoding (RLE) algorithm.

    Parameters:
    input_str -- A non-empty string consisting of alphanumeric characters and symbols.

    Output:
    A compressed string using RLE format.
    """
    if not input_str:
        return ""

    compressed_str = []
    count = 1

    for i in range(1, len(input_str)):
        if input_str[i] == input_str[i - 1]:
            count += 1
        else:
            compressed_str.append(f"{input_str[i - 1]}{count}")
            count = 1
    compressed_str.append(f"{input_str[-1]}{count}")

    return ''.join(compressed_str)

