def common_chars(words: list[str]) -> list[str]:
    """
    Returns a list of characters that appear in all strings within the list, including duplicates.
    """
    if not words:
        return []

    # Start with the character count of the first word
    common_count = {char: words[0].count(char) for char in set(words[0])}

    # Iterate through the rest of the words
    for word in words[1:]:
        current_count = {char: word.count(char) for char in set(word)}

        # Update the common count dictionary
        for char in list(common_count.keys()):
            if char in current_count:
                common_count[char] = min(common_count[char], current_count[char])
            else:
                del common_count[char]

    # Convert the common count dictionary to the result list
    result = []
    for char, count in common_count.items():
        result.extend([char] * count)

    return result

