from typing import List
import bisect


def length_of_lis(prices: List[int]) -> int:
    """
    Returns the length of the longest increasing subsequence in the given list of prices.
    """
    if not prices:
        return 0

    # dp will store the increasing subsequences formed
    dp = []

    for price in prices:
        # Find the index where the price fits in the dp array
        idx = bisect.bisect_left(dp, price)
        # If the price is larger than any element in dp, it extends the largest subsequence
        if idx == len(dp):
            dp.append(price)
        else:
            dp[idx] = price

    return len(dp)

