def regex_match(s: str, p: str) -> bool:
    """
    Perform regular expression matching with support for '.' and '*'.
    """
    # Create a memoization table
    memo = {}

    def dp(i, j):
        if (i, j) not in memo:
            if j == len(p):
                ans = i == len(s)
            else:
                first_match = i < len(s) and p[j] in {s[i], '.'}

                if j + 1 < len(p) and p[j + 1] == '*':
                    ans = (dp(i, j + 2) or  # case where '*' means zero occurrences
                           first_match and dp(i + 1, j))  # case where '*' means one or more occurrences
                else:
                    ans = first_match and dp(i + 1, j + 1)

            memo[i, j] = ans
        return memo[i, j]

    return dp(0, 0)

