def can_reserve(seats, M):
    """
    Determines if there is a block of M consecutive available seats in a movie theater row.

    :param seats: List of integers where 1 indicates a reserved seat and 0 indicates an available seat.
    :param M: Integer representing the number of consecutive seats to reserve.
    :return: Boolean value, True if there is a block of M consecutive available seats, False otherwise.
    """
    consecutive_free = 0  # Counter for consecutive available seats

    for seat in seats:
        if seat == 0:
            consecutive_free += 1
            if consecutive_free == M:
                return True
        else:
            consecutive_free = 0  # Reset counter if a reserved seat is encountered

    return False

