def count_unique_pairs(nums: list[int], k: int) -> int:
    """
    Determines the number of unique pairs (i, j) such that 
    i < j and nums[i] + nums[j] equals the target sum k.
    """
    count = 0
    seen = {}  # Dictionary to store each number and its indices

    for i, num in enumerate(nums):
        if k - num in seen:
            count += len(seen[k - num])

        if num in seen:
            seen[num].append(i)
        else:
            seen[num] = [i]

    return count

