def matrix_determinant(matrix):
    """
    Function to calculate the determinant of a square matrix.

    :param matrix: 2D list representing the square matrix.

    :return:       Float value representing the determinant of the matrix.
    """
    def get_minor(matrix, i, j):
        # Return the minor of the matrix by removing row i and column j
        return [row[:j] + row[j+1:] for row in (matrix[:i] + matrix[i+1:])]

    def determinant(matrix):
        # Base case for 1x1 matrix
        if len(matrix) == 1:
            return matrix[0][0]

        # Base case for 2x2 matrix
        if len(matrix) == 2:
            return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]

        det = 0
        # Expand along the first row
        for c in range(len(matrix)):
            det += ((-1) ** c) * matrix[0][c] * determinant(get_minor(matrix, 0, c))
        return det

    return determinant(matrix)

