def simulate_stack_operations(operations):
    """
    Simulates a sequence of stack operations and collects results of Pop operations.

    Args:
    operations (List[Tuple[str, int]]): The list of stack operations to perform.

    Returns:
    List[int]: The results of the Pop operations.
    """
    stack = []
    result = []

    for operation in operations:
        if operation[0] == "Push":
            stack.append(operation[1])
        elif operation[0] == "Pop":
            if stack:
                result.append(stack.pop())
            else:
                result.append(-1)

    return result

