from typing import List


def duplicate_zeros(arr: List[int]) -> None:
    """
    Duplicates each zero in the list, modifying the list in place without extra space.
    """
    n = len(arr)
    zeros = arr.count(0)

    # Traverse the list backwards
    for i in range(n - 1, -1, -1):
        if i + zeros < n:
            arr[i + zeros] = arr[i]
        if arr[i] == 0:
            zeros -= 1
            if i + zeros < n:
                arr[i + zeros] = 0

def find_lcis_length(arr: list[int]) -> int:
    """
    Returns the length of the longest continuous increasing subsequence in the array.
    """
    if not arr:
        return 0

    max_len = 1
    current_len = 1

    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            current_len += 1
            max_len = max(max_len, current_len)
        else:
            current_len = 1

    return max_len

