def depth_sum(nested_list, depth=1):
    """
    Calculate the sum of integers in a nested list weighted by their depth.
    """
    total_sum = 0
    for element in nested_list:
        if isinstance(element, list):
            total_sum += depth_sum(element, depth + 1)
        else:
            total_sum += element * depth
    return total_sum

