def is_rotation_90(A: list[list[int]], B: list[list[int]]) -> bool:
    """
    Determines if matrix B is a 90-degree rotation of matrix A.
    """
    n = len(A)
    # Check if B is a 90-degree rotation of A
    for i in range(n):
        for j in range(n):
            if A[i][j] != B[j][n - 1 - i]:
                return False
    return True

