from typing import List


def can_form_contiguous_sequence(arr: List[int]) -> bool:
    """
    Determine if the given list can be rearranged to form a contiguous integer sequence.

    :param arr: List of integers.
    :return: True if the list can be rearranged to form a contiguous sequence, False otherwise.
    """
    if not arr:
        return True
    arr_set = set(arr)
    if len(arr_set) != len(arr):
        return False
    return max(arr_set) - min(arr_set) + 1 == len(arr_set)

