def find_and_replace(original: str, target: str, replacement: str) -> str:
    """
    Replaces all occurrences of the target substring in the original string
    with the replacement substring.
    """
    if not target:
        return original

    result = []
    i = 0
    target_len = len(target)
    while i <= len(original) - target_len:
        if original[i:i + target_len] == target:
            result.append(replacement)
            i += target_len
        else:
            result.append(original[i])
            i += 1

    result.append(original[i:])
    return "".join(result)

