def substring_frequency(text: str, length: int) -> dict[str, int]:
    """
    Finds all unique substrings of a given length within a string and counts their frequencies.

    Parameters:
    - text (str): The input string to analyze.
    - length (int): The length of substrings to find.

    Returns:
    - dict: A dictionary where keys are substrings and values are their frequencies.
    """
    if length <= 0 or len(text) < length:
        return {}

    freq_dict = {}
    for i in range(len(text) - length + 1):
        substring = text[i:i + length]
        if substring in freq_dict:
            freq_dict[substring] += 1
        else:
            freq_dict[substring] = 1

    return freq_dict

