def final_position(moves: list[str]) -> tuple[int, int]:
    """
    Computes the final position on the grid after executing all the moves.

    Arguments:
    moves -- a list of move strings ("up", "down", "left", "right")

    Returns:
    A tuple representing the final (x, y) coordinates on the grid.
    """
    x, y = 0, 0

    for move in moves:
        if move == "up":
            y += 1
        elif move == "down":
            y -= 1
        elif move == "left":
            x -= 1
        elif move == "right":
            x += 1

    return (x, y)

