def constant_behavior(input_value):
    """
    Returns specific built-in Python constants based on the type and value of input_value.
    """
    if isinstance(input_value, bool):
        return input_value
    elif input_value is None:
        return None
    elif input_value is NotImplemented:
        return NotImplemented
    elif input_value == "ellipsis":
        return Ellipsis
    elif input_value == "debug":
        return __debug__
    else:
        return "Unknown input"

