def longest_valid_parentheses(s: str) -> int:
    """
    Function to find the length of the longest valid (well-formed) parentheses substring.
    """
    stack = [-1]
    max_length = 0

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if len(stack) == 0:
                stack.append(i)
            else:
                max_length = max(max_length, i - stack[-1])

    return max_length

