def subarray_with_zero_sum(arr):
    """
    Determines if there is a subarray that sums up to zero and returns the start 
    and end indices of one such subarray. If no such subarray exists, returns None.
    """
    sum_indices_map = {}
    current_sum = 0

    for i, num in enumerate(arr):
        current_sum += num

        if current_sum == 0:
            return (0, i)

        if current_sum in sum_indices_map:
            return (sum_indices_map[current_sum] + 1, i)

        sum_indices_map[current_sum] = i

    return None

