def can_form_palindrome(s):
    """
    Checks if a given string can be rearranged to form a palindrome.
    """
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    # Correct condition: A string can form a palindrome if it has no more than one character with an odd count
    return odd_count <= 1

