def correct_parentheses(expression):
    """
    Identifies and corrects instances of misaligned parentheses in the expression.
    Returns the corrected string if possible; otherwise, returns 'Cannot be corrected'.
    """
    # Stack to keep track of parentheses positions
    stack = []

    for i, char in enumerate(expression):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()  # This pop matches the current ')' with a previous '('
            else:
                # If there's no matching '(' for this ')', this is an error
                return 'Cannot be corrected'

    # If the stack is not empty here, we had unmatched '('
    if stack:
        return 'Cannot be corrected'

    return expression

