def compress_string(s):
    """
    Compresses the string by counting consecutive occurrences of each character.
    Returns the compressed string only if it is shorter than the original string.
    """
    if not s:
        return s

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(s[i - 1])
            if count > 1:
                compressed.append(str(count))
            count = 1

    # Append the last set of characters
    compressed.append(s[-1])
    if count > 1:
        compressed.append(str(count))

    compressed_string = ''.join(compressed)

    return compressed_string if len(compressed_string) < len(s) else s

