def caesar_cipher(input_string, shift):
    """
    Applies a Caesar cipher transformation to the input string by shifting the letters
    by the given shift value while preserving the case. Non-alphabetical characters 
    remain unchanged.

    Args:
    - input_string (str): The string to be transformed.
    - shift (int): The number of positions to shift each letter.

    Returns:
    - str: The transformed string.
    """
    if not isinstance(input_string, str) or not isinstance(shift, int):
        raise ValueError("Invalid input: input_string must be a string and shift must be an integer")

    result = []
    for char in input_string:
        if char.isalpha():
            if char.islower():
                result.append(chr((ord(char) - ord('a') + shift) % 26 + ord('a')))
            elif char.isupper():
                result.append(chr((ord(char) - ord('A') + shift) % 26 + ord('A')))
        else:
            result.append(char)

    return ''.join(result)

