def longest_subarray_with_sum(nums, target):
    """
    Return the longest contiguous subarray that sums to the given target.
    If multiple subarrays have the same length, return the first one found.
    If no such subarray exists, return an empty list.
    """
    n = len(nums)
    longest_subarray = []
    subarray_indices = {}
    current_sum = 0

    for i in range(n):
        current_sum += nums[i]

        if current_sum == target:
            longest_subarray = nums[:i + 1]

        if (current_sum - target) in subarray_indices:
            start_index = subarray_indices[current_sum - target] + 1
            if len(nums[start_index:i + 1]) > len(longest_subarray):
                longest_subarray = nums[start_index:i + 1]

        if current_sum not in subarray_indices:
            subarray_indices[current_sum] = i

    return longest_subarray

