from collections import Counter


def all_elements_even_frequency(arr: list) -> bool:
    """
    Return True if every element in the list arr occurs an even number of times, otherwise return False.
    """
    element_counts = Counter(arr)
    for count in element_counts.values():
        if count % 2 != 0:
            return False
    return True

