def is_balanced(s):
    """
    Determines if the given string contains balanced parentheses.

    :param s: Input string
    :return: True if balanced, otherwise False
    """
    stack = []

    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack and stack[-1] == '(':
                stack.pop()
            else:
                return False

    return not stack

