def alternating_sequence(str1, str2, str3):
    """
    Returns a single string that alternates characters from the three input strings.
    """
    result = []
    max_len = max(len(str1), len(str2), len(str3))

    for i in range(max_len):
        if i < len(str1):
            result.append(str1[i])
        if i < len(str2):
            result.append(str2[i])
        if i < len(str3):
            result.append(str3[i])

    return "".join(result)

