from typing import List


def findClosestElements(arr: List[int], k: int, x: int) -> List[int]:
    """
    Returns the k closest integers to x in the array arr. The resulting list is sorted in ascending order.
    """
    left, right = 0, len(arr) - k

    while left < right:
        mid = (left + right) // 2
        if x - arr[mid] > arr[mid + k] - x:
            left = mid + 1
        else:
            right = mid

    return arr[left:left + k]

