def bubble_sort(arr):
    """
    Sorts a list of integers using the bubble sort algorithm.
    Returns the sorted list and the number of swaps needed to sort the list.
    If the list is empty, returns "The list is empty!".
    If the list contains non-integer elements, returns "Invalid input: list contains non-integer elements!".
    """
    if not arr:
        return "The list is empty!"

    if not all(isinstance(x, int) for x in arr):
        return "Invalid input: list contains non-integer elements!"

    n = len(arr)
    swaps = 0
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swaps += 1

    return arr, swaps

