def longest_distinct_subarray(arr):
    """
    Returns the length of the longest subarray containing only distinct elements.
    """
    max_len = 0
    start = 0
    seen = {}

    for end, value in enumerate(arr):
        if value in seen:
            start = max(start, seen[value] + 1)
        seen[value] = end
        max_len = max(max_len, end - start + 1)

    return max_len

