from typing import List


def find_elements_appearing_twice(arr: List[int]) -> List[int]:
    """
    Identifies and returns a list of all unique elements that appear exactly twice in the array.

    :param arr: List of integers (input array)
    :return: List of integers containing all unique elements that appear exactly twice
    """
    element_count = {}
    result = []

    # Step 1: Count the occurrences of each element
    for num in arr:
        if num in element_count:
            element_count[num] += 1
        else:
            element_count[num] = 1

    # Step 2: Collect elements that appear exactly twice
    for num, count in element_count.items():
        if count == 2:
            result.append(num)

    return result

