def lengthOfLIS(nums):
    """
    Returns the length of the longest strict increasing subsequence of nums.
    """
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # Initialize the dp array with 1s

    for i in range(1, n):
        for j in range(0, i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

