def subtract_sums_of_digits(s):
    """
    Given a string containing only digits, return the result of subtracting the sum
    of all odd digits from the sum of all even digits.
    """
    if not s:
        return 0

    sum_even = 0
    sum_odd = 0

    for char in s:
        digit = int(char)
        if digit % 2 == 0:
            sum_even += digit
        else:
            sum_odd += digit

    return sum_even - sum_odd

