def parse_string(s):
    """
    Parses the input string s and returns a dictionary based on the rules specified.
    """
    result = {}
    current_char = None

    for char in s:
        if char.isalpha():
            if char not in result:
                result[char] = set()
            current_char = char
        elif char.isdigit() and current_char is not None:
            result[current_char].add(int(char))

    # If there are no alphabets, return the default dictionary
    if not any(char.isalpha() for char in s):
        result = {'default': []}

    return result

