def has_common_integer(lists):
    """
    Checks if any two lists contain the same integer value.

    :param lists: List of lists of integers
    :return: True if any two lists contain the same integer, False otherwise
    """
    seen = set()
    for sublist in lists:
        for num in sublist:
            if num in seen:
                return True
            seen.add(num)
    return False

