def count_occurrences_recursive(text, pattern, index=0):
    """
    Returns the total number of occurrences of pattern in text, including overlapping, using recursion.
    """
    if not pattern or not text:
        return 0

    if len(text[index:]) < len(pattern):
        return 0

    found = 1 if text[index:index+len(pattern)] == pattern else 0

    return found + count_occurrences_recursive(text, pattern, index + 1)

