def basic_calculator(input_str):
    """
    A function that takes in a string in the format "number1 operator number2"
    and performs the corresponding arithmetic operation.

    Args:
    input_str (str): The input string containing the calculation.

    Returns:
    str: The result of the calculation or an error message.
    """
    try:
        if input_str.strip().lower() == "exit":
            return "exit"

        tokens = input_str.split()
        if len(tokens) != 3:
            return "Invalid input format. Use: number1 operator number2"

        num1, operator, num2 = tokens
        num1 = float(num1)
        num2 = float(num2)

        if operator == '+':
            return str(num1 + num2)
        elif operator == '-':
            return str(num1 - num2)
        elif operator == '*':
            return str(num1 * num2)
        elif operator == '/':
            if num2 == 0:
                return "Error: Division by zero"
            return str(num1 / num2)
        else:
            return "Invalid operator. Use: +, -, *, /"
    except ValueError:
        return "Error: Invalid number format"

