def find_max_value(numbers):
    """
    Returns the maximum value in a list of float numbers.

    Parameters:
    numbers (list): List of float numbers

    Returns:
    float: The maximum value in the list

    Raises:
    ValueError: If the list is empty or contains non-float elements
    """
    if not numbers:
        raise ValueError("The list is empty")

    for num in numbers:
        if not isinstance(num, (float, int)):
            raise ValueError("List contains non-float elements")

    return max(numbers)

