def rotate_list(nums, k, direction):
    """
    Rotates the list nums by k positions.

    If direction is True, rotates to the right.
    If direction is False, rotates to the left.
    """
    if not nums:
        return nums
    k %= len(nums)
    if direction:
        return nums[-k:] + nums[:-k]
    else:
        return nums[k:] + nums[:k]

