def longest_unique_char_fragment_length(s):
    """
    Returns the length of the longest continuous fragment of a unique character in the given string.

    Parameters:
    s (str): The input string to evaluate.

    Returns:
    int: The length of the longest fragment.
    """
    if not s:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1

    return max(max_length, current_length)

