def count_characters(message):
    """
    Returns the number of characters in the message,
    excluding any leading or trailing whitespace.
    """
    if message is None or not isinstance(message, str):
        raise ValueError("Invalid input, message must be a string")

    trimmed_message = message.strip()
    return len(trimmed_message)

