def calculate_custom_sum(nums):
    """
    This function calculates the custom sum of a list of integers. 
    If a number is a multiple of 5, it subtracts its double from the sum instead of adding it.
    """
    total = 0
    for num in nums:
        if num % 5 == 0:
            total -= 2 * num
        else:
            total += num
    return total

