def check_palindromes(lst):
    """
    Checks whether the list is empty or not. If the list is not empty, 
    checks whether every string in the list is a palindrome.

    Returns True if the list is empty, or if all strings in the list are palindromes.
    Returns False if any string in the list is not a palindrome.
    """
    if not lst:
        return True

    for s in lst:
        if s != s[::-1]:
            return False

    return True

