def calculator(a, b, operator):
    """
    Simulates a calculator for basic arithmetic operations (+, -, *, /).
    Returns the result of the operation or a message if the operation is invalid.
    """
    try:
        a = float(a)
        b = float(b)
    except ValueError:
        return "Invalid input: numbers must be valid."

    if operator == '+':
        return a + b
    elif operator == '-':
        return a - b
    elif operator == '*':
        return a * b
    elif operator == '/':
        if b == 0:
            return "Invalid operation: division by zero."
        return a / b
    elif operator.lower() == 'q':
        return "Quit"
    else:
        return "Invalid input: operator must be one of (+, -, *, /)."

