def check_variable_type(var):
    """
    Returns the type of the variable var.
    Possible types: 'integer', 'float', 'string', 'tuple', 'nested_tuple', 'list', 'none', 'unknown'
    """
    if isinstance(var, int):
        return 'integer'
    elif isinstance(var, float):
        return 'float'
    elif isinstance(var, str):
        return 'string'
    elif isinstance(var, tuple):
        def is_nested_tuple(t):
            return any(isinstance(ele, tuple) for ele in t)
        return 'nested_tuple' if is_nested_tuple(var) else 'tuple'
    elif isinstance(var, list):
        return 'list'
    elif var is None:
        return 'none'
    else:
        return 'unknown'

