def word_frequency(sentences):
    """
    Counts the frequency of each word in a given list of sentences.

    Parameters:
    sentences (list of str): List of sentences to count word frequency in.

    Returns:
    dict: A dictionary where the keys are words and the values are their respective frequencies.
    """

    def custom_split(sentence):
        """
        Splits a sentence into words without using built-in split function.
        """
        words = []
        word = ""
        for char in sentence:
            if char.isalnum():
                word += char
            else:
                if word:
                    words.append(word)
                    word = ""
        if word:
            words.append(word)
        return words

    word_freq = {}
    for sentence in sentences:
        words = custom_split(sentence)
        for word in words:
            if word in word_freq:
                word_freq[word] += 1
            else:
                word_freq[word] = 1

    return word_freq

