def merge_lists_no_duplicates(list1, list2):
    """
    Merges two lists ensuring no duplicate elements in the final list.
    Handles unhashable types like lists by converting them to tuples for comparison.
    """
    def make_hashable(element):
        if isinstance(element, list):
            return tuple(make_hashable(sub_element) for sub_element in element)
        return element

    unique_elements = set()
    merged_list = []

    for element in list1 + list2:
        hashable_element = make_hashable(element)
        if hashable_element not in unique_elements:
            unique_elements.add(hashable_element)
            merged_list.append(element)

    return merged_list

