def max_length_subarray(arr):
    """
    Returns the maximum length of an increasing subarray where consecutive 
    elements have a difference of 1, 0, or -1.
    """
    if not arr:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(arr)):
        if abs(arr[i] - arr[i - 1]) <= 1:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

