def create_fibonacci_sequence(n):
    """
    Generates a list of Fibonacci numbers up to a given number n (inclusive if n is a Fibonacci number).
    """
    if n < 0:
        return []

    fibonacci_sequence = [0, 1]
    while True:
        next_fib = fibonacci_sequence[-1] + fibonacci_sequence[-2]
        if next_fib > n:
            break
        fibonacci_sequence.append(next_fib)

    # For the case when n is 0
    if n == 0:
        return [0]

    return fibonacci_sequence

