def replace_zeros(arr):
    """
    Replaces each zero in the array with the nearest non-zero value to its left.
    If there is no non-zero value to the left, the zero remains unchanged.
    """
    if not arr:
        return arr

    last_nonzero = None
    for i in range(len(arr)):
        if arr[i] != 0:
            last_nonzero = arr[i]
        elif last_nonzero is not None:
            arr[i] = last_nonzero

    return arr

