def find_median(input_string):
    """
    Returns the median of a list of numbers provided in a space-separated string.
    """
    try:
        numbers = list(map(float, input_string.split()))
    except ValueError:
        return "Input string must contain only numbers"

    if not numbers:
        return "Input string must not be empty"

    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)
    mid = n // 2

    if n % 2 == 0:
        median = (sorted_numbers[mid - 1] + sorted_numbers[mid]) / 2.0
    else:
        median = sorted_numbers[mid]

    return median

