def longest_palindromic_substring_brute_force(s):
    """
    Returns the length of the longest palindromic substring in the given string s using a brute force approach.
    """
    n = len(s)
    max_length = 1
    for i in range(n):
        for j in range(i, n):
            subs = s[i:j+1]
            if subs == subs[::-1]:
                max_length = max(max_length, j-i+1)
    return max_length

