def evaluate_postfix(expression):
    """
    Evaluates a postfix (Reverse Polish Notation) mathematical expression using a stack.

    Parameters:
        expression (str): The postfix expression to evaluate.

    Returns:
        int/float: The result of the evaluated expression.
    """
    stack = []
    operators = set(['+', '-', '*', '/'])

    tokens = expression.split()

    for token in tokens:
        if token not in operators:
            stack.append(float(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)

    return stack[0]

