def find_first_increasing_pair(arr):
    """
    Finds the index of the first pair of consecutive elements where the second element is greater than the first.

    :param arr: List of integers.
    :return: Index of the first element of the first increasing pair or -1 if no such pair exists.
    """
    for i in range(len(arr) - 1):
        if arr[i] < arr[i + 1]:
            return i
    return -1

