def longest_unique_substring(s):
    """
    Given an input string s, returns the longest substring without repeating characters.
    """
    char_map = {}
    left = 0
    longest = 0

    for right, char in enumerate(s):
        if char in char_map:
            left = max(left, char_map[char] + 1)

        char_map[char] = right
        longest = max(longest, right - left + 1)

    return longest

