import string


def word_count(strings):
    """
    Returns a dictionary with each word from the list of strings as a key and the value being the total count 
    of that word across all strings. The function ignores punctuation and is case-insensitive.
    """

    # Creating a translation table to remove punctuation and translate everything to lower case
    translator = str.maketrans('', '', string.punctuation)
    word_counts = {}

    for s in strings:
        # Removing punctuation, converting to lower case, and splitting into words
        words = s.translate(translator).lower().split()
        for word in words:
            if word in word_counts:
                word_counts[word] += 1
            else:
                word_counts[word] = 1

    return word_counts

