def count_words(strings):
    """
    Processes a list of strings and returns a dictionary where keys are
    unique words and values are counts of each word's occurrence.

    :param strings: List of strings to be processed.
    :return: Dictionary with words as keys and their counts as values.
    """
    word_count = {}
    for string in strings:
        words = string.split()  # Split each string by spaces to get words
        for word in words:
            if word in word_count:
                word_count[word] += 1
            else:
                word_count[word] = 1
    return word_count

