def greet(name, day):
    """
    Returns a greeting message based on the day of the week.
    """
    if day == "Monday":
        return f"Happy Monday, {name}!"
    elif day == "Tuesday":
        return f"Tuesday already, {name}?"
    elif day == "Wednesday":
        return f"Halfway through the week, {name}!"
    elif day == "Thursday":
        return f"One more day till Friday, {name}!"
    elif day == "Friday":
        return f"TGIF, {name}!"
    elif day == "Saturday":
        return f"Have a great weekend, {name}!"
    elif day == "Sunday":
        return f"Enjoy your Sunday, {name}!"
    else:
        return f"Hello, {name}! Have a nice day!"

