def contains_substring(main_str, sub_str):
    """
    Recursively checks if the main_str contains the sub_str, ignoring leading and trailing whitespace.

    :param main_str: The string to search within.
    :param sub_str: The substring to search for.
    :return: True if sub_str is found within main_str, otherwise False.
    """
    main_str = main_str.strip()
    sub_str = sub_str.strip()

    if not sub_str:
        return True

    if not main_str:
        return False

    if main_str[:len(sub_str)] == sub_str:
        return True

    return contains_substring(main_str[1:], sub_str)

