def is_rotation(strings):
    """
    Check if any string in the list is a rotation of another string in the same list.

    Params:
        strings (list of str): List of strings to check for rotations.

    Returns:
        bool: True if a rotation is found, False otherwise.
    """
    for i in range(len(strings)):
        for j in range(len(strings)):
            if i != j and len(strings[i]) == len(strings[j]):
                if strings[j] in (strings[i] + strings[i]):
                    return True
    return False

