from typing import List


def longest_increasing_subsequence(nums: List[int]) -> int:
    """
    Given an integer array nums, return the length of the longest strictly increasing subsequence.

    A subsequence is a sequence that can be derived from an array by deleting some or no elements without changing
    the order of the remaining elements. For example, [3,6,2,7] is a subsequence of the array [0,3,1,6,2,2,7].

    Example:

    longest_increasing_subsequence([10,9,2,5,3,7,101,18]) == 4
    longest_increasing_subsequence([0,1,0,3,2,3]) == 4
    longest_increasing_subsequence([7,7,7,7,7,7,7]) == 1
    """
    n = len(nums)
    if n == 0:
        return 0

    dp = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

