def solve(nums):
    """
    Determines if a given list contains any duplicate numbers.

    :param nums: List of integers
    :return: True if there are duplicates, False otherwise
    """
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] == nums[j]:
                return True

    return False

