def perform_operations(int_list, operation):
    """
    Perform an arithmetic operation on a filtered list of integers.

    Parameters:
    int_list (list): List containing elements that may include non-integers.
    operation (str): The operation to perform: 'add', 'subtract', 'multiply', or 'divide'.

    Returns:
    result (float or int): The result of the arithmetic operation.
    """
    # Filter out non-integer values
    filtered_list = [item for item in int_list if isinstance(item, int)]

    if not filtered_list:
        raise ValueError("The list must contain at least one integer.")

    if operation == 'add':
        result = sum(filtered_list)

    elif operation == 'subtract':
        result = filtered_list[0]
        for num in filtered_list[1:]:
            result -= num

    elif operation == 'multiply':
        result = 1
        for num in filtered_list:
            result *= num

    elif operation == 'divide':
        result = filtered_list[0]
        for num in filtered_list[1:]:
            if num == 0:
                raise ValueError("Division by zero is not allowed.")
            result /= num

    else:
        raise ValueError("Invalid operation specified.")

    return result

