def is_subsequence(s, t):
    """
    Checks whether the string `s` is a subsequence of string `t`.
    """
    t_index = 0
    s_index = 0

    while t_index < len(t) and s_index < len(s):
        if t[t_index] == s[s_index]:
            s_index += 1
        t_index += 1

    return s_index == len(s)

