def count_vowels_consonants(user_string):
    """
    Counts the number of vowels and consonants in the given string.

    :param user_string: The string to process
    :return: Tuple containing the count of vowels and consonants respectively
    """
    vowels = "aeiouAEIOU"
    vowel_count = 0
    consonant_count = 0

    for char in user_string:
        if char in vowels:
            vowel_count += 1
        elif char.isalpha():
            consonant_count += 1

    return (vowel_count, consonant_count)

