def compress_ranges(numbers):
    """
    Compress a sorted list of integers into range-based representation.

    Parameters:
    numbers (list): A sorted list of integers.

    Returns:
    list: A list of strings with compressed range-based representation.
    """
    if not numbers:
        return []

    compressed = []
    start = numbers[0]
    end = numbers[0]

    for i in range(1, len(numbers)):
        if numbers[i] == end + 1:
            end = numbers[i]
        else:
            if end - start >= 2:
                compressed.append(f"{start}-{end}")
            else:
                compressed.extend(map(str, range(start, end + 1)))
            start = numbers[i]
            end = numbers[i]

    if end - start >= 2:
        compressed.append(f"{start}-{end}")
    else:
        compressed.extend(map(str, range(start, end + 1)))

    return compressed

