import re


def evaluate_expression(expression):
    """
    Evaluates an arithmetic expression containing positive integers and the operators 
    '+', '-', '*', and '/'. Handles an empty string by returning a message. 

    Parameters:
        expression (str): The arithmetic expression to evaluate.

    Returns:
        float: The result of the expression.
        str: An error message if the input is invalid.
    """
    if not expression:
        return "Error: Empty expression"

    # Check for invalid characters
    if not re.match(r'^[\d\+\-\*/\s]+$', expression):
        return "Error: Invalid characters in expression"

    try:
        # Tokenize the expression
        tokens = re.findall(r'\d+|[\+\-\*/]', expression)

        # Convert numbers to integers
        for i in range(len(tokens)):
            if tokens[i].isdigit():
                tokens[i] = int(tokens[i])

        def apply_operator(operators, values):
            operator = operators.pop()
            right = values.pop()
            left = values.pop()
            if operator == '+':
                values.append(left + right)
            elif operator == '-':
                values.append(left - right)
            elif operator == '*':
                values.append(left * right)
            elif operator == '/':
                values.append(left / right)

        # Operator precedence
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        operators = []
        values = []

        i = 0
        while i < len(tokens):
            if isinstance(tokens[i], int):
                values.append(tokens[i])
                i += 1
            else:
                while (operators and 
                       precedence[operators[-1]] >= precedence[tokens[i]]):
                    apply_operator(operators, values)
                operators.append(tokens[i])
                i += 1

        while operators:
            apply_operator(operators, values)

        return values[0]

    except Exception as e:
        return "Error: Invalid expression"

def evaluate_expression(expression: str) -> int:
    """
    Evaluate the given mathematical expression string and return the resulting integer.
    The division should result in integer division.
    """
    def compute(operators, operands):
        right = operands.pop()
        left = operands.pop()
        operator = operators.pop()

        if operator == '+':
            operands.append(left + right)
        elif operator == '-':
            operands.append(left - right)
        elif operator == '*':
            operands.append(left * right)
        elif operator == '/':
            operands.append(int(left / right))

    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    operators = []
    operands = []
    i = 0

    while i < len(expression):
        if expression[i].isdigit():
            num = 0
            while i < len(expression) and expression[i].isdigit():
                num = num * 10 + int(expression[i])
                i += 1
            operands.append(num)
            i -= 1
        elif expression[i] in precedence:
            while (operators and operators[-1] in precedence and
                   precedence[operators[-1]] >= precedence[expression[i]]):
                compute(operators, operands)
            operators.append(expression[i])
        elif expression[i] == '(':
            operators.append(expression[i])
        elif expression[i] == ')':
            while operators[-1] != '(':
                compute(operators, operands)
            operators.pop()
        i += 1

    while operators:
        compute(operators, operands)

    return operands[0]

