def convert_temperature(value, from_unit, to_unit):
    """
    Converts temperature between Celsius, Fahrenheit, and Kelvin.

    Parameters:
    value (float): Numeric value of the temperature to be converted.
    from_unit (str): Unit of the input temperature ('C', 'F', or 'K').
    to_unit (str): Unit to convert the input temperature to ('C', 'F', or 'K').

    Returns:
    float: Converted temperature value.
    """
    if from_unit not in ['C', 'F', 'K'] or to_unit not in ['C', 'F', 'K']:
        raise ValueError("Invalid temperature units.")

    if from_unit == to_unit:
        return value

    # Convert from `from_unit` to Celsius first
    if from_unit == 'C':
        temp_in_c = value
    elif from_unit == 'F':
        temp_in_c = (value - 32) * 5/9
    elif from_unit == 'K':
        temp_in_c = value - 273.15

    # Convert from Celsius to `to_unit`
    if to_unit == 'C':
        return temp_in_c
    elif to_unit == 'F':
        return temp_in_c * 9/5 + 32
    elif to_unit == 'K':
        return temp_in_c + 273.15

