def replace_vowels(s):
    """
    Returns a new string after replacing all the vowels in the original string
    with the next closest consonant in the alphabet.
    """
    vowels = "aeiouAEIOU"
    next_consonants = {
        'a': 'b', 'e': 'f', 'i': 'j', 'o': 'p', 'u': 'v',
        'A': 'B', 'E': 'F', 'I': 'J', 'O': 'P', 'U': 'V'
    }

    result = []
    for char in s:
        if char in vowels:
            result.append(next_consonants[char])
        else:
            result.append(char)

    return ''.join(result)

