def roman_to_integer(roman: str) -> int:
    """
    Converts a Roman numeral to an integer.

    Returns -1 for invalid input.
    """
    roman_dict = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    valid_chars = set(roman_dict.keys())

    # Checking input validity
    if not (1 <= len(roman) <= 15):
        return -1
    if not all(char in valid_chars for char in roman):
        return -1

    total = 0
    previous_value = 0
    for char in reversed(roman):
        current_value = roman_dict[char]
        if current_value < previous_value:
            total -= current_value
        else:
            total += current_value
        previous_value = current_value

    return total

from typing import List, Dict


def classify_weights(weights: List[float]) -> Dict[str, int]:
    """
    Classifies the given weights into 'Light', 'Medium', 'Heavy', and 'Very Heavy' categories.
    """
    categories = {
        'Light': 0,
        'Medium': 0,
        'Heavy': 0,
        'Very Heavy': 0
    }

    for weight in weights:
        if weight < 1:
            categories['Light'] += 1
        elif 1 <= weight < 10:
            categories['Medium'] += 1
        elif 10 <= weight < 25:
            categories['Heavy'] += 1
        else:
            categories['Very Heavy'] += 1

    return categories

