def closest_greater_neighbor(nums):
    """
    Returns a list where each element is the closest greater neighbor of the corresponding element in `nums` list.
    If no greater neighbor is found, the output is -1.
    """
    n = len(nums)
    if n == 0:
        return []

    result = [-1] * n
    stack = []  # this will store indices

    # Scan from left to right to find the closest greater on the right
    for i in range(n):
        while stack and nums[stack[-1]] < nums[i]:
            index = stack.pop()
            if result[index] == -1 or (i - index) < (index - result[index]):
                result[index] = i
        stack.append(i)

    stack.clear()

    # Scan from right to left to find the closest greater on the left
    for i in range(n-1, -1, -1):
        while stack and nums[stack[-1]] < nums[i]:
            index = stack.pop()
            if result[index] == -1 or (index - i) <= (result[index] - index):
                result[index] = i
        stack.append(i)

    return [nums[idx] if idx != -1 else -1 for idx in result]

