def find_kth_min_max(lst, k, comparator):
    """
    Returns the kth minimum and maximum element in a list using a custom comparator function.

    :param lst: List of elements
    :param k: The k-th index for finding minimum and maximum (1-based index)
    :param comparator: A function that defines comparison logic
    :return: A tuple containing kth minimum and kth maximum elements
    """
    def partition(arr, low, high, comp):
        i = low - 1
        pivot = arr[high]
        for j in range(low, high):
            if comp(arr[j], pivot):
                i = i + 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1

    def quickselect(arr, low, high, k, comp):
        if low == high:
            return arr[low]
        pivot_index = partition(arr, low, high, comp)
        if k == pivot_index:
            return arr[k]
        elif k < pivot_index:
            return quickselect(arr, low, pivot_index - 1, k, comp)
        else:
            return quickselect(arr, pivot_index + 1, high, k, comp)

    if not lst or k < 1 or k > len(lst):
        return None, None

    lst_min = lst[:]
    lst_max = lst[:]

    kth_min = quickselect(lst_min, 0, len(lst_min) - 1, k - 1, comparator)
    reverse_comparator = lambda x, y: comparator(y, x)
    kth_max = quickselect(lst_max, 0, len(lst_max) - 1, k - 1, reverse_comparator)

    return kth_min, kth_max

