def compare_lists(list1, list2):
    """
    Compares two lists and returns the differences.
    """
    differences = {
        "only_in_list1": [],
        "only_in_list2": [],
        "in_both_lists": []
    }

    list1_items = {}
    list2_items = {}

    for item in list1:
        if item in list1_items:
            list1_items[item] += 1
        else:
            list1_items[item] = 1

    for item in list2:
        if item in list2_items:
            list2_items[item] += 1
        else:
            list2_items[item] = 1

    for item in list1_items:
        if item in list2_items:
            min_count = min(list1_items[item], list2_items[item])
            for _ in range(min_count):
                differences["in_both_lists"].append(item)
            if list1_items[item] > list2_items[item]:
                for _ in range(list1_items[item] - list2_items[item]):
                    differences["only_in_list1"].append(item)
        else:
            for _ in range(list1_items[item]):
                differences["only_in_list1"].append(item)

    for item in list2_items:
        if item not in list1_items:
            for _ in range(list2_items[item]):
                differences["only_in_list2"].append(item)

    return differences

