def validate_phone_number(country_code: str, phone_number: str) -> bool:
    """
    Validates a phone number based on country-specific rules.

    Parameters:
        country_code (str): The country code (e.g., 'US', 'UK', 'IN').
        phone_number (str): The phone number to validate.

    Returns:
        bool: True if the phone number is valid, False otherwise.
    """
    if not isinstance(country_code, str):
        raise TypeError(f"Expected string as country code, found {type(country_code)}")
    if not isinstance(phone_number, str):
        raise TypeError(f"Expected string as phone number, found {type(phone_number)}")

    country_code = country_code.upper()

    if country_code == 'US':
        return phone_number.isdigit() and len(phone_number) == 10
    elif country_code == 'UK':
        return phone_number.isdigit() and len(phone_number) == 11 and phone_number[0] == '0'
    elif country_code == 'IN':
        return phone_number.isdigit() and len(phone_number) == 10 and phone_number[0] in '9876'
    else:
        return False

