def lambda_handler(event, context):
    """
    AWS Lambda handler function
    """
    def greet(name):
        if name:
            return f"Hello, {name}!"
        else:
            return "Hello, World!"

    def calculate_factorial(n):
        result = 1
        for i in range(1, n + 1):
            result *= i
        return result

    # Example of loop
    names = ["Alice", "Bob", None]
    greetings = [greet(name) for name in names]

    # Example of function call and conditional
    number = event.get('number', 5)
    factorial = calculate_factorial(number)

    return {
        "statusCode": 200,
        "greetings": greetings,
        "factorial": factorial
    }

