def categorize_animals(animals):
    """
    Categorize the given list of animals into Mammals, Reptiles, and Birds.

    Parameters:
        animals (list): A list of animal names (str).

    Returns:
        dict: A dictionary with keys 'Mammals', 'Reptiles', 'Birds', and values as lists of corresponding animals.
    """
    categories = {
        'Mammals': ['elephant', 'giraffe', 'tiger', 'zebra'],
        'Reptiles': ['alligator'],
        'Birds': ['penguin']
    }

    categorized = {'Mammals': [], 'Reptiles': [], 'Birds': []}

    for animal in animals:
        for category, animals_list in categories.items():
            if animal in animals_list:
                categorized[category].append(animal)
                break

    return categorized

