def min_path_sum(grid):
    """
    Finds the minimum cost path from the top-left corner to the bottom-right corner of the grid.
    You can only move either down or right at any point in time.

    :param grid: List[List[int]] - 2D list of integers representing the grid
    :return: int - minimum cost to reach the bottom-right corner
    """
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # Initialize a dp table with the same dimensions as the grid
    dp = [[0] * cols for _ in range(rows)]

    # Fill the dp table
    for r in range(rows):
        for c in range(cols):
            if r == 0 and c == 0:
                dp[r][c] = grid[r][c]
            elif r == 0:
                dp[r][c] = dp[r][c-1] + grid[r][c]
            elif c == 0:
                dp[r][c] = dp[r-1][c] + grid[r][c]
            else:
                dp[r][c] = min(dp[r-1][c], dp[r][c-1]) + grid[r][c]

    return dp[-1][-1]

