def merge_sort(arr: list) -> list:
    """
    Sorts a list of integers in ascending order using the merge sort algorithm.

    Parameters:
    arr (list): The list of integers to be sorted.

    Returns:
    list: A new list containing the sorted integers.

    Raises:
    TypeError: If arr is not a list or if any element within arr is not an integer.
    """
    if not isinstance(arr, list):
        raise TypeError("Input should be a list")
    for elem in arr:
        if not isinstance(elem, int):
            raise TypeError("All elements in the list should be integers")

    if len(arr) <= 1:
        return arr

    def merge(left, right):
        merged = []
        i = j = 0

        while i < len(left) and j < len(right):
            if left[i] < right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1

        while i < len(left):
            merged.append(left[i])
            i += 1

        while j < len(right):
            merged.append(right[j])
            j += 1

        return merged

    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])

    return merge(left, right)

