def roman_to_int(s):
    """
    Converts a string representing a Roman numeral to its integer value.
    """
    roman_values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 
        'C': 100, 'D': 500, 'M': 1000
    }
    total = 0
    prev_value = 0

    for char in reversed(s):
        value = roman_values[char]
        if value >= prev_value:
            total += value
        else:
            total -= value
        prev_value = value

    return total

def find_local_minima_indices(arr):
    """
    Returns a list of indices of all local minimum elements in the list.
    """
    local_minima_indices = []
    length = len(arr)

    if length == 0:
        return local_minima_indices

    if length == 1 or (length > 1 and arr[0] <= arr[1]):
        local_minima_indices.append(0)

    for i in range(1, length - 1):
        if arr[i] <= arr[i - 1] and arr[i] <= arr[i + 1]:
            local_minima_indices.append(i)

    if length > 1 and arr[-1] <= arr[-2]:
        local_minima_indices.append(length - 1)

    return local_minima_indices

