def binomial_coefficient(n, k):
    """
    Calculates the binomial coefficient "n choose k" for given non-negative integers n and k.
    The coefficient is calculated as n! / (k! * (n - k)!)

    Parameters:
    - n: the total number of items.
    - k: the number of items to choose.

    Returns:
    int: the binomial coefficient.
    """
    try:
        # Check if inputs are integers
        if not isinstance(n, int) or not isinstance(k, int):
            raise TypeError("Both n and k must be integers")

        # Check if inputs are non-negative
        if n < 0 or k < 0:
            raise ValueError("Both n and k must be non-negative integers")

        # Check if k is not greater than n
        if k > n:
            raise ValueError("k cannot be greater than n")

        # Calculate binomial coefficient using an iterative approach
        if k == 0 or k == n:
            return 1
        k = min(k, n - k)  # Use symmetry property
        coefficient = 1
        for i in range(k):
            coefficient = coefficient * (n - i) // (i + 1)
        return coefficient
    except Exception as e:
        return str(e)

def evaluate_expression(expression):
    """
    Evaluates a mathematical expression containing non-negative integers, +, -, *, / operators, and parentheses.
    """
    def operate(a, b, op):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return int(a / b)

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_ops(values, ops):
        right = values.pop()
        left = values.pop()
        op = ops.pop()
        values.append(operate(left, right, op))

    values, ops = [], []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue
        if expression[i] == '(':
            ops.append('(')
        elif expression[i] == ')':
            while ops and ops[-1] != '(':
                apply_ops(values, ops)
            ops.pop()
        elif expression[i].isdigit():
            num = 0
            while i < len(expression) and expression[i].isdigit():
                num = num * 10 + int(expression[i])
                i += 1
            values.append(num)
            i -= 1
        else:
            while (ops and precedence(ops[-1]) >= precedence(expression[i])):
                apply_ops(values, ops)
            ops.append(expression[i])
        i += 1

    while ops:
        apply_ops(values, ops)

    return values[0]

