def rock_paper_scissors(user_choice, computer_choice):
    """
    Determines the outcome of a rock, paper, scissors game.

    :param user_choice: str - User's choice of 'rock', 'paper', or 'scissors'
    :param computer_choice: str - Computer's choice of 'rock', 'paper', or 'scissors'
    :return: str - Outcome of the game: 'tie', 'win', or 'lose'
    """
    if user_choice not in ["rock", "paper", "scissors"]:
        raise ValueError("Invalid user choice")

    if computer_choice not in ["rock", "paper", "scissors"]:
        raise ValueError("Invalid computer choice")

    if user_choice == computer_choice:
        return 'tie'
    elif user_choice == "rock":
        return 'win' if computer_choice == "scissors" else 'lose'
    elif user_choice == "paper":
        return 'win' if computer_choice == "rock" else 'lose'
    elif user_choice == "scissors":
        return 'win' if computer_choice == "paper" else 'lose'

def convert_to_rpn(expression: str) -> str:
    """
    Converts an infix arithmetic expression to its equivalent Reverse Polish Notation (RPN).
    """
    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    output = []
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token.isdigit():
            output.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()
        else:  # token is an operator
            while stack and precedence(stack[-1]) >= precedence(token):
                output.append(stack.pop())
            stack.append(token)

    while stack:
        output.append(stack.pop())

    return " ".join(output)

