def fibonacci(n, memo=None):
    """
    Returns the first n numbers of the Fibonacci sequence using memoization.
    """
    if memo is None:
        memo = {}

    if n in memo:
        return memo[n]
    if n <= 0:
        return []
    if n == 1:
        return [0]
    if n == 2:
        return [0, 1]

    # Calculate the sequence up to n-1 if not already in memo
    if n-1 not in memo:
        memo[n-1] = fibonacci(n-1, memo)
    # Calculate the n-th value
    nth_value = memo[n-1][-1] + memo[n-1][-2]

    # Extend the memoized list with the new value
    memo[n] = memo[n-1] + [nth_value]

    return memo[n]

