def replace_nth_occurrence(text, word, replacement, n, case_sensitive=True):
    """
    Replaces every nth occurrence of a specific word with a given replacement term.

    Parameters:
    - text (str): The original text string.
    - word (str): The word to be replaced.
    - replacement (str): The term to replace the nth word with.
    - n (int): The occurrence interval for replacement.
    - case_sensitive (bool): Case sensitivity flag for word matching.

    Returns:
    - str: The modified text with nth occurrences replaced.
    """
    if n <= 0:
        raise ValueError("n must be greater than 0.")

    if not case_sensitive:
        word_lower = word.lower()
        words = text.split()
        occurrence_count = 0

        for i in range(len(words)):
            if words[i].lower() == word_lower:
                occurrence_count += 1
                if occurrence_count % n == 0:
                    words[i] = replacement

    else:
        words = text.split()
        occurrence_count = 0

        for i in range(len(words)):
            if words[i] == word:
                occurrence_count += 1
                if occurrence_count % n == 0:
                    words[i] = replacement

    return ' '.join(words)

def count_words(text):
    """
    Takes a string as input and returns a dictionary where the keys are 
    the unique words in the string and the values are the number of times 
    each word appears in the string. Words are counted in a case-insensitive 
    manner and common stop words are ignored.
    """
    stop_words = {"the", "and", "is", "in", "it", "of", "to", "a", "an"}
    words = text.lower().split()
    word_count = {}

    for word in words:
        word = word.strip(",.!?;:")
        if word and word not in stop_words:
            word_count[word] = word_count.get(word, 0) + 1

    return word_count

