def search_matrix(matrix: list[list[int]], target: int) -> tuple:
    """ 
    Searches for a target value in a row-wise and column-wise sorted matrix.
    """
    if not matrix or not matrix[0]:
        return -1, -1

    rows = len(matrix)
    cols = len(matrix[0])

    # Start from the top-right corner
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        if matrix[row][col] == target:
            return row, col
        elif matrix[row][col] < target:
            row += 1
        else:
            col -= 1

    return -1, -1

def max_rectangle_area(towers: list) -> int:
    """
    Returns the maximum rectangle area that can be formed in the skyline using consecutive towers.
    """

    def largestRectangleArea(heights):
        stack = []
        max_area = 0
        index = 0

        while index < len(heights):
            if not stack or heights[index] >= heights[stack[-1]]:
                stack.append(index)
                index += 1
            else:
                top_of_stack = stack.pop()
                area = (heights[top_of_stack] * ((index - stack[-1] - 1) if stack else index))
                max_area = max(max_area, area)

        while stack:
            top_of_stack = stack.pop()
            area = (heights[top_of_stack] * ((index - stack[-1] - 1) if stack else index))
            max_area = max(max_area, area)

        return max_area

    return largestRectangleArea(towers)

