def robot_path(moves: str, battery: int) -> (int, int, int):
    """
    Simulates the path of a robot given a sequence of movements and an initial battery level.

    Parameters:
    moves (str): A string of characters in 'F', 'B', 'L', 'R' representing the movements.
    battery (int): The initial battery level of the robot.

    Returns:
    (int, int, int): A tuple containing the final x and y coordinates and the remaining battery level.
    """
    x, y = 0, 0  # Starting position is (0,0)

    for move in moves:
        if battery <= 0:
            break

        if move == 'F':
            y += 1
        elif move == 'B':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

        battery -= 1

    return x, y, battery

def compute_average(numbers, weights=None):
    """
    Computes the average of a list of positive integers.
    Optionally calculates the weighted average if weights are provided.

    :param numbers: List of positive integers
    :param weights: Optional list of weights as floats or integers
    :return: Average or weighted average as a floating-point number
    """
    if not all(isinstance(n, int) and n > 0 for n in numbers):
        return "Error: List must contain only positive integers."

    if weights is not None:
        if len(weights) != len(numbers):
            return "Error: The number of weights must match the number of numbers."
        if not all(isinstance(w, (int, float)) for w in weights):
            return "Error: All weights must be integers or floats."
        if not abs(sum(weights) - 1.0) < 1e-6:
            return "Error: Weights must sum up to 1."

        weighted_sum = sum(n * w for n, w in zip(numbers, weights))
        return float(weighted_sum)

    return float(sum(numbers) / len(numbers))

def calculate_median(numbers):
    """
    Returns the median of a given list of numbers.
    """
    # Helper function to sort the list
    def sort_list(lst):
        for i in range(len(lst) - 1):
            for j in range(len(lst) - i - 1):
                if lst[j] > lst[j + 1]:
                    lst[j], lst[j + 1] = lst[j + 1], lst[j]
        return lst

    # Helper function to determine the length of the list
    def list_length(lst):
        count = 0
        for _ in lst:
            count += 1
        return count

    # Sorting the list
    sorted_numbers = sort_list(numbers[:])

    # Getting the length of the list
    n = list_length(sorted_numbers)

    # Checking if the length is odd or even and calculating the median accordingly
    if n % 2 == 1:
        return sorted_numbers[n // 2]
    else:
        mid1 = n // 2 - 1
        mid2 = n // 2
        return (sorted_numbers[mid1] + sorted_numbers[mid2]) / 2

