def pig_latin(sentence):
    """
    Converts a sentence into Pig Latin.
    """
    def convert_word(word):
        first_vowel = -1
        vowels = "aeiouAEIOU"
        for i, char in enumerate(word):
            if char in vowels:
                first_vowel = i
                break
        if first_vowel == -1:
            return word + "ay"
        elif first_vowel == 0:
            return word + "way"
        else:
            return word[first_vowel:] + word[:first_vowel] + "ay"

    words = sentence.split()
    pig_latin_words = [convert_word(word) for word in words]
    return ' '.join(pig_latin_words)

