def categorize_ball(ball_number):
    """
    Returns the category of the ball given its unique identifier (ball_number).
    Categories are:
    - A: 1 to 200
    - B: 201 to 400
    - C: 401 to 600
    - D: 601 to 800
    - E: 801 to 1000
    """
    if 1 <= ball_number <= 200:
        return 'A'
    elif 201 <= ball_number <= 400:
        return 'B'
    elif 401 <= ball_number <= 600:
        return 'C'
    elif 601 <= ball_number <= 800:
        return 'D'
    elif 801 <= ball_number <= 1000:
        return 'E'
    else:
        raise ValueError("Ball number out of range")

