def reverse_nth_word(sentence, n):
    """
    Reverses every nth word in the sentence.

    Parameters:
    sentence (str): The sentence to be modified.
    n (int): The interval at which to reverse the words.

    Returns:
    str: The modified sentence with every nth word reversed.
    """
    if not sentence:
        return "The sentence is empty."

    words = sentence.split()
    num_words = len(words)

    if n <= 0:
        return "The value of n must be a positive integer."

    if n > num_words:
        return f"The value of n ({n}) is greater than the number of words ({num_words})."

    for i in range(n-1, num_words, n):
        words[i] = words[i][::-1]

    return ' '.join(words)

