def longest_substring_with_two_distinct_characters(s):
    """
    Returns the longest substring that contains exactly 2 distinct characters.

    Args:
    s (str): input string

    Returns:
    str: the longest substring with exactly 2 distinct characters
    """
    start = 0
    max_length = 0
    max_substring = ""
    char_count = {}

    for end in range(len(s)):
        if s[end] in char_count:
            char_count[s[end]] += 1
        else:
            char_count[s[end]] = 1

        while len(char_count) > 2:
            char_count[s[start]] -= 1
            if char_count[s[start]] == 0:
                del char_count[s[start]]
            start += 1

        if end - start + 1 > max_length:
            max_length = end - start + 1
            max_substring = s[start:end+1]

    return max_substring

