def longest_increasing_subsequence(arr):
    """
    Returns the length and one of the longest increasing subsequences of the array.
    """
    if not arr:
        return (0, [])

    n = len(arr)
    lengths = [1] * n
    previous_indices = [-1] * n

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and lengths[i] < lengths[j] + 1:
                lengths[i] = lengths[j] + 1
                previous_indices[i] = j

    max_length = max(lengths)
    index = lengths.index(max_length)

    lis = []
    while index != -1:
        lis.append(arr[index])
        index = previous_indices[index]

    lis.reverse()

    return (max_length, lis)

