def fizzbuzz():
    """
    Prints the numbers from 1 to 100, but for multiples of three prints "Fizz" 
    instead of the number and for the multiples of five prints "Buzz". For 
    numbers which are multiples of both three and five prints "FizzBuzz".
    """
    result = []
    for num in range(1, 101):
        if num % 3 == 0 and num % 5 == 0:
            result.append("FizzBuzz")
        elif num % 3 == 0:
            result.append("Fizz")
        elif num % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(num))
    return result

