    """
    This function takes an integer score and returns a string rating.
    The rating system is as follows:
    1-3: Poor
    4-7: Fair
    8-10: Good
    """
    if score < 1 or score > 10:
        return 'Invalid score'
    elif score < 4:
        return 'Poor'
    elif 4 <= score <= 7:
        return 'Fair'
    elif 8 <= score <= 10:
        return 'Good'

