def subset_sum(nums, target):
    """
    Returns True if there exists a subset of `nums` that sums up to `target`.
    Otherwise, returns False.
    """
    dp = [[False] * (target + 1) for _ in range(len(nums) + 1)]
    dp[0][0] = True

    for i in range(1, len(nums) + 1):
        for j in range(target + 1):
            if j < nums[i - 1]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]

    return dp[-1][-1]

def levenshtein_distance(a: str, b: str) -> int:
    """
    Computes the Levenshtein distance between two strings a and b.
    The Levenshtein distance is the number of single-character edits (insertions, deletions, or substitutions) required to change one word into the other.
    """
    # Base case: If one of the strings is empty, return the length of the other string
    if not a:
        return len(b)
    if not b:
        return len(a)

    # If the last characters are the same, no increment needed
    if a[-1] == b[-1]:
        return levenshtein_distance(a[:-1], b[:-1])

    # If the last characters are different, consider all possibilities and find the minimum
    insert = levenshtein_distance(a, b[:-1])
    delete = levenshtein_distance(a[:-1], b)
    replace = levenshtein_distance(a[:-1], b[:-1])

    return 1 + min(insert, delete, replace)

