def solve_eight_queens():
    """
    Solve the Eight Queens problem and return all possible configurations.
    Each configuration is represented as a list of strings, where 'Q' 
    represents a queen and '.' represents an empty square.
    """
    solutions = []
    def is_valid_position(queens, row, col):
        for r, c in enumerate(queens):
            if c == col or abs(r - row) == abs(c - col):
                return False
        return True

    def solve(queens, row):
        if row == 8:
            board = []
            for q in queens:
                board.append("".join('Q' if i == q else '.' for i in range(8)))
            solutions.append(board)
        else:
            for col in range(8):
                if is_valid_position(queens, row, col):
                    queens.append(col)
                    solve(queens, row + 1)
                    queens.pop()

    solve([], 0)
    return solutions

