def check_email_domain(email):
    """
    Extracts the domain from an email address and checks if it is from a popular domain.
    :param email: str - an email address
    :return: str - 'Popular Domain' or 'Other Domain'
    """
    popular_domains = {'gmail.com', 'yahoo.com', 'hotmail.com', 'aol.com', 'protonmail.com', 'outlook.com'}
    domain = email.split('@')[-1]
    if domain in popular_domains:
        return "Popular Domain"
    else:
        return "Other Domain"

def time_to_seconds(time_str):
    """
    Converts a given time string in the format 'HH:MM:SS' to seconds.
    Returns None for invalid input.
    """
    if not isinstance(time_str, str):
        return None

    parts = time_str.split(':')
    if len(parts) != 3:
        return None

    try:
        hours = int(parts[0])
        minutes = int(parts[1])
        seconds = int(parts[2])

        if hours < 0 or minutes < 0 or minutes >= 60 or seconds < 0 or seconds >= 60:
            return None

        return hours * 3600 + minutes * 60 + seconds
    except ValueError:
        return None

