from typing import List
import bisect


def sliding_window_median(nums: List[int], k: int) -> List[float]:
    """
    Returns the median of each sliding window of size k.
    """
    if k == 0 or not nums or k > len(nums):
        return []

    medians = []
    window = sorted(nums[:k])

    def median(window):
        n = len(window)
        if n % 2 == 1:
            return float(window[n // 2])
        else:
            return (window[n // 2 - 1] + window[n // 2]) / 2

    for i in range(len(nums) - k + 1):
        medians.append(median(window))
        if i + k < len(nums):
            old_elem = nums[i]
            new_elem = nums[i + k]
            window.remove(old_elem)
            bisect.insort(window, new_elem)

    return medians

def reverse_vowels(s: str) -> str:
    """
    This function reverses the vowels in the input string s.
    """
    vowels = set("aeiouAEIOU")
    s = list(s)
    i, j = 0, len(s) - 1
    while i < j:
        if s[i] in vowels and s[j] in vowels:
            s[i], s[j] = s[j], s[i]
            i += 1
            j -= 1
        if s[i] not in vowels:
            i += 1
        if s[j] not in vowels:
            j -= 1
    return ''.join(s)

def longest_palindromic_substring(s):
    """
    Returns the longest palindromic substring of the input string s.
    """
    def expand_from_center(left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left + 1:right]

    if not s:
        return ""

    longest = ""
    for i in range(len(s)):
        # Odd length palindrome
        odd_palindrome = expand_from_center(i, i)
        if len(odd_palindrome) > len(longest):
            longest = odd_palindrome
        # Even length palindrome
        even_palindrome = expand_from_center(i, i + 1)
        if len(even_palindrome) > len(longest):
            longest = even_palindrome

    return longest

def check_prime(num):
    """
    Checks if a number is prime. 
    Returns a tuple (is_prime, smallest_prime_factor).
    is_prime is True if num is prime, otherwise False.
    smallest_prime_factor is None if num is prime, 
    otherwise the smallest prime factor of num.
    """
    if num <= 1:
        return (False, None)

    if num == 2:
        return (True, None)

    if num % 2 == 0:
        return (False, 2)

    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return (False, i)

    return (True, None)

