def categorize_students(scores: list[tuple[str, int]]) -> dict[str, list[str]]:
    """
    Categorize students based on their scores.

    Args:
    - scores (list[tuple[str, int]]): A list of tuples where each tuple contains a student's name and their score.

    Returns:
    - dict[str, list[str]]: A dictionary with 'Top', 'Average', and 'Below Average' as keys and lists of student names as values.
    """
    categorized = {
        'Top': [],
        'Average': [],
        'Below Average': []
    }

    for name, score in scores:
        if score >= 75:
            categorized['Top'].append(name)
        elif 50 <= score < 75:
            categorized['Average'].append(name)
        else:
            categorized['Below Average'].append(name)

    return categorized

