def count_vowels(s):
    """
    Returns the number of vowels in the provided string and the frequency of each vowel.
    If the input is not a string, it returns an error message.

    Parameters:
        s (str): The input string.

    Returns:
        tuple: A tuple containing the total number of vowels and a dictionary with the frequency of each vowel.
    """
    if not isinstance(s, str):
        return "Error: Input is not a string."

    vowels = 'aeiouAEIOU'
    vowel_count = 0
    frequency = {v: 0 for v in 'aeiou'}

    for char in s:
        if char in vowels:
            vowel_count += 1
            if char.lower() in frequency:
                frequency[char.lower()] += 1

    return vowel_count, frequency

