def length_of_longest_substring_two_distinct(s):
    """
    Returns the length of the longest substring containing at most two distinct characters.
    """
    if not s:
        return 0

    # Dictionary to count the characters in current window
    count = {}
    left = 0
    max_length = 0

    for right in range(len(s)):
        if s[right] in count:
            count[s[right]] += 1
        else:
            count[s[right]] = 1

        while len(count) > 2:
            count[s[left]] -= 1
            if count[s[left]] == 0:
                del count[s[left]]
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

