def shifted_array_search(arr, target):
    """
    Find the index of target in a shifted sorted array. Return -1 if target is not found.
    """
    if not arr:
        return -1

    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return mid

        # Check if the left half is sorted
        if arr[left] <= arr[mid]:
            if arr[left] <= target < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if arr[mid] < target <= arr[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

def fibonacci_number(n):
    """
    Returns the nth Fibonacci number.
    If the input is not a non-negative integer, returns an error message.
    """
    if not isinstance(n, int) or n < 0:
        return 'Error: Input must be a non-negative integer'

    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b

    return b

