import math


def is_prime(n):
    """
    Checks whether a given number n is prime or not.

    Parameters:
    n (int): The number to check.

    Returns:
    bool: True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    max_divisor = math.floor(math.sqrt(n))
    for d in range(3, max_divisor + 1, 2):
        if n % d == 0:
            return False

    return True

def shift_string_backward(input_str, c):
    """
    Shifts the input string c characters in the backward direction using circular rotation.

    Args:
    input_str (str): The string to be shifted.
    c (int): The number of positions to shift the string backward.

    Returns:
    str: The shifted string.
    """
    result = []
    for char in input_str:
        if 'a' <= char <= 'z':
            new_char = chr((ord(char) - ord('a') - c) % 26 + ord('a'))
            result.append(new_char)
        elif 'A' <= char <= 'Z':
            new_char = chr((ord(char) - ord('A') - c) % 26 + ord('A'))
            result.append(new_char)
        else:
            result.append(char)

    return ''.join(result)

