def generate_order_summary(orders):
    """
    Generates a summary of orders with total quantity and total price for each item.

    Parameters:
    orders (list of tuples): A list where each tuple contains (item_name, quantity, price_per_unit).

    Returns:
    dict: A dictionary with item names as keys and another dictionary as values containing
          'total_quantity' and 'total_price' for each item.
    """
    summary = {}

    for item_name, quantity, price_per_unit in orders:
        if item_name not in summary:
            summary[item_name] = {'total_quantity': 0, 'total_price': 0.0}
        summary[item_name]['total_quantity'] += quantity
        summary[item_name]['total_price'] += quantity * price_per_unit

    # Optional: Rounding total_price to 2 decimal places
    for item in summary:
        summary[item]['total_price'] = round(summary[item]['total_price'], 2)

    return summary

