def robot_arithmetic(commands):
    """
    Decodes a list of encoded arithmetic commands and performs the corresponding operation.

    Parameters:
    commands (list): A list of encoded strings representing arithmetic operations.

    Returns:
    list: A list of results from performing each arithmetic operation.
    """
    results = []
    for command in commands:
        operation, values = command.split(":")
        x, y = map(int, values.split(","))
        if operation == "ADD":
            results.append(x + y)
        elif operation == "SUB":
            results.append(x - y)
        elif operation == "MUL":
            results.append(x * y)
        elif operation == "DIV":
            if y == 0:
                results.append(float('inf'))
            else:
                results.append(x / y)
    return results

