def grade_summary(grades):
    """
    Converts numeric grades into letter grades and summarizes the count of each letter grade.

    Args:
        grades (list): List of numeric grades (integers).

    Returns:
        dict: A dictionary with letter grades as keys and their counts as values.
    """
    summary = {'A': 0, 'B': 0, 'C': 0, 'D': 0, 'F': 0}

    for grade in grades:
        if grade >= 90:
            summary['A'] += 1
        elif grade >= 80:
            summary['B'] += 1
        elif grade >= 70:
            summary['C'] += 1
        elif grade >= 60:
            summary['D'] += 1
        else:
            summary['F'] += 1

    return summary

