def caesar_cipher(text, shift):
    """
    Applies a Caesar cipher to the input text, shifting each letter by the specified number of positions.

    :param text: The input string to be encrypted.
    :param shift: The number of positions to shift each letter.
    :return: The encrypted string.
    """
    def shift_char(c):
        if 'a' <= c <= 'z':
            return chr(((ord(c) - ord('a') + shift) % 26) + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr(((ord(c) - ord('A') + shift) % 26) + ord('A'))
        else:
            return c

    return ''.join(shift_char(c) for c in text)

