def bubble_sort_students(students):
    """
    Sorts students by their score in descending order.
    In case of a tie, sorts the students by their names in alphabetical order.

    :param students: List of students where each student is represented by a list containing the name and score.
    :type students: list of [str, int]
    """
    n = len(students)

    for i in range(n):
        for j in range(0, n-i-1):
            if (students[j][1] < students[j+1][1]) or (students[j][1] == students[j+1][1] and students[j][0] > students[j+1][0]):
                students[j], students[j+1] = students[j+1], students[j]

    return students

def diff_dicts(d1, d2):
    """
    Compute the difference between two dictionaries, including nested dictionaries.
    Returns a dictionary containing the differences.
    """
    diff = {}
    all_keys = set(d1.keys()).union(set(d2.keys()))

    for key in all_keys:
        if key in d1 and key not in d2:
            diff[key] = ("removed", d1[key])
        elif key not in d1 and key in d2:
            diff[key] = ("added", d2[key])
        elif d1[key] != d2[key]:
            if isinstance(d1[key], dict) and isinstance(d2[key], dict):
                nested_diff = diff_dicts(d1[key], d2[key])
                if nested_diff:
                    diff[key] = nested_diff
            else:
                diff[key] = ("modified", d1[key], d2[key])
    return diff

