def validate_stack_operations(operations: list[str], expected_output: list[int]) -> bool:
    """
    Validates the sequence of stack operations against the expected output.

    :param operations: List of stack operations to perform. Each operation is 'PUSH x' or 'POP'.
    :param expected_output: List of integers representing the expected sequence of outputs from the 'POP' operations.
    :return: True if the stack operations produce the expected sequence of outputs, False otherwise.
    """
    stack = []
    output_index = 0

    for operation in operations:
        if operation.startswith('PUSH '):
            _, value = operation.split()
            stack.append(int(value))
        elif operation == 'POP':
            if not stack:
                return False
            popped_value = stack.pop()
            if output_index < len(expected_output) and expected_output[output_index] == popped_value:
                output_index += 1
            else:
                return False

    return output_index == len(expected_output)

def add_positive_integers(a, b):
    """
    Returns the sum of a and b if both are positive integers and the sum is greater than 100.
    Otherwise, returns an appropriate error message.
    """
    if not (isinstance(a, int) and isinstance(b, int)):
        return "Error: Both inputs must be integers."
    if a <= 0 or b <= 0:
        return "Error: Both inputs must be positive."

    result = a + b
    if result > 100:
        return result
    else:
        return "The sum is too small"

