def longest_common_subsequence(s1, s2):
    """
    This function finds the length of the longest common subsequence (LCS) and the LCS itself between two strings s1 and s2.
    """
    m, n = len(s1), len(s2)

    # Initialize the memoization matrix
    lcs_matrix = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the matrix
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                lcs_matrix[i][j] = lcs_matrix[i - 1][j - 1] + 1
            else:
                lcs_matrix[i][j] = max(lcs_matrix[i - 1][j], lcs_matrix[i][j - 1])

    # Length of LCS
    lcs_length = lcs_matrix[m][n]

    # Retrieve the LCS itself
    lcs_str = []
    i, j = m, n
    while i > 0 and j > 0:
        if s1[i - 1] == s2[j - 1]:
            lcs_str.append(s1[i - 1])
            i -= 1
            j -= 1
        elif lcs_matrix[i - 1][j] > lcs_matrix[i][j - 1]:
            i -= 1
        else:
            j -= 1

    lcs_str.reverse()

    return lcs_length, ''.join(lcs_str)

