def kth_smallest(arr, k):
    """
    Returns the k-th smallest element in the array.
    """
    if not isinstance(arr, list) or not isinstance(k, int) or k <= 0:
        raise ValueError("Invalid input: arr must be a list, and k must be a positive integer.")

    for val in arr:
        if not isinstance(val, (int, float)):
            raise ValueError(f"Invalid element in arr: {val}. All elements must be int or float.")

    sorted_arr = sorted(arr)

    if k > len(sorted_arr):
        raise ValueError("k is larger than the size of the array.")

    return sorted_arr[k - 1]

