def elevator_system(commands):
    """
    Simulates an elevator system in a building.

    Parameters:
        commands (List[str]): A list of commands in the format specified (i.e., "CALL <floor_number>" or "DESTINATION <floor_number>").

    Returns:
        List[int]: The sequence of floors that the elevator travels through.
    """

    current_floor = 0
    floors_visited = [current_floor]
    call_queue = []
    destination_queue = []

    for command in commands:
        cmd, floor = command.split()
        floor = int(floor)

        if cmd == "CALL":
            if floor not in call_queue and floor not in destination_queue:
                call_queue.append(floor)
        elif cmd == "DESTINATION":
            if floor not in destination_queue:
                destination_queue.append(floor)

    all_floors = sorted(set(call_queue + destination_queue))

    for floor in all_floors:
        if floor not in floors_visited:
            floors_visited.append(floor)

    return floors_visited

