def print_pattern(n):
    """
    Prints a pattern of numbers based on the input integer n.
    Returns "Invalid input" if n is negative, zero, or greater than 100.
    """
    if n <= 0 or n > 100:
        return "Invalid Input"

    pattern = ""
    for i in range(n, 0, -1):
        line = ' '.join(str(x) for x in range(1, i + 1))
        pattern += line + "\n"
    return pattern.strip()

