from typing import List


def is_valid_tictactoe_state(board: List[str]) -> bool:
    """
    Determines if a given tic-tac-toe board configuration is a valid state.
    """
    def check_winner(player: str) -> bool:
        # Check rows, columns and diagonals for a win
        return any([
            all(cell == player for cell in row) for row in board
        ]) or any([
            all(board[row][col] == player for row in range(3)) for col in range(3)
        ]) or all([
            board[i][i] == player for i in range(3)
        ]) or all([
            board[i][2 - i] == player for i in range(3)
        ])

    # Count X's and O's
    x_count = sum(row.count('X') for row in board)
    o_count = sum(row.count('O') for row in board)

    if o_count > x_count:
        return False
    if x_count > o_count + 1:
        return False

    x_wins = check_winner('X')
    o_wins = check_winner('O')

    if x_wins and o_wins:
        return False
    if x_wins and x_count != o_count + 1:
        return False
    if o_wins and x_count != o_count:
        return False

    return True

