def compress_string(text):
    """
    Compresses the string using run-length encoding (RLE).
    If a character appears only once, it should not be followed by a number.

    :param text: A string containing only alphabetic characters.
    :return: The compressed string.
    """
    if not text:
        return ""

    compressed = []
    count = 1
    prev_char = text[0]

    for char in text[1:]:
        if char == prev_char:
            count += 1
        else:
            compressed.append(prev_char)
            if count > 1:
                compressed.append(str(count))
            prev_char = char
            count = 1

    # Append the last character and its count
    compressed.append(prev_char)
    if count > 1:
        compressed.append(str(count))

    return ''.join(compressed)

