def validate_brackets(input_string: str) -> bool:
    """
    Validates whether the input string has balanced brackets.

    Parameters:
    input_string (str): The string to be checked for balanced brackets.

    Returns:
    bool: True if the string has balanced brackets, False otherwise.

    Raises:
    ValueError: If the input is not a string.
    """

    if not isinstance(input_string, str):
        raise ValueError("Input must be a string")

    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in input_string:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map:
            if stack == [] or bracket_map[char] != stack.pop():
                return False

    return stack == []

