def generate_grid(rows: int, cols: int) -> str:
    """
    Generate a rectangular grid using two input integers. 

    Each cell in the grid alternates between 'X' and 'O', starting with 'X'.

    Returns an empty string if rows or columns are zero or negative.
    """
    if rows <= 0 or cols <= 0:
        return ''

    grid = []
    for i in range(rows):
        row = []
        for j in range(cols):
            if (i + j) % 2 == 0:
                row.append('X')
            else:
                row.append('O')
        grid.append(''.join(row))

    return '\n'.join(grid)

