def fib(n):
    """
    Returns the nth Fibonacci number.
    For negative indices, returns -1.
    """
    if n < 0:
        return -1
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

def fibonacci(n):
    """
    Returns the nth Fibonacci number.
    """
    if n <= 0:
        return "Invalid input"

    if n == 1:
        return 0
    elif n == 2:
        return 1

    a, b = 0, 1
    for _ in range(2, n):
        a, b = b, a + b
    return b

