def nth_fibonacci(n):
    """
    Returns the n-th Fibonacci number.

    If n is zero or negative, returns None.
    If n is not an integer, raises a TypeError.
    """
    if not isinstance(n, int):
        raise TypeError("Input n must be an integer")

    if n <= 0:
        return None

    if n == 1:
        return 0
    elif n == 2:
        return 1

    a, b = 0, 1
    for _ in range(2, n):
        a, b = b, a + b
    return b

