def safe_divide_and_access(a: int, b: int, lst: list, index: int) -> dict:
    """
    Perform division and access list element safely, handling various exceptions.

    Parameters:
        a (int): The numerator.
        b (int): The denominator.
        lst (list): The list from which an element is to be accessed.
        index (int): The index of the element to be accessed.

    Returns:
        dict: A dictionary with the results of the division and element access, 
              and any errors encountered.
    """
    result = {
        'division_result': None,
        'element': None,
        'errors': {}
    }

    # Handle division with exception handling.
    try:
        result['division_result'] = a / b
    except ZeroDivisionError as e:
        result['errors']['ZeroDivisionError'] = str(e)
    except TypeError as e:
        result['errors']['TypeError'] = str(e)

    # Handle list index access with exception handling.
    try:
        result['element'] = lst[index]
    except IndexError as e:
        result['errors']['IndexError'] = str(e)
    except TypeError as e:
        result['errors']['TypeError'] = str(e)

    return result

