def sum_n_elements(numbers, n):
    """
    Returns the sum of the first n elements in the list 'numbers'.
    If n is greater than the length of the list, sum all elements.
    If the list is empty, return 0.
    Validates inputs to be of correct types.
    """
    if not isinstance(numbers, list):
        raise TypeError("The first argument must be a list.")

    if not all(isinstance(num, (int, float)) for num in numbers):
        raise TypeError("All elements in the list must be integers or floats.")

    if not isinstance(n, int):
        raise TypeError("The second argument must be an integer.")

    if n < 0:
        raise ValueError("The integer value must be non-negative.")

    return sum(numbers[:n]) if numbers else 0

