def count_file_extensions(file_paths):
    """
    Takes a list of file paths and returns a dictionary with file extensions as keys
    and the number of occurrences as values.
    """
    extension_count = {}

    for path in file_paths:
        # Split path by '.' and keep fragments after the last '/'
        parts = path.split('/')[-1].split('.')

        # If the file has no extension, consider it as a special case
        if len(parts) == 1:
            ext = 'no_extension'
        else:
            ext = '.'.join(parts[1:])  # Consider the entire suffix as the extension

        if ext in extension_count:
            extension_count[ext] += 1
        else:
            extension_count[ext] = 1

    return extension_count

