def fibonacci(n):
    """
    Returns the n-th Fibonacci number.

    Parameters:
    n (int): The position of the desired Fibonacci number in the sequence (0-indexed).

    Returns:
    int: The n-th Fibonacci number.
    """
    if n < 0:
        raise ValueError("Input should be a non-negative integer.")
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n+1):
            a, b = b, a + b
        return b

