def compare_scores(students, student_name):
    """
    Returns a list of names of students that have a higher score than the given student.
    """
    target_student = None
    for student in students:
        if student['name'] == student_name:
            target_student = student
            break

    if target_student is None:
        raise ValueError(f"No student found with the name {student_name}")

    higher_score_students = []
    for student in students:
        if student['score'] > target_student['score']:
            higher_score_students.append(student['name'])

    return higher_score_students

