def is_prime(number):
    """
    Check if a given number is a prime number.
    Return 'Prime' if the number is a prime number, otherwise return 'Not Prime'.
    """
    if number <= 1:
        return "Not Prime"
    if number <= 3:
        return "Prime"
    if number % 2 == 0 or number % 3 == 0:
        return "Not Prime"
    i = 5
    while i * i <= number:
        if number % i == 0 or number % (i + 2) == 0:
            return "Not Prime"
        i += 6
    return "Prime"

def merge_sort(arr):
    """
    Sorts an array of numbers using the merge sort algorithm.
    """
    if len(arr) <= 1:
        return arr

    def merge(left, right):
        if not left:
            return right
        if not right:
            return left

        if left[0] < right[0]:
            return [left[0]] + merge(left[1:], right)
        return [right[0]] + merge(left, right[1:])

    middle = len(arr) // 2
    left = arr[:middle]
    right = arr[middle:]

    return merge(merge_sort(left), merge_sort(right))

