def is_perfect_square(n):
    """
    Returns True if n is a perfect square, otherwise returns False.
    """
    if n < 1:
        return False

    left, right = 1, n
    while left <= right:
        mid = (left + right) // 2
        mid_squared = mid * mid
        if mid_squared == n:
            return True
        elif mid_squared < n:
            left = mid + 1
        else:
            right = mid - 1
    return False

def convert_temperature(temp: float, from_unit: str, to_unit: str) -> float:
    """
    Converts temperature from one unit to another.

    Arguments:
    temp : float : The temperature value to convert.
    from_unit : str : The current unit of the temperature ('C' for Celsius, 'F' for Fahrenheit).
    to_unit : str : The desired unit to convert the temperature to ('C' for Celsius, 'F' for Fahrenheit).

    Returns:
    float : The converted temperature value.
    """

    if from_unit not in ['C', 'F']:
        raise Exception("Invalid from_unit. Must be either 'C' or 'F'")

    if to_unit not in ['C', 'F']:
        raise Exception("Invalid to_unit. Must be either 'C' or 'F'")

    if from_unit == to_unit:
        return temp

    if from_unit == 'C' and to_unit == 'F':
        return (temp * 9/5) + 32
    elif from_unit == 'F' and to_unit == 'C':
        return (temp - 32) * 5/9

