def calculate_total_cost(n):
    """
    Returns the total cost for n number of donuts based on the bakery's pricing tiers.
    """
    return round(
        n * (
            (n >= 1) * (n <= 4) * 1.00 +
            (n >= 5) * (n <= 9) * 0.95 +
            (n >= 10) * (n <= 19) * 0.90 +
            (n >= 20) * 0.85
        ), 2
    )

