def unique_paths(m: int, n: int) -> int:
    """
    Returns the number of unique paths from the top-left corner to the bottom-right corner of an m x n grid.
    """
    # Create a 2D array `dp` where `dp[i][j]` represents the number of ways to reach cell (i, j)
    dp = [[0] * n for _ in range(m)]

    # Initialize the top row and left column to 1
    for i in range(m):
        dp[i][0] = 1
    for j in range(n):
        dp[0][j] = 1

    # Fill the rest of the dp array
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

def find_unique_substrings(s: str, k: int) -> list[str]:
    """
    Returns a list of all unique substrings of length k from the input string s.
    """
    if not isinstance(s, str):
        raise TypeError("The input 's' must be a string.")
    if not isinstance(k, int):
        raise TypeError("The input 'k' must be an integer.")
    if k < 1 or k > len(s):
        raise ValueError("The input 'k' must be between 1 and the length of the string 's'.")

    unique_substrings = set()
    for i in range(len(s) - k + 1):
        substring = s[i:i+k]
        unique_substrings.add(substring)

    return list(unique_substrings)

