def vending_machine(money_inserted, item_price, inventory, item_name):
    """
    Simulates a vending machine.

    Parameters:
    money_inserted (float): Amount of money inserted into the machine.
    item_price (float): Price of the item.
    inventory (dict): Dictionary with items as keys and quantities as values.
    item_name (str): The name of the item to purchase.

    Returns:
    tuple: Containing the change, the item name, and the updated inventory, 
           or an error message if the item is out of stock or money is insufficient.
    """

    if item_name not in inventory:
        return ("Error: Item not available",)

    if inventory[item_name] <= 0:
        return ("Error: Out of stock",)

    if money_inserted < item_price:
        return ("Error: Insufficient money",)

    change = money_inserted - item_price
    inventory[item_name] -= 1

    return (change, item_name, inventory)

