def subarraysDivByK(nums, k):
    """
    Returns the count of non-empty subarrays whose sum is divisible by k.
    """
    count = 0
    prefix_sum = 0
    modulo_counts = {0: 1}

    for num in nums:
        prefix_sum += num
        modulo = prefix_sum % k
        if modulo < 0:
            modulo += k

        if modulo in modulo_counts:
            count += modulo_counts[modulo]
            modulo_counts[modulo] += 1
        else:
            modulo_counts[modulo] = 1

    return count

