def bubble_sort_passes(arr):
    """
    Returns the smallest number of passes needed to sort the list using Bubble Sort.
    """
    n = len(arr)
    num_passes = 0

    while True:
        swapped = False
        for i in range(1, n):
            if arr[i-1] > arr[i]:
                arr[i-1], arr[i] = arr[i], arr[i-1]
                swapped = True
        num_passes += 1
        if not swapped:
            break

    return num_passes

