def is_balanced(input_str):
    """
    Checks whether the input string of parentheses, brackets, and curly braces is balanced.

    Args:
    input_str (str): The input string containing '(', ')', '[', ']', '{', '}'.

    Returns:
    bool: True if the string is balanced, False otherwise.
    """
    stack = []
    opening = set('([{')
    matching = {')': '(', ']': '[', '}': '{'}

    for char in input_str:
        if char in opening:
            stack.append(char)
        elif char in matching:
            if not stack or stack.pop() != matching[char]:
                return False
    return not stack

