def find_max_length(arr: list[int]) -> int:
    """
    Finds the longest contiguous subarray within a binary array that has an equal number of 0s and 1s.
    """
    # Dictionary to store the first occurrence of a balance value
    balance_index_map = {0: -1}
    max_length = 0
    balance = 0

    for i, num in enumerate(arr):
        # Increment balance for 1 and decrement for 0
        if num == 1:
            balance += 1
        else:
            balance -= 1

        if balance in balance_index_map:
            # Calculate the length of the subarray and update max_length
            subarray_length = i - balance_index_map[balance]
            max_length = max(max_length, subarray_length)
        else:
            # Store the first occurrence of the balance
            balance_index_map[balance] = i

    return max_length

