from collections import Counter


def longest_palindromic_substring_length(s):
    """
    Returns the length of the longest substring that can be rearranged to form a palindrome.
    """
    if not s:
        return 0

    char_count = Counter(s)
    length = 0
    has_odd = False

    for count in char_count.values():
        if count % 2 == 0:
            length += count
        else:
            length += count - 1
            has_odd = True

    if has_odd:
        length += 1

    return length

