def evaluate_expression(expression):
    """
    Evaluates a mathematical expression provided as a string. The expression contains non-negative
    integers, operators (+, -, *, /), and parentheses. The expression is evaluated according to
    operator precedence and parentheses. Division is performed as integer division.

    :param expression: A string containing the mathematical expression.
    :return: The integer result of the evaluated expression.
    """
    def calculate(operators, operands):
        right = operands.pop()
        left = operands.pop()
        operator = operators.pop()
        if operator == '+':
            operands.append(left + right)
        elif operator == '-':
            operands.append(left - right)
        elif operator == '*':
            operands.append(left * right)
        elif operator == '/':
            operands.append(left // right)  # Integer division

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    operators, operands = [], []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue
        elif expression[i] == '(':
            operators.append(expression[i])
        elif expression[i].isdigit():
            num = 0
            while i < len(expression) and expression[i].isdigit():
                num = num * 10 + int(expression[i])
                i += 1
            operands.append(num)
            i -= 1
        elif expression[i] == ')':
            while operators and operators[-1] != '(':
                calculate(operators, operands)
            operators.pop()
        else:
            while operators and precedence(operators[-1]) >= precedence(expression[i]):
                calculate(operators, operands)
            operators.append(expression[i])
        i += 1

    while operators:
        calculate(operators, operands)

    return operands[-1]

