from collections import deque


def min_operations_to_transform(target, wordList):
    """
    Returns the minimum number of operations required to transform the target string into one of the strings in the word list.
    """
    word_set = set(wordList)
    queue = deque([(target, 0)])
    visited = set([target])

    while queue:
        current_word, operations = queue.popleft()

        if current_word in word_set:
            return operations

        for i in range(len(current_word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                next_word = current_word[:i] + c + current_word[i+1:]
                if next_word in word_set and next_word not in visited:
                    visited.add(next_word)
                    queue.append((next_word, operations + 1))

    return -1

