def bottles_of_beer(verse):
    """
    Returns the corresponding verse from the song 99 Bottles of Beer given the verse number.
    """

    if verse < 0 or verse > 99:
        raise ValueError("Verse must be between 0 and 99")

    if verse == 0:
        return (
            "No more bottles of beer on the wall, no more bottles of beer.\n"
            "Go to the store and buy some more, 99 bottles of beer on the wall."
        )
    elif verse == 1:
        return (
            "1 bottle of beer on the wall, 1 bottle of beer.\n"
            "Take one down and pass it around, no more bottles of beer on the wall."
        )
    else:
        return (
            f"{verse} bottles of beer on the wall, {verse} bottles of beer.\n"
            f"Take one down and pass it around, {verse - 1} bottle{'s' if verse - 1 != 1 else ''} of beer on the wall."
        )

