def find_max_divisible(start, end, step):
    """
    Returns the maximum value within the range [start, end] that is divisible by step.
    If no such number exists, returns a suitable message.
    """
    # Checking if the range is valid
    if start > end or step <= 0:
        return "Invalid input: start must be less than or equal to end and step must be positive."

    # Loop over the range from end to start to find the maximum divisible number
    for num in range(end, start - 1, -1):
        if num % step == 0:
            return num

    return "No number in the range is divisible by the specified step."

