def powers_and_factorial(n):
    """
    Returns the sum of powers of 2 from 2^0 to 2^n and the factorial of that sum.
    """
    if n < 0:
        raise ValueError("The input must be a non-negative integer")

    total_sum = sum(2**i for i in range(n + 1))

    def factorial(num):
        if num == 0 or num == 1:
            return 1
        return num * factorial(num - 1)

    factorial_of_sum = factorial(total_sum)

    return total_sum, factorial_of_sum

