def unique_word_count(text):
    """
    Returns the total number of unique words in a given text, ignoring
    common English stop words and considering words in a case-insensitive manner.
    """
    stop_words = {"the", "and", "is", "in", "at", "which", "on", "for", "with", "a", "an", "to", "of", "by", "from"}
    words = text.lower().split()
    filtered_words = [word.strip(",.!?:;()[]{}\"'") for word in words if word.strip(",.!?:;()[]{}\"'") not in stop_words]
    return len(set(filtered_words))

