def longest_subsequence_k_times(s: str, k: int) -> int:
    """
    Returns the length of the longest possible subsequence in which every character appears at least 'k' times.
    This function employs a divide and conquer strategy.
    """
    def helper(start, end):
        if end - start < k:
            return 0

        count = {}
        for i in range(start, end):
            if s[i] in count:
                count[s[i]] += 1
            else:
                count[s[i]] = 1

        for mid in range(start, end):
            if count[s[mid]] < k:
                left = helper(start, mid)
                right = helper(mid + 1, end)
                return max(left, right)

        return end - start

    return helper(0, len(s))

