def convert_to_12_hour_format(hour):
    """
    Converts an hour from 24-hour format to 12-hour format with AM/PM.

    Args:
    hour (int): The hour in 24-hour format (0 to 23).

    Returns:
    str: The hour in 12-hour format followed by AM or PM.
    """
    if hour == 0:
        return "12 AM"
    elif 1 <= hour <= 11:
        return f"{hour} AM"
    elif hour == 12:
        return "12 PM"
    else:
        return f"{hour - 12} PM"

