import operator


def evaluate_expression(expression: str) -> float:
    """
    Evaluates a mathematical expression given as a string.
    Supports basic operations (+, -, *, /) and parentheses.

    Parameters:
    expression (str): The mathematical expression to evaluate.

    Returns:
    float: The result of the evaluation.
    """
    def get_precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators, values):
        right = values.pop()
        left = values.pop()
        operator = operators.pop()
        values.append(operators_map[operator](left, right))

    def parse_expression(expression):
        operators, values = [], []
        i, n = 0, len(expression)

        while i < n:
            if expression[i] == ' ':
                i += 1
                continue
            if expression[i] == '(':
                operators.append(expression[i])
            elif expression[i].isdigit():
                val = 0
                while i < n and expression[i].isdigit():
                    val = val * 10 + int(expression[i])
                    i += 1
                values.append(val)
                i -= 1
            elif expression[i] == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()
            else:
                while (operators and get_precedence(operators[-1]) >= get_precedence(expression[i])):
                    apply_operator(operators, values)
                operators.append(expression[i])
            i += 1

        while operators:
            apply_operator(operators, values)

        return values[0]

    operators_map = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv
    }

    return parse_expression(expression)

