def length_of_longest_substring(s: str) -> int:
    """
    Find the length of the longest substring without repeating characters.
    """
    n = len(s)
    if n == 0:
        return 0
    char_index_map = {}
    longest_length = 0
    start = 0

    for end in range(n):
        if s[end] in char_index_map:
            start = max(start, char_index_map[s[end]] + 1)
        char_index_map[s[end]] = end
        longest_length = max(longest_length, end - start + 1)

    return longest_length

def convert_number(input_value):
    """
    Converts decimal to binary string or binary string to decimal.

    Args:
    input_value: a decimal number (int) or binary string (str)

    Returns:
    Converted value as a binary string if input is decimal, 
    or decimal int if input is a binary string.

    Raises:
    ValueError: if input is invalid (not a decimal number or binary string).
    """
    if isinstance(input_value, int):
        if input_value < 0:
            raise ValueError("Only non-negative integers are allowed.")
        return bin(input_value)[2:]
    elif isinstance(input_value, str):
        if not all(c in '01' for c in input_value):
            raise ValueError("Invalid binary string.")
        return int(input_value, 2)
    else:
        raise ValueError("Input must be a non-negative integer or a binary string.")

