def min_perfect_squares(n, memo=None):
    """
    Returns the minimum number of perfect square numbers which sum up to n.
    Uses memoization to avoid redundant calculations.
    """
    if memo is None:
        memo = {}

    if n in memo:
        return memo[n]

    if n == 0:
        return 0

    min_count = n  # Initialize with max possible count (1^2 + 1^2 + ... + 1^2)
    i = 1
    while i * i <= n:
        min_count = min(min_count, 1 + min_perfect_squares(n - i * i, memo))
        i += 1

    memo[n] = min_count
    return min_count

def evaluate_postfix_expression(expression: str) -> float:
    """
    Evaluates a given postfix expression and returns the result as a float. 
    The expression tokens are separated by spaces

    :param expression: str - postfix expression
    :return: float - the evaluation result
    """
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token in "+-*/":
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            elif token == "/":
                stack.append(a / b)
        else:
            stack.append(float(token))

    return stack[-1]

def spiral_order(matrix):
    """
    Returns the elements of the matrix in spiral order.
    """
    if not matrix:
        return []

    result = []
    while matrix:
        result += matrix.pop(0)
        if matrix and matrix[0]:
            for row in matrix:
                result.append(row.pop())
        if matrix:
            result += matrix.pop()[::-1]
        if matrix and matrix[0]:
            for row in matrix[::-1]:
                result.append(row.pop(0))
    return result

