def count_pairs_with_sum(numbers, target):
    """
    Returns the count of unique pairs of numbers in the list that sum up to the target.
    """
    num_count = {}
    count = 0

    # Store the frequency of each number in a dictionary
    for number in numbers:
        if number in num_count:
            num_count[number] += 1
        else:
            num_count[number] = 1

    for number in numbers:
        complement = target - number
        if complement in num_count:
            count += num_count[complement]

            # Adjust count if complement and number are the same
            if complement == number:
                count -= 1

    # Every pair is counted twice
    return count // 2

