def longest_contiguous_subarray(arr):
    """
    Returns the length of the longest contiguous subarray with no duplicate elements.
    """
    n = len(arr)
    if n == 0:
        return 0

    max_len = 0
    start = 0
    seen = {}

    for end in range(n):
        if arr[end] in seen:
            start = max(start, seen[arr[end]] + 1)
        seen[arr[end]] = end
        max_len = max(max_len, end - start + 1)

    return max_len

