def find_first_and_last(arr, target):
    """
    Returns the first and last occurrence of the target value in a sorted array.
    If the target value is not found, returns [-1, -1].
    """
    def binary_search_left(arr, target):
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def binary_search_right(arr, target):
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] <= target:
                left = mid + 1
            else:
                right = mid - 1
        return right

    first = binary_search_left(arr, target)
    last = binary_search_right(arr, target)

    if first <= last and 0 <= first < len(arr) and arr[first] == target:
        return [first, last]
    return [-1, -1]

