def longest_consecutive_repeating_characters(s):
    """
    Given a string s, find the length of the longest consecutive sequence of repeating characters.

    :param s: input string
    :return: length of the longest consecutive sequence of repeating characters
    """

    if not s:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            current_length += 1
        else:
            current_length = 1
        if current_length > max_length:
            max_length = current_length

    return max_length

