def evaluate_expression(expression: str) -> int:
    """
    Evaluates a mathematical expression in a string.
    Assumes the expression contains non-negative integers and the operators +, -, *, and /.
    """
    def apply_op(operators, operands):
        right = operands.pop()
        left = operands.pop()
        op = operators.pop()
        if op == '+':
            operands.append(left + right)
        elif op == '-':
            operands.append(left - right)
        elif op == '*':
            operands.append(left * right)
        elif op == '/':
            operands.append(int(left / right))  # The int cast is for truncation towards zero

    def precedence(op):
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '/':
            return 2
        return 0

    operators = []
    operands = []
    i = 0
    while i < len(expression):
        if expression[i] == ' ':
            i += 1
            continue
        if expression[i] == '(':
            operators.append(expression[i])
        elif expression[i].isdigit():
            val = 0
            while (i < len(expression) and expression[i].isdigit()):
                val = (val * 10) + int(expression[i])
                i += 1
            operands.append(val)
            i -= 1
        elif expression[i] == ')':
            while len(operators) != 0 and operators[-1] != '(':
                apply_op(operators, operands)
            operators.pop()
        else:
            while (len(operators) != 0 and 
                   precedence(operators[-1]) >= precedence(expression[i])):
                apply_op(operators, operands)
            operators.append(expression[i])
        i += 1

    while len(operators) != 0:
        apply_op(operators, operands)

    return operands[-1]

def is_prime(n: int) -> bool:
    """
    Returns True if n is a prime number, False otherwise.
    Prime numbers are greater than 1 and have no divisors other than 1 and themselves.
    """
    if n <= 1:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6

    return True

