def is_leap_year(year):
    """
    Returns True if the given year is a leap year, otherwise False.
    """
    if year % 4 == 0:
        if year % 100 == 0:
            if year % 400 == 0:
                return True
            else:
                return False
        else:
            return True
    else:
        return False

