def calculate_averages(students):
    """
    Calculate average scores for each student and return a sorted list of students
    by their average scores in descending order. Ties are resolved by alphabetical order of names.
    """
    # Handle empty input
    if not students:
        return []

    # Calculate average scores
    averages = []
    for student, scores in students:
        if not scores:
            average = 0.0
        else:
            valid_scores = [score for score in scores if isinstance(score, (int, float))]
            if not valid_scores:
                average = 0.0
            else:
                average = sum(valid_scores) / len(valid_scores)
        averages.append((student, round(average, 2)))

    # Sort by average score (descending) and name (ascending) for ties
    averages.sort(key=lambda x: (-x[1], x[0]))

    return averages

