import math


def is_prime(num):
    """
    Returns True if the input number is a prime number, otherwise False.
    """
    if not isinstance(num, int):
        raise ValueError("Input must be an integer")

    if num <= 1:
        return False

    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

