def max_sum_pair(arr1, arr2):
    """
    Returns a pair of values (one from each array) that have the maximum sum.
    """
    if not arr1 or not arr2:
        return None, None # If either array is empty, return a tuple of Nones

    max_pair = (arr1[0], arr2[0])
    max_sum = max_pair[0] + max_pair[1]

    for num1 in arr1:
        for num2 in arr2:
            current_sum = num1 + num2
            if current_sum > max_sum:
                max_sum = current_sum
                max_pair = (num1, num2)

    return max_pair

