def recursive_fibonacci(n, seen=None):
    """
    Calculates the nth Fibonacci number using recursion and tracks seen numbers.
    :param n: The position in the Fibonacci sequence.
    :param seen: List to track seen numbers.
    :return: The nth Fibonacci number.
    """
    if seen is None:
        seen = []

    if n < 0:
        return "Input should be a non negative integer"
    elif n in [0, 1]:
        if n not in seen:
            seen.append(n)
        return n
    else:
        if n not in seen:
            seen.append(n)
        return recursive_fibonacci(n-1, seen) + recursive_fibonacci(n-2, seen)

