def sort_descending(arr):
    """
    Sorts an array of floating point numbers from largest to smallest.
    Throws a TypeError if the input is not a list of floats.
    """
    if not isinstance(arr, list) or any(not isinstance(x, float) for x in arr):
        raise TypeError("Input must be a list of floating point numbers.")

    # Implementing bubble sort for demonstration purposes.
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] < arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]

    return arr

