def evaluate_postfix(expression):
    """
    Evaluates a postfix (Reverse Polish Notation) expression.
    """
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token in "+-*/":
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(int(a / b))  # Integer division truncating towards zero
        else:
            stack.append(int(token))

    return stack[0]

