def can_form_palindrome(s):
    """
    Checks if the given string can be re-arranged to form a palindrome, 
    considering alphabetic characters only and ignoring case sensitivity.

    Args:
    s (str): The input string

    Returns:
    bool: True if the string can be re-arranged to form a palindrome, False otherwise
    """
    s = s.lower()
    char_count = {}

    for char in s:
        if char.isalpha():
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1

    odd_count = sum(1 for count in char_count.values() if count % 2 != 0)
    return odd_count <= 1

