def binary_search_recursive(array, target, left=0, right=None):
    """
    Performs binary search on a sorted array using recursion.
    Args:
        array (list): A sorted array of integers.
        target (int): The integer to search for.
        left (int): The left boundary of the search range.
        right (int): The right boundary of the search range.
    Returns:
        int: The index of the target integer if found, otherwise -1.
    """
    if right is None:
        right = len(array) - 1

    if left > right:
        return -1

    mid = (left + right) // 2
    if array[mid] == target:
        return mid
    elif array[mid] < target:
        return binary_search_recursive(array, target, mid + 1, right)
    else:
        return binary_search_recursive(array, target, left, mid - 1)

