def find_max_sum_submatrix(matrix):
    """
    Returns the maximum sum of a submatrix within the given 2D array (matrix) using divide and conquer approach.

    Args:
    matrix (List[List[int]]): A 2D list representing the matrix.

    Returns:
    int: The maximum sum of a submatrix.
    """
    def max_sum_subarray(arr):
        max_ending_here = max_so_far = arr[0]
        for x in arr[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    def max_sum_submatrix_for_fixed_left_right(matrix, left, right):
        temp = [0] * len(matrix)
        max_sum = float('-inf')
        for i in range(left, right + 1):
            for j in range(len(matrix)):
                temp[j] += matrix[j][i]
            max_sum = max(max_sum, max_sum_subarray(temp))
        return max_sum

    if not matrix or not matrix[0]:
        return 0

    max_sum = float('-inf')
    for left in range(len(matrix[0])):
        for right in range(left, len(matrix[0])):
            max_sum = max(max_sum, max_sum_submatrix_for_fixed_left_right(matrix, left, right))

    return max_sum

