def binary_search_all(arr, target):
    """
    Returns a list of indexes of all occurrences of target in arr.
    """
    def find_leftmost():
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def find_rightmost():
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] <= target:
                left = mid + 1
            else:
                right = mid - 1
        return right

    left_index = find_leftmost()
    right_index = find_rightmost()

    # Verify if the target value is within the range of found indices
    if left_index <= right_index and arr[left_index] == target and arr[right_index] == target:
        return list(range(left_index, right_index + 1))
    else:
        return []

def length_of_longest_substring_two_distinct(s):
    """
    Returns the length of the longest substring that contains at most two distinct characters.
    """
    n = len(s)
    if n == 0:
        return 0
    if n == 1:
        return 1

    left, right = 0, 0
    max_len = 2  # at least two distinct characters are possible
    char_map = {}

    while right < n:
        char_map[s[right]] = char_map.get(s[right], 0) + 1
        right += 1

        if len(char_map) > 2:
            while len(char_map) > 2:
                char_map[s[left]] -= 1
                if char_map[s[left]] == 0:
                    del char_map[s[left]]
                left += 1

        max_len = max(max_len, right - left)

    return max_len

