def first_unique_character(s):
    """
    Returns the index and character of the first unique character in the string s.
    If no unique character, returns None, None.
    """
    char_count = {}
    char_index = {}

    for index, char in enumerate(s):
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
            char_index[char] = index

    unique_chars = [char for char in char_count if char_count[char] == 1]
    if not unique_chars:
        return None, None

    first_unique_char = min(unique_chars, key=lambda char: char_index[char])
    return char_index[first_unique_char], first_unique_char

def longest_substring_with_k_repeats(s, k):
    """
    Find the length of the longest substring where each character appears at least k times.

    :param s: Input string
    :param k: Minimum number of times each character must appear in the substring
    :return: Length of the longest substring
    """
    def longest_substring_helper(s, k):
        if not s:
            return 0

        count = {}
        for char in s:
            count[char] = count.get(char, 0) + 1

        for mid in range(len(s)):
            if count[s[mid]] < k:
                left = longest_substring_helper(s[:mid], k)
                right = longest_substring_helper(s[mid+1:], k)
                return max(left, right)

        return len(s)

    return longest_substring_helper(s, k)

def factorial(n):
    """
    Calculate the factorial of a non-negative integer n.
    Return -1 for negative integers as an error indicator.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    result = 1
    for i in range(1, n + 1):
        result *= i

    return result

