def fibonacci(n):
    """
    Returns the nth Fibonacci number.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b

    return b

def calculate_factorial(n):
    """
    Returns the factorial of a non-negative integer n using recursion.
    Raises a ValueError if n is not a non-negative integer.
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer")

    if n == 0 or n == 1:
        return 1

    return n * calculate_factorial(n - 1)

def fibonacci(n):
    """
    Returns the nth Fibonacci number.
    """
    if n == 0:
        return 0
    if n == 1:
        return 1

    prev, curr = 0, 1
    for _ in range(2, n + 1):
        prev, curr = curr, prev + curr

    return curr

def fibonacci(n, memo=None):
    """
    Returns the n-th Fibonacci number using recursion.

    Parameters:
    n (int): The position in the Fibonacci sequence.
    memo (dict, optional): Dictionary to store previously computed Fibonacci numbers.

    Returns:
    int: The n-th Fibonacci number.
    """
    if memo is None:
        memo = {}

    if n <= 0:
        return 0
    elif n == 1:
        return 1
    elif n in memo:
        return memo[n]

    memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo)
    return memo[n]

def fibonacci(n):
    """
    Returns the n-th number in the Fibonacci sequence.
    """
    if n <= 0:
        raise ValueError("Input should be a positive integer.")
    if n == 1:
        return 0
    if n == 2:
        return 1
    return fibonacci(n-1) + fibonacci(n-2)

