def is_path_in_tree(adj_list: dict[int, list[int]], start: int, end: int) -> bool:
    """
    Returns True if there is a path between start and end nodes in an undirected tree,
    otherwise returns False.
    """
    if start == end:
        return True

    visited = set()

    # Use Depth First Search (DFS) to find the path
    def dfs(node):
        if node in visited:
            return False
        visited.add(node)
        if node == end:
            return True
        for neighbor in adj_list.get(node, []):
            if dfs(neighbor):
                return True
        return False

    return dfs(start)

