def make_change(amount):
    """
    Given an amount of money in cents, returns a dictionary with the minimum number of coins
    (quarters, dimes, nickels, and pennies) needed to make that amount.
    """
    if amount <= 0:
        return {'quarters': 0, 'dimes': 0, 'nickels': 0, 'pennies': 0}

    change = {}
    change['quarters'], remaining = divmod(amount, 25)
    change['dimes'], remaining = divmod(remaining, 10)
    change['nickels'], remaining = divmod(remaining, 5)
    change['pennies'] = remaining

    return change

