def find_max_and_check_sorted_desc(arr):
    """
    Returns a tuple (max_num, is_sorted) where max_num is the maximum number in the array,
    and is_sorted is a boolean indicating if the array is sorted in descending order.
    """
    if not arr:
        return None, True  # An empty array has no max and is trivially sorted

    max_num = arr[0]
    is_sorted = True

    for i in range(1, len(arr)):
        if arr[i] > max_num:
            max_num = arr[i]
        if arr[i - 1] < arr[i]:
            is_sorted = False

    return max_num, is_sorted

