def count_valid_pairs(nums, target):
    """
    Returns the number of pairs (i, j) such that i < j and nums[i] + nums[j] == target.
    """
    count = 0
    seen = {}

    for i in range(len(nums)):
        complement = target - nums[i]
        if complement in seen and seen[complement] > 0:
            count += seen[complement]

        if nums[i] in seen:
            seen[nums[i]] += 1
        else:
            seen[nums[i]] = 1

    return count

