def min_operations_to_sort(arr):
    """
    Returns the minimum number of operations to sort the array using bubble sort algorithm.
    """
    n = len(arr)
    operations = 0
    for i in range(n-1):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
                operations += 1
    return operations

