def merge_and_sort_stacks(stack1, stack2):
    """
    Merges two stacks and returns a single stack in sorted order without
    using any built-in sort functions.
    """
    merged_stack = []
    while stack1 or stack2:
        if not stack1:
            merged_stack.append(stack2.pop())
        elif not stack2:
            merged_stack.append(stack1.pop())
        elif stack1[-1] <= stack2[-1]:
            merged_stack.append(stack2.pop())
        else:
            merged_stack.append(stack1.pop())

    sorted_stack = []
    while merged_stack:
        value = merged_stack.pop()
        while sorted_stack and sorted_stack[-1] > value:
            merged_stack.append(sorted_stack.pop())
        sorted_stack.append(value)

    return sorted_stack

def pig_latin(word):
    """
    Converts the given word into Pig Latin.
    If the word starts with a vowel, just add 'ay' to the end.
    If the word starts with consonants, move all the consonants leading up to the first vowel to the end and then add 'ay'.
    """
    vowels = 'aeiou'
    if word[0] in vowels:
        return word + 'ay'

    for i in range(len(word)):
        if word[i] in vowels:
            return word[i:] + word[:i] + 'ay'

    return word + 'ay'

