def determine_grade(score):
    """
    Determines the grade of a student based on the provided score.

    Parameters:
    score (int): The score you would like to evaluate.

    Returns:
    str: The grade associated with the score.
    """
    # Check if score is within valid range
    if score < 0 or score > 100:
        return "Invalid score"

    # Determine grade based on the score ranges
    if score >= 90:
        return "A"
    elif score >= 80:
        return "B"
    elif score >= 70:
        return "C"
    elif score >= 60:
        return "D"
    else:
        return "F"

