def task_func(text):
    """
    Identify all palindromic substrings of the input text and return them in a list.

    Raises:
    ValueError: If the input text is not a string.

    Returns:
    list: A list containing all unique palindromic substrings.
    """

    if not isinstance(text, str):
        raise ValueError("Input text must be a string")

    def is_palindrome(s):
        return s == s[::-1]

    palindromes = set()
    n = len(text)

    for i in range(n):
        for j in range(i + 1, n + 1):
            substring = text[i:j]
            if is_palindrome(substring):
                palindromes.add(substring)

    return list(palindromes)

