def longest_even_odd_subarray(arr: list) -> tuple:
    """
    Finds the longest subarray with equal number of even and odd integers.

    Args:
    arr (list of int): The input array of integers.

    Returns:
    tuple: (length of the subarray, start index, end index) if such a subarray is found,
           otherwise (0, -1, -1).
    """
    n = len(arr)
    max_length = 0
    start_index = -1
    end_index = -1
    prefix_sum = {0: -1}
    current_balance = 0

    for i in range(n):
        if arr[i] % 2 == 0:
            current_balance += 1
        else:
            current_balance -= 1

        if current_balance in prefix_sum:
            length = i - prefix_sum[current_balance]
            if length > max_length:
                max_length = length
                start_index = prefix_sum[current_balance] + 1
                end_index = i
        else:
            prefix_sum[current_balance] = i

    return (max_length, start_index, end_index)

