def find_maximum(lst):
    """
    Finds the maximum number in a list without using the built-in max
    function, sorting functions, or looping constructs, and returns
    an error message if the list is empty. 

    Args:
    lst: list of integers or floats

    Returns:
    The maximum number in the list or an error message if the list is empty.
    """
    if not lst:
        return "Error: The list is empty"

    def find_max_recursive(index, current_max):
        if index == len(lst):
            return current_max
        current_max = lst[index] if lst[index] > current_max else current_max
        return find_max_recursive(index + 1, current_max)

    return find_max_recursive(1, lst[0])

