def count_vowels_consonants(s):
    """
    Returns the number of vowels and consonants in the string 's'.
    The function ignores non-alphabetic characters and is case-insensitive.
    """
    vowels = 'aeiou'
    s = s.lower()
    vowel_count = 0
    consonant_count = 0

    for char in s:
        if char.isalpha():
            if char in vowels:
                vowel_count += 1
            else:
                consonant_count += 1

    return vowel_count, consonant_count

