def count_vowels(s: str) -> int:
    """
    Recursively counts the number of vowels in the string s.
    """
    vowels = "aeiou"
    s = s.lower()

    if len(s) == 0:
        return 0

    if s[0] in vowels:
        return 1 + count_vowels(s[1:])
    else:
        return count_vowels(s[1:])

