from collections import defaultdict
import heapq


def network_delay_time(times: list, n: int, k: int) -> int:
    """
    Calculate the time it takes for a signal to propagate from node k to all other nodes.
    """
    graph = defaultdict(list)

    # Build the graph
    for u, v, w in times:
        graph[u].append((v, w))

    # Min-heap to store (time, node) for Dijkstra's algorithm
    min_heap = [(0, k)]
    shortest_times = {}

    while min_heap:
        t, node = heapq.heappop(min_heap)

        if node in shortest_times:
            continue

        shortest_times[node] = t

        for neighbor, w in graph[node]:
            if neighbor not in shortest_times:
                heapq.heappush(min_heap, (t + w, neighbor))

    if len(shortest_times) == n:
        return max(shortest_times.values())

    return -1

