def is_valid(s: str) -> bool:
    """
    This function determines whether an input string represents valid, sorted, and separated data.

    The input string should consist of only 4 digits separated by either a dot (.) or a hyphen (-).
    The digits should be in ascending order.

    Args:
        s (str): The input string to be checked.

    Returns:
        bool: True if the input string is valid, False otherwise.
    """
    # Check if the string is empty
    if not s:
        return False

    # Split the string by . or -
    if '.' in s:
        parts = s.split('.')
    elif '-' in s:
        parts = s.split('-')
    else:
        return False

    # Check if there are exactly 4 parts
    if len(parts) != 4:
        return False

    # Check if all parts are digits and if they are sorted in ascending order
    for i in range(4):
        if not parts[i].isdigit():
            return False
        if i > 0 and int(parts[i]) <= int(parts[i-1]):
            return False

    return True

