def fibonacci(limit=None, max_val=None):
    """
    Generates the Fibonacci sequence.

    :param limit: An integer, the limit on the number of Fibonacci numbers to generate.
    :param max_val: An integer, the maximum value that numbers in the sequence should not exceed.
    """
    a, b = 0, 1
    count = 0

    if limit is not None and limit < 0:
        raise ValueError("The limit must be a non-negative integer.")
    if max_val is not None and max_val < 0:
        raise ValueError("The max_val must be a non-negative integer.")

    while True:
        if limit is not None and count >= limit:
            break
        if max_val is not None and a > max_val:
            break

        yield a
        a, b = b, a + b
        count += 1

def check_hydration(water_intake_liters, physical_activity_minutes):
    """
    Returns a message indicating the hydration level based on water intake and physical activity.

    Parameters:
    water_intake_liters (float): The amount of water intake in liters.
    physical_activity_minutes (int): The amount of physical activity in minutes.

    Returns:
    str: A message indicating the hydration level.
    """
    if water_intake_liters <= 0:
        return "Invalid water intake."

    if physical_activity_minutes < 0:
        return "Invalid physical activity time."

    if physical_activity_minutes == 0:
        if water_intake_liters < 2:
            return "Hydration level: Low"
        elif water_intake_liters <= 3:
            return "Hydration level: Normal"
        else:
            return "Hydration level: High"
    else:
        if water_intake_liters / physical_activity_minutes < 0.033:
            return "Hydration level: Low"
        elif water_intake_liters / physical_activity_minutes <= 0.05:
            return "Hydration level: Normal"
        else:
            return "Hydration level: High"

