from typing import List


def is_rotated_array(original: List[int], rotated: List[int]) -> bool:
    """
    Checks if the 'rotated' array is a rotation of the 'original' array.
    """
    if len(original) != len(rotated):
        return False

    if not original and not rotated:
        return True

    # Concatenate the original list with itself and check if the rotated list is a subsequence of it
    doubled = original + original
    for i in range(len(original)):
        if doubled[i:i+len(rotated)] == rotated:
            return True

    return False

