def distinct_ways_to_climb(n):
    """
    Returns the number of distinct ways to climb a staircase of n steps,
    given that you can take 1, 2, or 3 steps at a time.
    """
    if n == 1:
        return 1
    if n == 2:
        return 2
    if n == 3:
        return 4

    dp = [0] * (n + 1)
    dp[1], dp[2], dp[3] = 1, 2, 4

    for i in range(4, n + 1):
        dp[i] = dp[i-1] + dp[i-2] + dp[i-3]

    return dp[n]

def anonymize_users(users):
    """
    Takes a list of user dictionaries and anonymizes their names, filters out minors,
    and adds a 'valid_email' field indicating if the email is valid.
    """
    def is_valid_email(email):
        if '@' in email and email.split('@')[1].count('.') >= 1:
            return True
        return False

    modified_users = []
    for user in users:
        if user['age'] >= 18:
            user['name'] = '*' * len(user['name'])
            user['valid_email'] = is_valid_email(user['email'])
            modified_users.append(user)

    return modified_users

def check_winner(board):
    """
    Check if there is a winner in the tic-tac-toe game.

    Args:
    board (list of lists): 3x3 grid representing the game state

    Returns:
    bool: True if there is a winner, False otherwise
    """
    # Check rows
    for row in board:
        if row[0] == row[1] == row[2] and row[0] is not None:
            return True

    # Check columns
    for col in range(3):
        if board[0][col] == board[1][col] == board[2][col] and board[0][col] is not None:
            return True

    # Check diagonals
    if board[0][0] == board[1][1] == board[2][2] and board[0][0] is not None:
        return True
    if board[0][2] == board[1][1] == board[2][0] and board[0][2] is not None:
        return True

    return False

