def remove_tuples_with_same_first_element(tuples_list):
    """
    This function removes all the tuples from the list that have the same first element.

    Args:
        tuples_list (list): A list of tuples, where each tuple contains 2 or more elements.

    Returns:
        list: A list of tuples with unique first elements.
    """
    first_elements = {}

    for tup in tuples_list:
        if tup[0] in first_elements:
            first_elements[tup[0]] += 1
        else:
            first_elements[tup[0]] = 1

    result = [tup for tup in tuples_list if first_elements[tup[0]] == 1]

    return result

def twisted_fibonacci(a: int, b: int, n: int) -> list[int]:
    """
    Returns the first `n` numbers of a Fibonacci-like sequence starting with integers `a` and `b`.
    """
    if n == 1:
        return [a]
    elif n == 2:
        return [a, b]

    sequence = [a, b]
    for i in range(2, n):
        next_value = sequence[-1] + sequence[-2]
        sequence.append(next_value)

    return sequence

def search_matrix(matrix, target):
    """
    Search for the target integer in a sorted 2D matrix and return its position.
    If the target is not found, return (-1, -1).
    """
    if not matrix or not matrix[0]:
        return (-1, -1)

    rows, cols = len(matrix), len(matrix[0])
    row, col = 0, cols - 1  # start from the top-right corner

    while row < rows and col >= 0:
        if matrix[row][col] == target:
            return (row, col)
        elif matrix[row][col] > target:
            col -= 1  # move left
        else:
            row += 1  # move down

    return (-1, -1)

def even_integers_sorted(lst):
    """
    Returns a new list consisting of only the even integers
    from the original list, sorted in non-decreasing order.
    """
    evens = [num for num in lst if num % 2 == 0]
    # Implementing bubble sort for educational purposes
    n = len(evens)
    for i in range(n):
        for j in range(0, n-i-1):
            if evens[j] > evens[j+1]:
                evens[j], evens[j+1] = evens[j+1], evens[j]
    return evens

