from typing import List


def removeDuplicates(nums: List[int]) -> int:
    """
    Removes duplicates in-place from a sorted list of integers and returns the length of the list after duplicates have been removed.
    """
    if len(nums) == 0:
        return 0

    i = 0
    for j, num in enumerate(nums[1:], start=1):
        if num != nums[i]:
            i += 1
            nums[i] = num

    return i + 1

def fizzbuzz_list(n):
    """
    Returns a list of strings for the FizzBuzz game from 1 to n.
    """
    if n < 1:
        return []
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

