def merge_and_sort_lists(list1, list2):
    """
    Merges two lists into one sorted list without duplicates.
    """
    merged_list = list1 + list2
    unique_list = []
    for item in merged_list:
        if item not in unique_list:
            unique_list.append(item)

    # Sort the unique_list using bubble sort
    n = len(unique_list)
    for i in range(n):
        for j in range(0, n-i-1):
            if unique_list[j] > unique_list[j+1]:
                unique_list[j], unique_list[j+1] = unique_list[j+1], unique_list[j]

    return unique_list

def fibonacci_sequence(n):
    """
    Returns the first n numbers in the Fibonacci sequence and the sequence in reverse order.
    """
    if n <= 0:
        return [], []

    sequence = [0, 1][:n]  # handle edge case for n = 1

    for i in range(2, n):
        sequence.append(sequence[-1] + sequence[-2])

    return sequence, sequence[::-1]

