def n_queens(n):
    """
    Generates all possible solutions for placing n queens on an n x n chessboard.
    Each solution is represented as a list of integers, where the i-th integer
    represents the column of the queen in the i-th row.
    """
    def solve(n):
        solutions = []
        def is_safe(queens, row, col):
            for r, c in enumerate(queens):
                if c == col or abs(c - col) == abs(r - row):
                    return False
            return True

        def place_queens(row, queens):
            if row == n:
                solutions.append(queens)
                return
            for col in range(n):
                if is_safe(queens, row, col):
                    place_queens(row + 1, queens + [col])

        place_queens(0, [])
        return solutions

    return solve(n)

