def find_pair_with_difference(nums: list[int], k: int) -> bool:
    """
    Returns True if there exists a pair of distinct indices i and j such that the absolute difference
    between nums[i] and nums[j] is equal to k. Otherwise, returns False.
    """
    nums_set = set(nums)
    for num in nums:
        if (num + k) in nums_set or (num - k) in nums_set:
            # We need to check for the existence of a distinct index
            if k == 0:
                if nums.count(num) > 1:
                    return True
            else:
                return True
    return False

