def count_vowels(s):
    """
    Returns the number of vowels in the given string using recursion.

    Args:
    s (str): The input string.

    Returns:
    int: The number of vowels in the input string.
    """
    vowels = 'aeiouAEIOU'

    if len(s) == 0:
        return 0
    elif s[0] in vowels:
        return 1 + count_vowels(s[1:])
    else:
        return count_vowels(s[1:])

