def longest_palindromic_subsequence(s: str) -> int:
    """
    Computes the length of the longest palindromic subsequence in the input string s.
    """
    n = len(s)
    # Create a 2D array dp to store the lengths of palindromic subsequences.
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Each character on its own is a palindrome of length 1.
    for i in range(n):
        dp[i][i] = 1

    # Fill the dp array.
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and length == 2:
                dp[i][j] = 2
            elif s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]

