def has_zero_sum_subarray(nums, k):
    """
    Checks if the list contains a subarray of at least length k that has a sum equal to zero.
    """
    n = len(nums)
    for i in range(n):
        curr_sum = 0
        for j in range(i, n):
            curr_sum += nums[j]
            if j - i + 1 >= k and curr_sum == 0:
                return True
    return False

