def evaluate_expression(expression):
    """
    Parses and evaluates a simple mathematical expression given as a string.
    Supports integer numbers, addition (+), and multiplication (*), with
    proper handling of operator precedence and parentheses.
    """
    def parse_expr(tokens):
        def parse_term(tokens):
            token = tokens.pop(0)
            if token == '(':
                expr_value = parse_expr(tokens)
                tokens.pop(0)  # Remove closing parenthesis
                return expr_value
            else:
                return int(token)

        def parse_factor(tokens):
            term_value = parse_term(tokens)
            while tokens and tokens[0] == '*':
                tokens.pop(0)
                term_value *= parse_term(tokens)
            return term_value

        expr_value = parse_factor(tokens)
        while tokens and tokens[0] == '+':
            tokens.pop(0)
            expr_value += parse_factor(tokens)

        return expr_value

    tokens = []
    i = 0
    while i < len(expression):
        if expression[i] in '0123456789':
            j = i
            while j < len(expression) and expression[j] in '0123456789':
                j += 1
            tokens.append(expression[i:j])
            i = j
        elif expression[i] in '+*()':
            tokens.append(expression[i])
            i += 1
        else:
            i += 1  # Ignore whitespace
    return parse_expr(tokens)

