def count_vowels_and_consonants(sentence):
    """
    Returns the number of vowels and consonants as a tuple (vowels, consonants) in the given sentence.
    """
    vowels = set("aeiouAEIOU")
    vowel_count = 0
    consonant_count = 0

    for char in sentence:
        if char.isalpha():
            if char in vowels:
                vowel_count += 1
            else:
                consonant_count += 1

    return (vowel_count, consonant_count)

